fn closeout_worktree_candidate_authorizes_hygiene_preflight(
    report: &CloseoutWorktreeReport,
    candidate: &CloseoutWorktreeReportCandidate,
    _program_run_id: &str,
    state: &ProgramChildPlanState,
    route_id: &str,
    classifier_output_ref: &str,
    classifier_output_digest: &str,
    foreign_fingerprint: Option<&str>,
) -> bool {
    let Some(auth) = candidate.proposal_program_handoff_authorization.as_ref() else {
        return false;
    };
    let authorized_or_outside_scope = auth
        .authorization_grant
        .as_deref()
        .is_some_and(|grant| !grant.trim().is_empty())
        || (auth.outside_child_route_write_scope == Some(true)
            && auth
                .authorized_paths
                .iter()
                .all(|path| !path_is_under_or_equal(path, &state.target)));
    let final_state = report
        .final_candidate_dispositions
        .get(&candidate.candidate_id)
        .map(|disposition| disposition.state.as_str());
    let matching_fingerprint = foreign_fingerprint
        .map(|fingerprint| {
            auth.authorized_foreign_fingerprint == fingerprint
                && auth.foreign_fingerprint.as_deref().unwrap_or(fingerprint) == fingerprint
        })
        .unwrap_or(false);
    let classifier_ref_matches = auth.classifier_output_ref == classifier_output_ref;
    let classifier_digest_matches = auth.classifier_output_digest == classifier_output_digest;
    let classifier_snapshot_matches = classifier_ref_matches && classifier_digest_matches;
    let current_fingerprint_matches =
        matching_fingerprint || (foreign_fingerprint.is_none() && classifier_snapshot_matches);
    authorized_or_outside_scope
        && auth.child_id == state.child_id
        && auth.route_id == route_id
        && current_fingerprint_matches
        && auth.disposition == "preserve-and-exclude-from-child-closeout-blocking"
        && auth.non_mutating == Some(true)
        && auth.preserve_and_exclude_from_child_closeout_blocking == Some(true)
        && auth.parent_summary_not_child_closeout_receipt == Some(true)
        && auth.child_closeout_authority_preserved == Some(true)
        && closeout_worktree_handoff_forbidden_actions_are_all_false(&auth.forbidden_actions)
        && candidate.residue_routing_class == "foreign_manual_review"
        && candidate.disposition == "foreign"
        && final_state == Some("foreign")
        && path_sets_equal(&candidate.boundaries.include_paths, &auth.authorized_paths)
}

fn closeout_worktree_candidate_authorizes_selected_closeout_route(
    repo_root: &Path,
    report: &CloseoutWorktreeReport,
    candidate: &CloseoutWorktreeReportCandidate,
    _program_run_id: &str,
    state: &ProgramChildPlanState,
    route_id: &str,
    foreign_fingerprint: Option<&str>,
) -> Result<bool> {
    let Some(auth) = candidate.proposal_program_handoff_authorization.as_ref() else {
        return Ok(false);
    };
    let authorized_or_outside_scope = auth
        .authorization_grant
        .as_deref()
        .is_some_and(|grant| !grant.trim().is_empty())
        || (auth.outside_child_route_write_scope == Some(true)
            && auth
                .authorized_paths
                .iter()
                .all(|path| !path_is_under_or_equal(path, &state.target)));
    let final_state = report
        .final_candidate_dispositions
        .get(&candidate.candidate_id)
        .map(|disposition| disposition.state.as_str());
    let matching_fingerprint = foreign_fingerprint
        .map(|fingerprint| {
            auth.authorized_foreign_fingerprint == fingerprint
                && auth.foreign_fingerprint.as_deref().unwrap_or(fingerprint) == fingerprint
        })
        .unwrap_or(false);
    if !(authorized_or_outside_scope
        && auth.child_id == state.child_id
        && auth.route_id == route_id
        && matching_fingerprint
        && auth.disposition == "preserve-and-exclude-from-child-closeout-blocking"
        && auth.non_mutating == Some(true)
        && auth.preserve_and_exclude_from_child_closeout_blocking == Some(true)
        && auth.parent_summary_not_child_closeout_receipt == Some(true)
        && auth.child_closeout_authority_preserved == Some(true)
        && closeout_worktree_handoff_forbidden_actions_are_all_false(&auth.forbidden_actions)
        && candidate.residue_routing_class == "foreign_manual_review"
        && candidate.disposition == "foreign"
        && final_state == Some("foreign")
        && path_sets_equal(&candidate.boundaries.include_paths, &auth.authorized_paths)
        && is_safe_repo_relative(&auth.classifier_output_ref))
    {
        return Ok(false);
    }
    let classifier_path = repo_root.join(&auth.classifier_output_ref);
    if !classifier_path.is_file() {
        return Ok(false);
    }
    let classifier_digest_matches = file_digest(&classifier_path)? == auth.classifier_output_digest;
    let classifier_fingerprint_matches = closeout_worktree_classifier_fingerprint_matches(
        &classifier_path,
        &auth.authorized_foreign_fingerprint,
    )?;
    Ok(classifier_digest_matches || classifier_fingerprint_matches)
}

fn closeout_worktree_candidate_authorizes_lifecycle_residue_closeout(
    repo_root: &Path,
    report: &CloseoutWorktreeReport,
    candidate: &CloseoutWorktreeReportCandidate,
    program_run_id: &str,
    _route_id: &str,
    cleanup_receipt: &ReceiptState,
) -> Result<bool> {
    let Some(auth) = candidate
        .proposal_program_parent_handoff_authorization
        .as_ref()
    else {
        return Ok(false);
    };
    let final_state = report
        .final_candidate_dispositions
        .get(&candidate.candidate_id)
        .map(|disposition| disposition.state.as_str());
    let cleanup_receipt_ref = rel_display(repo_root, &cleanup_receipt.path_abs);
    if auth
        .authorization_grant
        .as_deref()
        .map(|grant| grant.trim().is_empty())
        .unwrap_or(true)
        || auth.program_run_id != program_run_id
        || auth.parent_route_id != ROUTE_ID_CLEANUP_LIFECYCLE_RESIDUE
        || auth.cleanup_receipt_ref != cleanup_receipt_ref
        || !lifecycle_residue_cleanup_deletion_phase_completed(cleanup_receipt)
        || auth.disposition != "preserve-and-exclude-from-lifecycle-closeout-blocking"
        || auth.non_mutating != Some(true)
        || auth.preserve_and_exclude_from_lifecycle_closeout_blocking != Some(true)
        || auth.parent_summary_not_child_closeout_receipt != Some(true)
        || auth.child_closeout_authority_preserved != Some(true)
        || auth.parent_evidence_replaces_child_evidence == Some(true)
        || !(auth.outside_child_owned_closeout_authority == Some(true)
            || auth.separately_partitioned_for_later_legal_closeout == Some(true))
        || candidate.residue_routing_class != "foreign_manual_review"
        || candidate.disposition != "foreign"
        || final_state != Some("foreign")
        || !path_sets_equal(&candidate.boundaries.include_paths, &auth.authorized_paths)
        || !auth
            .authorized_paths
            .iter()
            .all(|path| is_safe_repo_relative(path))
    {
        return Ok(false);
    }
    if !parent_handoff_forbidden_actions_are_all_false(&auth.forbidden_actions) {
        return Ok(false);
    }
    if auth
        .foreign_fingerprint
        .as_deref()
        .unwrap_or(auth.authorized_foreign_fingerprint.as_str())
        != auth.authorized_foreign_fingerprint
    {
        return Ok(false);
    }
    if !closeout_worktree_parent_handoff_stable_fields_match(auth, cleanup_receipt) {
        return Ok(false);
    }
    if !is_safe_repo_relative(&auth.classifier_output_ref) {
        return Ok(false);
    }
    let classifier_path = repo_root.join(&auth.classifier_output_ref);
    if !classifier_path.is_file() {
        return Ok(false);
    }
    let classifier_digest_matches = file_digest(&classifier_path)? == auth.classifier_output_digest;
    let classifier_fingerprint_matches = closeout_worktree_classifier_fingerprint_matches(
        &classifier_path,
        &auth.authorized_foreign_fingerprint,
    )?;
    Ok(classifier_digest_matches || classifier_fingerprint_matches)
}

fn lifecycle_residue_cleanup_deletion_phase_completed(cleanup_receipt: &ReceiptState) -> bool {
    if !cleanup_receipt.exists || !cleanup_receipt.missing_required_fields.is_empty() {
        return false;
    }
    if cleanup_receipt
        .fields
        .get("cleanup_candidates")
        .map(|value| value.trim() == "0")
        != Some(true)
    {
        return false;
    }
    if cleanup_receipt
        .fields
        .get("implementation_blocking")
        .map(|value| receipt_bool_is_true(value))
        .unwrap_or(false)
    {
        return false;
    }
    let route_completed = cleanup_receipt
        .fields
        .get("cleaned_at")
        .is_some_and(|value| !value.trim().is_empty())
        || cleanup_receipt
            .fields
            .get("verdict")
            .is_some_and(|value| matches!(value.trim(), "pass" | "blocked-retained"));
    if !route_completed {
        return false;
    }
    let deletion_occurred = [
        "deletion_performed",
        "cleanup_deletion_performed",
        "repo_hygiene_cleanup_performed",
    ]
    .iter()
    .any(|field| {
        cleanup_receipt
            .fields
            .get(*field)
            .map(|value| receipt_bool_is_true(value))
            .unwrap_or(false)
    });
    if deletion_occurred
        && ![
            "deletion_evidence_digest",
            "repo_hygiene_cleanup_receipt_digest",
            "cleanup_authorization_digest",
        ]
        .iter()
        .any(|field| cleanup_receipt_field_nonempty(cleanup_receipt, field))
    {
        return false;
    }
    true
}

fn closeout_worktree_parent_handoff_stable_fields_match(
    auth: &CloseoutWorktreeParentHandoffAuthorization,
    cleanup_receipt: &ReceiptState,
) -> bool {
    let mut worktree_foreign_fingerprint_matched = false;
    if let Some(worktree_fingerprint) = cleanup_receipt
        .fields
        .get("worktree_hygiene_foreign_fingerprint")
    {
        if auth.authorized_foreign_fingerprint != *worktree_fingerprint
            || auth
                .foreign_fingerprint
                .as_deref()
                .unwrap_or(auth.authorized_foreign_fingerprint.as_str())
                != worktree_fingerprint
        {
            return false;
        }
        worktree_foreign_fingerprint_matched = true;
    } else if let Some(residue_fingerprint) = cleanup_receipt.fields.get("residue_fingerprint") {
        if auth
            .residue_fingerprint
            .as_deref()
            .unwrap_or(auth.authorized_foreign_fingerprint.as_str())
            != residue_fingerprint
        {
            return false;
        }
    }
    if !worktree_foreign_fingerprint_matched {
        if let (Some(auth_residue_fingerprint), Some(receipt_residue_fingerprint)) = (
            auth.residue_fingerprint.as_deref(),
            cleanup_receipt
                .fields
                .get("residue_fingerprint")
                .map(String::as_str),
        ) {
            if auth_residue_fingerprint != receipt_residue_fingerprint {
                return false;
            }
        }
    }
    if let Some(digest) = auth.cleanup_candidates_digest.as_deref() {
        let observed = cleanup_receipt
            .fields
            .get("cleanup_candidates")
            .map(|value| stable_text_digest(&format!("cleanup_candidates={}", value.trim())));
        if observed.as_deref() != Some(digest) {
            return false;
        }
    }
    if let Some(digest) = auth.authorized_path_set_digest.as_deref() {
        let observed = stable_path_set_digest(&auth.authorized_paths);
        if observed.as_deref() != Some(digest) {
            return false;
        }
    }
    let cleanup_candidates_zero = cleanup_receipt
        .fields
        .get("cleanup_candidates")
        .is_some_and(|value| value.trim() == "0");
    if worktree_foreign_fingerprint_matched && cleanup_candidates_zero {
        return true;
    }
    optional_cleanup_digest_field_matches(
        cleanup_receipt,
        auth.repo_hygiene_cleanup_receipt_digest.as_deref(),
        &[
            "repo_hygiene_cleanup_receipt_digest",
            "repo_hygiene_cleanup_digest",
        ],
    ) && optional_cleanup_digest_field_matches(
        cleanup_receipt,
        auth.cleanup_authorization_digest.as_deref(),
        &[
            "cleanup_authorization_digest",
            "repo_hygiene_cleanup_authorization_digest",
        ],
    ) && optional_cleanup_digest_field_matches(
        cleanup_receipt,
        auth.post_cleanup_summary_digest.as_deref(),
        &["post_cleanup_summary_digest", "post_cleanup_digest"],
    )
}

fn cleanup_receipt_field_nonempty(cleanup_receipt: &ReceiptState, field: &str) -> bool {
    cleanup_receipt
        .fields
        .get(field)
        .is_some_and(|value| !value.trim().is_empty())
}

fn optional_cleanup_digest_field_matches(
    cleanup_receipt: &ReceiptState,
    auth_digest: Option<&str>,
    fields: &[&str],
) -> bool {
    let observed = fields.iter().find_map(|field| {
        cleanup_receipt
            .fields
            .get(*field)
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
    });
    match observed {
        Some(observed) => auth_digest == Some(observed),
        None => true,
    }
}

fn stable_path_set_digest(paths: &[String]) -> Option<String> {
    if paths.is_empty() {
        return None;
    }
    let mut normalized = paths
        .iter()
        .map(|path| path.trim().trim_start_matches("./").to_string())
        .filter(|path| !path.is_empty())
        .collect::<Vec<_>>();
    normalized.sort();
    Some(stable_text_digest(&normalized.join("\n")))
}

fn closeout_worktree_handoff_forbidden_actions_are_all_false(
    actions: &BTreeMap<String, bool>,
) -> bool {
    const FORBIDDEN_CLAIMS: &[&str] = &[
        "deletion",
        "reset",
        "staging",
        "commit",
        "push",
        "publication",
        "archive",
        "branch_cleanup",
        "git_ref_mutation",
        "cleaned_claim",
    ];
    FORBIDDEN_CLAIMS
        .iter()
        .all(|action| actions.get(*action) != Some(&true))
        && !actions.values().any(|performed| *performed)
}

fn parent_handoff_forbidden_actions_are_all_false(actions: &BTreeMap<String, bool>) -> bool {
    const REQUIRED_FALSE_ACTIONS: &[&str] = &[
        "deletion",
        "reset",
        "staging",
        "commit",
        "push",
        "publication",
        "archive",
        "branch_cleanup",
        "git_ref_mutation",
        "cleaned_claim",
    ];
    REQUIRED_FALSE_ACTIONS
        .iter()
        .all(|action| actions.get(*action) == Some(&false))
        && !actions.values().any(|performed| *performed)
}

fn closeout_worktree_classifier_fingerprint_matches(
    classifier_path: &Path,
    expected_foreign_fingerprint: &str,
) -> Result<bool> {
    let classifier_bytes = fs::read(classifier_path)?;
    if let Ok(value) = serde_yaml::from_slice::<serde_yaml::Value>(&classifier_bytes) {
        if value
            .get("worktree_hygiene_foreign_fingerprint")
            .and_then(|value| value.as_str())
            == Some(expected_foreign_fingerprint)
        {
            return Ok(true);
        }
    }
    let classifier_body = String::from_utf8_lossy(&classifier_bytes);
    Ok(
        terminal_markdown_foreign_fingerprint(&classifier_body).as_deref()
            == Some(expected_foreign_fingerprint),
    )
}

fn terminal_markdown_foreign_fingerprint(body: &str) -> Option<String> {
    let rows = terminal_markdown_foreign_paths(body);
    if rows.is_empty() {
        return None;
    }
    Some(sha256_digest(rows.join("\n").as_bytes()))
}

fn path_sets_equal(left: &[String], right: &[String]) -> bool {
    if left.is_empty() || right.is_empty() {
        return false;
    }
    left.iter().collect::<BTreeSet<_>>() == right.iter().collect::<BTreeSet<_>>()
}

fn path_is_under_or_equal(path: &str, base: &str) -> bool {
    path == base
        || path
            .strip_prefix(base)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn selected_route_for_child_execution(
    octon_dir: &Path,
    options: &RunLifecycleOptions,
    state: &ProgramChildPlanState,
    approvals: Option<&Vec<ProgramApprovalGrant>>,
    registry_digest: &str,
) -> Result<(Option<RoutePlanState>, Option<String>)> {
    let loaded = load_lifecycle_contract(octon_dir, &options.lifecycle_id)?;
    let Some(program) = loaded.contract.program.as_ref() else {
        return Ok((state.selected_route.clone(), None));
    };
    let unresolved_authority_blocker = unresolved_child_authority_blocker(program, state);
    let Some(blocker) = state.blockers.iter().find(|blocker| {
        recovery_route_for_blocker(program, blocker).is_some()
            && !matches!(
                blocker.blocker_class.as_str(),
                "authority-ambiguity" | "policy-override"
            )
            && (unresolved_authority_blocker.is_none()
                || matches!(
                    classify_program_blocker_class(&blocker.blocker_class),
                    ProgramBlockerDisposition::Human | ProgramBlockerDisposition::Unsafe
                ))
    }) else {
        if let Some(blocker) = unresolved_authority_blocker {
            return Ok((None, Some(blocker.blocker_class.clone())));
        }
        return Ok((state.selected_route.clone(), None));
    };
    if blocker_non_recoverable(&blocker.blocker_class)
        && !blocker_has_safe_agent_repair(program, blocker)
    {
        return Ok((None, Some(blocker.blocker_class.clone())));
    }
    validate_recovery_recipe(program, &blocker.blocker_class, state)?;
    let route_id =
        recovery_route_id(program, &blocker.blocker_class).or(blocker.recovery_route.as_ref());
    let Some(route_id) = route_id else {
        return Ok((state.selected_route.clone(), None));
    };
    let approval_granted = approval_granted(
        approvals,
        &state.child_id,
        route_id,
        Some(registry_digest),
        Some(&blocker.blocker_class),
    );
    let delegation_safe = options.invocation_authority == "unattended"
        && recovery_delegation_contract_basis(Some(program), &blocker.blocker_class).is_some();
    if recovery_requires_approval(program, &blocker.blocker_class)
        && !approval_granted
        && !delegation_safe
    {
        return Ok((None, Some(blocker.blocker_class.clone())));
    }
    let child_contract = load_lifecycle_contract(octon_dir, &state.child_lifecycle_id)?;
    if let Some(route) = route_by_id(&child_contract.contract, route_id) {
        Ok((
            Some(route_plan_state(route.clone())),
            Some(blocker.blocker_class.clone()),
        ))
    } else if let Some(fallback_route) = blocker.recovery_route.as_ref() {
        let route = route_by_id(&child_contract.contract, fallback_route).with_context(|| {
            format!("recovery route missing from child lifecycle: {fallback_route}")
        })?;
        Ok((
            Some(route_plan_state(route.clone())),
            Some(blocker.blocker_class.clone()),
        ))
    } else {
        Ok((
            state.selected_route.clone(),
            Some(blocker.blocker_class.clone()),
        ))
    }
}

fn unresolved_child_authority_blocker<'a>(
    program: &ProgramSpec,
    state: &'a ProgramChildPlanState,
) -> Option<&'a ProgramBlocker> {
    state.blockers.iter().find(|blocker| {
        !closeout_hygiene_handoff_preflight_allowed(state, blocker)
            && !matches!(
                blocker.blocker_class.as_str(),
                "authority-ambiguity" | "policy-override"
            )
            && matches!(
                classify_program_blocker_class(&blocker.blocker_class),
                ProgramBlockerDisposition::Human | ProgramBlockerDisposition::Unsafe
            )
            && !blocker_has_safe_agent_repair(program, blocker)
    })
}

fn unsafe_repair_evidence_for_job(
    program_run_id: &str,
    state: &ProgramChildPlanState,
    blocker_class: &str,
    route_id: &str,
    delegation_contract_basis: Option<&str>,
    child_evidence_root: &Path,
) -> Option<ProgramUnsafeRepairEvidence> {
    if classify_program_blocker_class(blocker_class) != ProgramBlockerDisposition::Unsafe {
        return None;
    }
    let authority_basis = delegation_contract_basis?;
    let unsafe_condition = state
        .blockers
        .iter()
        .find(|blocker| blocker.blocker_class == blocker_class)
        .map(|blocker| blocker.message.clone())
        .unwrap_or_else(|| format!("unsafe blocker {blocker_class}"));
    Some(ProgramUnsafeRepairEvidence {
        schema_version: "octon-program-lifecycle-unsafe-repair-v2".to_string(),
        program_run_id: program_run_id.to_string(),
        repair_scope: "child".to_string(),
        blocker_scope: "child".to_string(),
        child_id: state.child_id.clone(),
        unsafe_condition,
        original_route_blocked_reason: format!(
            "current route or action for {blocker_class} must not continue as-is"
        ),
        selected_repair_route: route_id.to_string(),
        agent_authority_basis: authority_basis.to_string(),
        files_artifacts_changed: vec![rel_path_string(child_evidence_root)],
        before_validation:
            "unsafe blocker selected for governed repair before child route dispatch".to_string(),
        after_validation: "pending repair route execution".to_string(),
        safe_continuation_available: true,
        route_execution_status: "pending".to_string(),
        recipe_validation_status: "passed".to_string(),
        recipe_validation_failures: Vec::new(),
        post_attempt_validations_declared: Vec::new(),
        post_attempt_validation_results: Vec::new(),
        resume_decision_basis: "pending post-attempt validation".to_string(),
        post_attempt_validation_status: "pending".to_string(),
        post_attempt_validation_failures: Vec::new(),
        final_blocker_class: Some(blocker_class.to_string()),
        final_execution_can_resume: false,
        execution_can_resume: false,
    })
}

fn unsafe_repair_evidence_for_program_route(
    program_run_id: &str,
    program: &ProgramSpec,
    plan: &ProgramLifecyclePlanResult,
    route_id: &str,
    parent_evidence_root: &Path,
) -> Option<ProgramUnsafeRepairEvidence> {
    let blocker = plan.program_blockers.iter().find(|blocker| {
        classify_program_blocker_class(&blocker.blocker_class) == ProgramBlockerDisposition::Unsafe
            && recovery_route_for_blocker(program, blocker) == Some(route_id)
    })?;
    let authority_basis =
        program_repair_delegation_contract_basis(program, &blocker.blocker_class)?;
    let declared_validations = recovery_post_attempt_validations(program, &blocker.blocker_class);
    Some(ProgramUnsafeRepairEvidence {
        schema_version: "octon-program-lifecycle-unsafe-repair-v2".to_string(),
        program_run_id: program_run_id.to_string(),
        repair_scope: "program".to_string(),
        blocker_scope: "program".to_string(),
        child_id: "program".to_string(),
        unsafe_condition: blocker.message.clone(),
        original_route_blocked_reason: format!(
            "program route or action for {} must not continue as-is",
            blocker.blocker_class
        ),
        selected_repair_route: route_id.to_string(),
        agent_authority_basis: authority_basis,
        files_artifacts_changed: vec![rel_path_string(parent_evidence_root)],
        before_validation:
            "unsafe program blocker selected for governed repair before parent route dispatch"
                .to_string(),
        after_validation: "pending repair route execution".to_string(),
        safe_continuation_available: true,
        route_execution_status: "pending".to_string(),
        recipe_validation_status: plan
            .program_recovery_recipe_validation_status
            .clone()
            .unwrap_or_else(|| "passed".to_string()),
        recipe_validation_failures: plan.program_recovery_recipe_validation_failures.clone(),
        post_attempt_validations_declared: declared_validations,
        post_attempt_validation_results: Vec::new(),
        resume_decision_basis: "pending post-attempt validation".to_string(),
        post_attempt_validation_status: "pending".to_string(),
        post_attempt_validation_failures: Vec::new(),
        final_blocker_class: Some(blocker.blocker_class.clone()),
        final_execution_can_resume: false,
        execution_can_resume: false,
    })
}

fn program_child_approval_context(
    program_run_id: &str,
    child_id: &str,
    _child_run_id: &str,
    _child_lifecycle_id: &str,
    _child_target: &str,
    route_id: &str,
) -> LifecycleHumanBoundaryContext {
    LifecycleHumanBoundaryContext {
        context_kind: "program-child-route".to_string(),
        program_run_id: Some(program_run_id.to_string()),
        child_id: Some(child_id.to_string()),
        human_exception_instruction: Some(format!(
            "record typed human exception grant for program child route {child_id}:{route_id}"
        )),
        retry_instruction: Some(format!(
            "octon lifecycle program retry --run-id {program_run_id} --child {child_id}"
        )),
    }
}

fn recovery_route_id<'a>(program: &'a ProgramSpec, blocker_class: &str) -> Option<&'a String> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .and_then(|recipe| recipe.recovery_route_id.as_ref())
        .or_else(|| {
            program
                .recovery_policy
                .handlers
                .get(blocker_class)
                .and_then(|handler| handler.recovery_route_id.as_ref())
        })
}

fn recovery_action_id<'a>(program: &'a ProgramSpec, blocker_class: &str) -> Option<&'a String> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .and_then(|recipe| recipe.recovery_action_id.as_ref())
}

fn child_results_have_publication_post_validation_failure(
    child_results: &[ProgramChildExecutionSummary],
) -> bool {
    child_results.iter().any(|result| {
        result.blocker_class.as_deref() == Some("publication-drift")
            && result.status == "failed"
            && result
                .error_message
                .as_deref()
                .map(|message| {
                    message
                        .contains("recovery post-attempt validation failed for publication-drift")
                        && message.contains("publication-freshness-cleared")
                })
                .unwrap_or(false)
    })
}

fn recovery_route_for_blocker<'a>(
    program: &'a ProgramSpec,
    blocker: &'a ProgramBlocker,
) -> Option<&'a str> {
    blocker
        .recovery_route
        .as_deref()
        .or_else(|| recovery_route_id(program, &blocker.blocker_class).map(String::as_str))
}

fn recovery_recipe_for_blocker<'a>(
    program: &'a ProgramSpec,
    blocker_class: &str,
) -> Option<&'a ProgramRecoveryRecipeSpec> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
}

fn recovery_delegation_contract_basis(
    program: Option<&ProgramSpec>,
    blocker_class: &str,
) -> Option<String> {
    if blocker_class == "recovery-budget-exhausted-alternate-route" {
        return Some(
            "budget exhausted for one recovery route; selected alternate was preclassified safe"
                .to_string(),
        );
    }
    let program = program?;
    let recipe = recovery_recipe_for_blocker(program, blocker_class)?;
    if let Some(route_id) = recipe.recovery_route_id.as_deref() {
        if program_recovery_route_material_side_effect(route_id).is_some() {
            return None;
        }
    }
    if let Some(action_id) = recipe.recovery_action_id.as_deref() {
        if validate_autonomous_recovery_envelope_action(program, blocker_class, action_id).is_err()
        {
            return None;
        }
    }
    let idempotency_class = recipe.idempotency_class.as_deref()?;
    delegated_replay_class(idempotency_class).then(|| {
        format!(
            "recovery recipe {} idempotency_class={idempotency_class}",
            recipe.blocker_class
        )
    })
}

fn delegated_replay_class(idempotency_class: &str) -> bool {
    matches!(
        idempotency_class,
        "inspect-only" | "idempotent" | "idempotent-rerun" | "bounded-retry" | "no-op-safe"
    )
}

fn lifecycle_route_delegation_contract_basis(
    octon_dir: &Path,
    lifecycle_id: &str,
    route_id: &str,
) -> Result<Option<String>> {
    let loaded = load_lifecycle_contract(octon_dir, lifecycle_id)?;
    Ok(route_by_id(&loaded.contract, route_id)
        .and_then(|route| route_spec_delegation_contract_basis(route_id, route)))
}

fn route_spec_delegation_contract_basis(route_id: &str, route: &RouteSpec) -> Option<String> {
    let contract = route.delegation_contract.as_ref()?;
    if contract.decision_class == "delegated-execution"
        && contract.safe_delegation
        && delegated_replay_class(&contract.replay_class)
    {
        Some(format!(
            "route {route_id} delegation_contract.safe_delegation=true replay_class={}",
            contract.replay_class
        ))
    } else {
        None
    }
}

fn recovery_attempt_budget(program: &ProgramSpec, blocker_class: &str) -> Option<u32> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .and_then(|recipe| recipe.retry_budget)
        .or_else(|| {
            program
                .recovery_policy
                .handlers
                .get(blocker_class)
                .and_then(|handler| handler.max_attempts)
        })
}

fn recovery_requires_approval(program: &ProgramSpec, blocker_class: &str) -> bool {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .map(|recipe| recipe.human_required)
        .or_else(|| {
            program
                .recovery_policy
                .handlers
                .get(blocker_class)
                .map(|handler| handler.human_required)
        })
        .unwrap_or(false)
}

fn recovery_dependent_handling(program: &ProgramSpec, blocker_class: &str) -> Option<String> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .and_then(|recipe| recipe.dependent_handling.clone())
}

fn recovery_replan_after_attempt(program: &ProgramSpec, blocker_class: &str) -> bool {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .and_then(|recipe| recipe.replan_behavior.as_deref())
        .map(|behavior| behavior == "always" || behavior == "after-attempt")
        .or_else(|| {
            program
                .recovery_policy
                .handlers
                .get(blocker_class)
                .map(|handler| handler.replan_after_attempt)
        })
        .unwrap_or(false)
}

fn blocker_non_recoverable(blocker_class: &str) -> bool {
    classify_program_blocker_class(blocker_class) != ProgramBlockerDisposition::Recoverable
}

fn recovery_attempt_key(child_id: &str, blocker_class: &str) -> String {
    format!("{child_id}:{blocker_class}")
}

fn recovery_progress_key(child_id: &str, route_id: &str, blocker_class: &str) -> String {
    format!("{child_id}:{route_id}:{blocker_class}")
}

fn child_progress_fingerprint(
    state: &ProgramChildPlanState,
    route_id: &str,
    blocker_class: &str,
) -> ProgramRecoveryProgressFingerprint {
    ProgramRecoveryProgressFingerprint {
        child_id: state.child_id.clone(),
        route_id: route_id.to_string(),
        blocker_class: blocker_class.to_string(),
        final_verdict: state.final_verdict.clone(),
        terminal_outcome: state.terminal_outcome.clone(),
        gate_status: state.gate_status.clone(),
        receipt_digests: state.receipt_digests.clone(),
        selected_route_id: state
            .selected_route
            .as_ref()
            .map(|route| route.route_id.clone()),
    }
}

fn recovery_attempt_count(
    checkpoint: &ProgramLifecycleCheckpoint,
    child_id: &str,
    blocker_class: &str,
) -> u32 {
    checkpoint
        .recovery_attempts
        .get(&recovery_attempt_key(child_id, blocker_class))
        .copied()
        .unwrap_or(0)
}

fn program_recovery_action_attempt_key(blocker_class: &str, action_id: &str) -> String {
    format!("{blocker_class}:{action_id}")
}

fn program_recovery_action_attempt_key_for_fingerprint(
    blocker_class: &str,
    action_id: &str,
    condition_fingerprint: &str,
) -> String {
    format!("{blocker_class}:{action_id}:{condition_fingerprint}")
}

fn program_recovery_action_attempt_key_for_plan(
    blocker_class: &str,
    action_id: &str,
    plan: &ProgramLifecyclePlanResult,
) -> String {
    program_recovery_action_condition_fingerprint(blocker_class, action_id, plan)
        .map(|fingerprint| {
            program_recovery_action_attempt_key_for_fingerprint(
                blocker_class,
                action_id,
                &fingerprint,
            )
        })
        .unwrap_or_else(|| program_recovery_action_attempt_key(blocker_class, action_id))
}

fn program_recovery_action_attempt_key_for_blocker(
    blocker_class: &str,
    action_id: &str,
    blocker: &ProgramBlocker,
) -> String {
    if blocker_class == "publication-drift" && action_id == REFRESH_PUBLICATION_PROJECTIONS_ACTION {
        if let Some(fingerprint) =
            publication_freshness_digest_from_blocker_message(&blocker.message)
        {
            return program_recovery_action_attempt_key_for_fingerprint(
                blocker_class,
                action_id,
                &fingerprint,
            );
        }
    }
    program_recovery_action_attempt_key(blocker_class, action_id)
}

fn program_recovery_action_condition_fingerprint(
    blocker_class: &str,
    action_id: &str,
    plan: &ProgramLifecyclePlanResult,
) -> Option<String> {
    if blocker_class != "publication-drift" || action_id != REFRESH_PUBLICATION_PROJECTIONS_ACTION {
        return None;
    }
    publication_freshness_digest_from_plan(plan)
}

fn publication_freshness_digest_from_plan(plan: &ProgramLifecyclePlanResult) -> Option<String> {
    plan.program_blockers
        .iter()
        .chain(
            plan.child_states
                .values()
                .flat_map(|state| state.blockers.iter()),
        )
        .filter(|blocker| blocker.blocker_class == "publication-drift")
        .find_map(|blocker| publication_freshness_digest_from_blocker_message(&blocker.message))
        .or_else(|| {
            let mut publication_blockers = plan
                .child_states
                .values()
                .filter(|state| {
                    state
                        .blockers
                        .iter()
                        .any(|blocker| blocker.blocker_class == "publication-drift")
                })
                .map(|state| {
                    child_progress_fingerprint(
                        state,
                        state
                            .selected_route
                            .as_ref()
                            .map(|route| route.route_id.as_str())
                            .unwrap_or("none"),
                        "publication-drift",
                    )
                })
                .collect::<Vec<_>>();
            if publication_blockers.is_empty() {
                return None;
            }
            publication_blockers.sort_by(|left, right| left.child_id.cmp(&right.child_id));
            serializable_digest(&publication_blockers).ok()
        })
}

fn publication_freshness_digest_from_blocker_message(message: &str) -> Option<String> {
    message
        .split_whitespace()
        .find_map(|part| part.strip_prefix("publication_freshness_digest="))
        .map(|value| value.trim_end_matches(';').to_string())
        .filter(|value| !value.is_empty())
}

fn publication_freshness_evidence_digest_from_parts(
    passed: bool,
    stdout: &[u8],
    stderr: &[u8],
    exit_code: i32,
) -> String {
    stable_text_digest(&format!(
        "status={}\nexit_code={exit_code}\nstdout={}\nstderr={}",
        if passed { "pass" } else { "blocked" },
        sha256_digest(stdout),
        sha256_digest(stderr)
    ))
}

fn program_recovery_action_attempt_count_for_plan(
    checkpoint: Option<&ProgramLifecycleCheckpoint>,
    blocker_class: &str,
    action_id: &str,
    plan: &ProgramLifecyclePlanResult,
) -> u32 {
    let Some(checkpoint) = checkpoint else {
        return 0;
    };
    let key = program_recovery_action_attempt_key_for_plan(blocker_class, action_id, plan);
    checkpoint
        .program_recovery_action_attempts
        .get(&key)
        .copied()
        .unwrap_or(0)
}

fn program_recovery_action_attempt_count_for_blocker(
    checkpoint: Option<&ProgramLifecycleCheckpoint>,
    blocker_class: &str,
    action_id: &str,
    blocker: &ProgramBlocker,
) -> u32 {
    checkpoint
        .and_then(|checkpoint| {
            checkpoint
                .program_recovery_action_attempts
                .get(&program_recovery_action_attempt_key_for_blocker(
                    blocker_class,
                    action_id,
                    blocker,
                ))
                .copied()
        })
        .unwrap_or(0)
}

fn program_recovery_action_attempt_count(
    checkpoint: Option<&ProgramLifecycleCheckpoint>,
    blocker_class: &str,
    action_id: &str,
) -> u32 {
    checkpoint
        .and_then(|checkpoint| {
            checkpoint
                .program_recovery_action_attempts
                .get(&program_recovery_action_attempt_key(
                    blocker_class,
                    action_id,
                ))
                .copied()
        })
        .unwrap_or(0)
}

fn validate_recovery_recipe(
    program: &ProgramSpec,
    blocker_class: &str,
    state: &ProgramChildPlanState,
) -> Result<()> {
    validate_child_recovery_recipe(program, blocker_class, state)
}

fn validate_child_recovery_recipe(
    program: &ProgramSpec,
    blocker_class: &str,
    state: &ProgramChildPlanState,
) -> Result<()> {
    let Some(recipe) = program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
    else {
        return Ok(());
    };
    validate_recovery_recipe_metadata(recipe, blocker_class, false)?;
    for precondition in &recipe.preconditions {
        match precondition.as_str() {
            "live-state-readable" => {}
            "selected-route-present" => {
                if state.selected_route.is_none() {
                    bail!("recovery recipe precondition selected-route-present failed");
                }
            }
            "receipt-stale" => {
                if blocker_class != "stale-receipt" {
                    bail!("recovery recipe precondition receipt-stale mismatched blocker class");
                }
            }
            "hygiene-receipt-stale-after-live-pass" => {
                if blocker_class != "stale-receipt" {
                    bail!(
                        "recovery recipe precondition hygiene-receipt-stale-after-live-pass mismatched blocker class"
                    );
                }
                // Historical name; the selected child-owned recovery route may be review, closeout,
                // or another receipt-refreshing route declared by the child lifecycle.
            }
            "missing-evidence" => {
                if blocker_class != "missing-evidence" {
                    bail!("recovery recipe precondition missing-evidence mismatched blocker class");
                }
            }
            "target-path-unchanged"
            | "write-scope-unchanged"
            | "current-run-child-owned-drift-evidence"
            | "authority-zone-allowed"
            | "artifact-ownership-known"
            | "declared-write-scope-contained"
            | "run-bound-current"
            | "source-authority-digest-unchanged"
            | "generated-non-authority" => {}
            "approval-grant-present" => {
                bail!("recovery recipe precondition approval-grant-present is not automatically recoverable");
            }
            other => bail!("unsupported recovery recipe precondition: {other}"),
        }
    }
    Ok(())
}

fn validate_program_recovery_recipe(
    contract: &LifecycleContract,
    program: &ProgramSpec,
    blocker: &ProgramBlocker,
    selected_route: &RoutePlanState,
) -> Result<ProgramRecoveryRecipeValidationEvidence> {
    let blocker_class = blocker.blocker_class.as_str();
    let route_id = recovery_route_for_blocker(program, blocker)
        .with_context(|| format!("program recovery route missing for {blocker_class}"))?;
    if route_id != selected_route.route_id {
        bail!(
            "selected program recovery route {} does not match declared route {route_id}",
            selected_route.route_id
        );
    }
    route_by_id(contract, route_id).with_context(|| {
        format!("program recovery route {route_id} is missing from program lifecycle contract")
    })?;
    let recipe = recovery_recipe_for_blocker(program, blocker_class)
        .with_context(|| format!("program recovery recipe missing for {blocker_class}"))?;
    validate_recovery_recipe_metadata(recipe, blocker_class, true)?;
    validate_autonomous_recovery_envelope_route(recipe, route_id, selected_route)?;
    for precondition in &recipe.preconditions {
        match precondition.as_str() {
            "live-state-readable" => {}
            "selected-route-present" => {}
            "receipt-stale" => {
                if blocker_class != "stale-receipt" {
                    bail!("program recovery recipe precondition receipt-stale mismatched blocker class");
                }
            }
            "hygiene-receipt-stale-after-live-pass" => {
                if blocker_class != "stale-receipt" {
                    bail!(
                        "program recovery recipe precondition hygiene-receipt-stale-after-live-pass mismatched blocker class"
                    );
                }
            }
            "missing-evidence" => {
                if blocker_class != "missing-evidence" {
                    bail!(
                        "program recovery recipe precondition missing-evidence mismatched blocker class"
                    );
                }
            }
            "target-path-unchanged"
            | "write-scope-unchanged"
            | "current-run-child-owned-drift-evidence"
            | "authority-zone-allowed"
            | "artifact-ownership-known"
            | "declared-write-scope-contained"
            | "run-bound-current"
            | "source-authority-digest-unchanged"
            | "generated-non-authority" => {}
            "approval-grant-present" => {
                bail!(
                    "program recovery recipe precondition approval-grant-present is not automatically recoverable"
                );
            }
            other => bail!("unsupported program recovery recipe precondition: {other}"),
        }
    }
    let delegation_contract_basis =
        program_repair_delegation_contract_basis(program, blocker_class).with_context(|| {
            format!("program recovery recipe for {blocker_class} has no safe unattended basis")
        })?;
    if classify_program_blocker_class(blocker_class) == ProgramBlockerDisposition::Unsafe
        && !delegated_replay_class(recipe.idempotency_class.as_deref().unwrap_or(""))
    {
        bail!("program unsafe repair for {blocker_class} is not safe for unattended execution");
    }
    Ok(ProgramRecoveryRecipeValidationEvidence::passed(
        blocker_class,
        route_id,
        &delegation_contract_basis,
    ))
}

fn validate_recovery_recipe_metadata(
    recipe: &ProgramRecoveryRecipeSpec,
    blocker_class: &str,
    require_post_attempt_validation: bool,
) -> Result<()> {
    if recipe
        .idempotency_class
        .as_deref()
        .map(|class| matches!(class, "non-idempotent" | "unsafe" | "non-recoverable"))
        .unwrap_or(false)
    {
        bail!(
            "recovery recipe for {blocker_class} is not executable because it is non-idempotent, unsafe, or non-recoverable"
        );
    }
    if require_post_attempt_validation && recipe.post_attempt_validation.is_empty() {
        bail!("program recovery recipe for {blocker_class} must declare post_attempt_validation");
    }
    if recipe.requires_zone_evidence
        && (recipe.allowed_authority_zones.is_empty() || recipe.operation_class.is_none())
    {
        bail!("recovery recipe for {blocker_class} requires zone evidence but does not declare authority-zone dispatch metadata");
    }
    for validation in &recipe.post_attempt_validation {
        if !supported_recovery_post_attempt_validation(validation) {
            bail!("unsupported recovery recipe post-attempt validation: {validation}");
        }
    }
    if let Some(dependent_handling) = recipe.dependent_handling.as_deref() {
        if !matches!(
            dependent_handling,
            "block-dependents"
                | "continue-independent"
                | "pause-dependent"
                | "pause-phase"
                | "pause-barrier"
                | "fail-closed"
        ) {
            bail!("unsupported recovery dependent_handling: {dependent_handling}");
        }
    }
    if let Some(replan_behavior) = recipe.replan_behavior.as_deref() {
        if !matches!(replan_behavior, "none" | "after-attempt" | "always") {
            bail!("unsupported recovery replan_behavior: {replan_behavior}");
        }
    }
    if let Some(action_id) = recipe.recovery_action_id.as_deref() {
        if !supported_program_recovery_action(action_id) {
            bail!("unsupported recovery_action_id: {action_id}");
        }
    }
    for zone in &recipe.allowed_authority_zones {
        if !supported_authority_zone(zone) {
            bail!("unsupported recovery authority zone: {zone}");
        }
        if !recipe.human_required
            && matches!(
                zone.as_str(),
                AUTHORITY_ZONE_AUTHORED_GOVERNANCE | AUTHORITY_ZONE_PROTECTED_OR_EXTERNAL
            )
        {
            bail!("approval-free recovery recipe for {blocker_class} allows protected authority zone {zone}");
        }
    }
    for artifact_class in &recipe.allowed_artifact_classes {
        if !supported_authority_artifact_class(artifact_class) {
            bail!("unsupported recovery authority artifact class: {artifact_class}");
        }
        if !recipe.human_required
            && matches!(
                artifact_class.as_str(),
                ARTIFACT_CLASS_AUTHORED_GOVERNANCE
                    | ARTIFACT_CLASS_PROTECTED_OR_EXTERNAL
                    | ARTIFACT_CLASS_UNKNOWN
            )
        {
            bail!("approval-free recovery recipe for {blocker_class} allows protected artifact class {artifact_class}");
        }
    }
    if let Some(operation_class) = recipe.operation_class.as_deref() {
        if !supported_authority_operation_class(operation_class) {
            bail!("unsupported recovery authority operation class: {operation_class}");
        }
        if !recipe.human_required
            && matches!(
                operation_class,
                "durable-authority-mutation" | "protected-artifact-mutation"
            )
        {
            bail!("approval-free recovery recipe for {blocker_class} allows protected operation class {operation_class}");
        }
    }
    for zone in &recipe.human_required_for_zones {
        if !supported_authority_zone(zone) {
            bail!("unsupported authority-ambiguity authority zone: {zone}");
        }
    }
    Ok(())
}

fn supported_program_recovery_action(action_id: &str) -> bool {
    matches!(
        action_id,
        REFRESH_PUBLICATION_PROJECTIONS_ACTION
            | REBASELINE_CHECKPOINT_ACTION
            | CLEANUP_CURRENT_RUN_ARTIFACTS_ACTION
    )
}

fn program_recovery_route_material_side_effect(route_id: &str) -> Option<&'static str> {
    let normalized = route_id.trim().to_ascii_lowercase();
    if normalized == ROUTE_ID_ARCHIVE_PROPOSAL {
        return Some("archive");
    }
    if normalized.contains("push") {
        return Some("push");
    }
    if normalized.contains("landing") || normalized.contains("merge") {
        return Some("landing-or-merge");
    }
    if normalized.contains("branch-cleanup") || normalized.contains("branch-delete") {
        return Some("branch-cleanup");
    }
    if normalized.contains("pull-request") || normalized.contains("pr-create") {
        return Some("pr-creation-or-merge");
    }
    if normalized.contains("external-publication") {
        return Some("external-publication");
    }
    if normalized.contains("cleaned-claim") {
        return Some("cleaned-claim");
    }
    if normalized.contains("cleanup") && normalized != ROUTE_ID_CLEANUP_LIFECYCLE_RESIDUE {
        return Some("cleanup-deletion");
    }
    None
}

fn recipe_declares_value(values: &[String], expected: &str) -> bool {
    values.iter().any(|value| value == expected)
}

fn require_recipe_value(
    recipe: &ProgramRecoveryRecipeSpec,
    values: &[String],
    field_name: &str,
    expected: &str,
) -> Result<()> {
    if recipe_declares_value(values, expected) {
        Ok(())
    } else {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} requires recipe {} field {field_name} to include {expected}",
            recipe.blocker_class
        )
    }
}

fn require_recipe_operation(
    recipe: &ProgramRecoveryRecipeSpec,
    expected_operation: &str,
) -> Result<()> {
    if recipe.operation_class.as_deref() == Some(expected_operation) {
        Ok(())
    } else {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} requires recipe {} operation_class={expected_operation}",
            recipe.blocker_class
        )
    }
}

fn require_recipe_post_validation(
    recipe: &ProgramRecoveryRecipeSpec,
    expected_validation: &str,
) -> Result<()> {
    require_recipe_value(
        recipe,
        &recipe.post_attempt_validation,
        "post_attempt_validation",
        expected_validation,
    )
}

fn validate_autonomous_recovery_envelope_action(
    program: &ProgramSpec,
    blocker_class: &str,
    action_id: &str,
) -> Result<()> {
    let recipe = recovery_recipe_for_blocker(program, blocker_class)
        .with_context(|| format!("program recovery recipe missing for {blocker_class}"))?;
    if recipe.human_required {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} cannot run human-required recovery action {action_id}"
        );
    }
    if recipe.recovery_action_id.as_deref() != Some(action_id) {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} action {action_id} is not declared by recipe {blocker_class}"
        );
    }
    validate_recovery_recipe_metadata(recipe, blocker_class, true)?;
    match action_id {
        REFRESH_PUBLICATION_PROJECTIONS_ACTION => {
            require_recipe_operation(recipe, OPERATION_CLASS_REFRESH_GENERATED_PROJECTION)?;
            require_recipe_value(
                recipe,
                &recipe.allowed_authority_zones,
                "allowed_authority_zones",
                AUTHORITY_ZONE_GENERATED_DERIVED,
            )?;
            require_recipe_value(
                recipe,
                &recipe.allowed_artifact_classes,
                "allowed_artifact_classes",
                ARTIFACT_CLASS_GENERATED_DERIVED,
            )?;
            require_recipe_value(
                recipe,
                &recipe.allowed_artifact_classes,
                "allowed_artifact_classes",
                ARTIFACT_CLASS_HOST_PROJECTION,
            )?;
            require_recipe_post_validation(recipe, "publication-freshness-cleared")?;
            require_recipe_post_validation(recipe, "replay-verify")?;
        }
        REBASELINE_CHECKPOINT_ACTION => {
            require_recipe_operation(recipe, OPERATION_CLASS_PROGRAM_RECOVERY_ACTION)?;
            require_recipe_value(
                recipe,
                &recipe.allowed_authority_zones,
                "allowed_authority_zones",
                AUTHORITY_ZONE_RUN_BOUND,
            )?;
            require_recipe_value(
                recipe,
                &recipe.allowed_artifact_classes,
                "allowed_artifact_classes",
                ARTIFACT_CLASS_RUN_CONTROL,
            )?;
            require_recipe_value(
                recipe,
                &recipe.allowed_artifact_classes,
                "allowed_artifact_classes",
                ARTIFACT_CLASS_RUN_EVIDENCE,
            )?;
            if !recipe.requires_run_binding || !recipe.requires_zone_evidence {
                bail!(
                    "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} requires run binding and zone evidence for {action_id}"
                );
            }
            require_recipe_post_validation(recipe, "authority-boundary-check")?;
            require_recipe_post_validation(recipe, "replay-verify")?;
        }
        CLEANUP_CURRENT_RUN_ARTIFACTS_ACTION => {
            require_recipe_operation(recipe, OPERATION_CLASS_CLEANUP_CURRENT_RUN_ARTIFACT)?;
            require_recipe_value(
                recipe,
                &recipe.allowed_authority_zones,
                "allowed_authority_zones",
                AUTHORITY_ZONE_CURRENT_RUN_AGENT_ARTIFACT,
            )?;
            require_recipe_value(
                recipe,
                &recipe.allowed_artifact_classes,
                "allowed_artifact_classes",
                ARTIFACT_CLASS_CURRENT_RUN_GENERATED,
            )?;
            if !recipe.requires_run_binding
                || !recipe.requires_declared_write_scope
                || !recipe.requires_zone_evidence
            {
                bail!(
                    "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} requires run binding, declared write scope, and zone evidence for {action_id}"
                );
            }
            require_recipe_post_validation(recipe, "authority-boundary-check")?;
        }
        other => bail!("{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} does not allow action {other}"),
    }
    Ok(())
}

fn validate_autonomous_recovery_envelope_route(
    recipe: &ProgramRecoveryRecipeSpec,
    route_id: &str,
    _route: &RoutePlanState,
) -> Result<()> {
    if let Some(effect) = program_recovery_route_material_side_effect(route_id) {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} stops before material side effect route {route_id}: {effect}"
        );
    }
    if recipe.human_required {
        bail!(
            "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} cannot run human-required recovery route {route_id}"
        );
    }
    if route_id == ROUTE_ID_CLEANUP_LIFECYCLE_RESIDUE {
        require_recipe_operation(recipe, OPERATION_CLASS_PROGRAM_RECOVERY_ACTION)?;
        if !recipe.requires_run_binding || !recipe.requires_zone_evidence {
            bail!(
                "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} requires run binding and zone evidence for {route_id}"
            );
        }
        require_recipe_post_validation(recipe, "authority-boundary-check")?;
        for forbidden_artifact_class in [
            ARTIFACT_CLASS_AUTHORED_GOVERNANCE,
            ARTIFACT_CLASS_PROTECTED_OR_EXTERNAL,
            ARTIFACT_CLASS_UNKNOWN,
        ] {
            if recipe_declares_value(&recipe.allowed_artifact_classes, forbidden_artifact_class) {
                bail!(
                    "{AUTONOMOUS_RECOVERY_ENVELOPE_NAME} route {route_id} cannot allow protected artifact class {forbidden_artifact_class}"
                );
            }
        }
    }
    Ok(())
}

fn supported_authority_zone(zone: &str) -> bool {
    matches!(
        zone,
        AUTHORITY_ZONE_RUN_BOUND
            | AUTHORITY_ZONE_GENERATED_DERIVED
            | AUTHORITY_ZONE_AUTHORED_GOVERNANCE
            | AUTHORITY_ZONE_WORKSPACE_DECLARED
            | AUTHORITY_ZONE_CURRENT_RUN_AGENT_ARTIFACT
            | AUTHORITY_ZONE_PROTECTED_OR_EXTERNAL
    )
}

fn supported_authority_artifact_class(artifact_class: &str) -> bool {
    matches!(
        artifact_class,
        ARTIFACT_CLASS_RUN_CONTROL
            | ARTIFACT_CLASS_RUN_EVIDENCE
            | ARTIFACT_CLASS_GENERATED_DERIVED
            | ARTIFACT_CLASS_HOST_PROJECTION
            | ARTIFACT_CLASS_AUTHORED_GOVERNANCE
            | ARTIFACT_CLASS_WORKSPACE_SOURCE
            | ARTIFACT_CLASS_CURRENT_RUN_GENERATED
            | ARTIFACT_CLASS_PROTECTED_OR_EXTERNAL
            | ARTIFACT_CLASS_UNKNOWN
    )
}

fn supported_authority_operation_class(operation_class: &str) -> bool {
    matches!(
        operation_class,
        "inspect"
            | "append-run-evidence"
            | "update-run-control"
            | OPERATION_CLASS_REFRESH_GENERATED_PROJECTION
            | OPERATION_CLASS_CLEANUP_CURRENT_RUN_ARTIFACT
            | OPERATION_CLASS_RETRY_CHILD_ROUTE
            | OPERATION_CLASS_EXECUTE_CHILD_ROUTE
            | OPERATION_CLASS_PROGRAM_RECOVERY_ACTION
            | OPERATION_CLASS_CLOSEOUT_READINESS
            | "durable-authority-mutation"
            | "protected-artifact-mutation"
    )
}

fn supported_recovery_post_attempt_validation(validation: &str) -> bool {
    matches!(
        validation,
        "replan-live-state"
            | "receipt-fresh"
            | "receipt-freshness"
            | "blocker-cleared"
            | "replay-verify"
            | "authority-boundary-check"
            | "aggregate-closeout-check"
            | "publication-freshness-cleared"
    )
}

fn enforce_recovery_post_attempt_validations(
    program: &ProgramSpec,
    plan: &ProgramLifecyclePlanResult,
    control_root: &Path,
    live_replanned: bool,
    child_results: &mut [ProgramChildExecutionSummary],
) -> Result<()> {
    for result in child_results
        .iter_mut()
        .filter(|result| result.blocker_class.is_some())
    {
        let blocker_class = result.blocker_class.clone().unwrap_or_default();
        let validations = recovery_post_attempt_validations(program, &blocker_class);
        if validations.is_empty() || result.status != "completed" {
            continue;
        }
        if recovery_replan_after_attempt(program, &blocker_class) && !live_replanned {
            result.status = "failed".to_string();
            result.retryable = true;
            result.error_message = Some(format!(
                "recovery post-attempt validation failed for {blocker_class}: declared replan_behavior was not satisfied"
            ));
            continue;
        }
        let Some(state) = plan.child_states.get(&result.child_id) else {
            result.status = "failed".to_string();
            result.retryable = true;
            result.error_message = Some(format!(
                "recovery post-attempt validation failed for {blocker_class}: child missing after live replan"
            ));
            continue;
        };
        if closeout_recovery_blocked_by_worktree(result, &blocker_class, state) {
            result.status = "blocked".to_string();
            result.retryable = false;
            result.blocker_class = Some("artifact-ownership-unclear".to_string());
            result.error_message = Some(
                "closeout-packet wrote a blocked closeout receipt because worktree hygiene is blocked"
                    .to_string(),
            );
            continue;
        }
        let failed = validations.iter().find(|validation| {
            !recovery_post_attempt_validation_passed(
                validation,
                state,
                plan,
                control_root,
                live_replanned,
            )
        });
        if let Some(validation) = failed {
            result.status = "failed".to_string();
            result.retryable = true;
            result.error_message = Some(format!(
                "recovery post-attempt validation failed for {blocker_class}: {validation}"
            ));
        }
    }
    Ok(())
}

fn closeout_recovery_blocked_by_worktree(
    result: &ProgramChildExecutionSummary,
    blocker_class: &str,
    state: &ProgramChildPlanState,
) -> bool {
    result.route_id == "closeout-packet"
        && blocker_class == "stale-receipt"
        && state.blockers.iter().any(|blocker| {
            matches!(
                blocker.blocker_class.as_str(),
                "worktree-hygiene-blocked"
                    | "artifact-ownership-unclear"
                    | "worktree-handoff-evidence-changed"
                    | "stale-closeout-worktree-return"
            )
        })
}

fn recovery_post_attempt_validations(program: &ProgramSpec, blocker_class: &str) -> Vec<String> {
    program
        .recovery_policy
        .recipes
        .iter()
        .find(|recipe| recovery_recipe_matches(recipe, blocker_class))
        .map(|recipe| recipe.post_attempt_validation.clone())
        .unwrap_or_default()
}

fn recovery_post_attempt_validation_passed(
    validation: &str,
    state: &ProgramChildPlanState,
    plan: &ProgramLifecyclePlanResult,
    control_root: &Path,
    live_replanned: bool,
) -> bool {
    match validation {
        "replan-live-state" => live_replanned,
        "receipt-fresh" | "receipt-freshness" => recovery_receipt_freshness_passed_for_child(state),
        "blocker-cleared" => state.blockers.is_empty(),
        "authority-boundary-check" => {
            !state
                .blockers
                .iter()
                .any(|blocker| blocker.blocker_class == "authority-boundary-ambiguous")
                && !plan
                    .program_blockers
                    .iter()
                    .any(|blocker| blocker.blocker_class == "authority-boundary-ambiguous")
        }
        "aggregate-closeout-check" => {
            plan.aggregate_state != "completed" || plan.final_verdict == "completed"
        }
        "publication-freshness-cleared" => !state
            .blockers
            .iter()
            .any(|blocker| blocker.blocker_class == "publication-drift"),
        "replay-verify" => verify_program_event_log_for_recovery(control_root).is_ok(),
        _ => false,
    }
}

fn recovery_receipt_freshness_passed_for_child(state: &ProgramChildPlanState) -> bool {
    if state.receipt_digests.is_empty() {
        return false;
    }
    if state
        .blockers
        .iter()
        .any(|blocker| blocker.blocker_class == "missing-evidence")
    {
        return false;
    }
    if !state
        .blockers
        .iter()
        .any(|blocker| blocker.blocker_class == "stale-receipt")
    {
        return true;
    }
    closeout_recovery_advanced_to_archive_route(state)
}

fn closeout_recovery_advanced_to_archive_route(state: &ProgramChildPlanState) -> bool {
    if !state.gate_status.closeout {
        return false;
    }
    let Some(route) = state.selected_route.as_ref() else {
        return false;
    };
    if route.route_id != ROUTE_ID_ARCHIVE_PROPOSAL {
        return false;
    }
    state
        .blockers
        .iter()
        .filter(|blocker| blocker.blocker_class == "stale-receipt")
        .all(|blocker| blocker.recovery_route.as_deref() == Some(ROUTE_ID_ARCHIVE_PROPOSAL))
}

fn enforce_program_recovery_post_attempt_validations(
    program: &ProgramSpec,
    _before_plan: &ProgramLifecyclePlanResult,
    after_plan: &ProgramLifecyclePlanResult,
    control_root: &Path,
    blocker_class: &str,
    result: &LifecycleRouteExecutionResult,
    live_replanned: bool,
) -> ProgramRecoveryPostAttemptValidationOutcome {
    if !matches!(result.status.as_str(), "completed" | "no-op") {
        return ProgramRecoveryPostAttemptValidationOutcome::route_not_completed(
            &result.status,
            result.error_message.as_deref(),
            Some(blocker_class.to_string()),
        );
    }
    let declared = recovery_post_attempt_validations(program, blocker_class);
    if declared.is_empty() {
        return ProgramRecoveryPostAttemptValidationOutcome {
            status: "failed".to_string(),
            failures: vec![format!(
                "program recovery recipe for {blocker_class} declared no post_attempt_validation"
            )],
            declared,
            results: Vec::new(),
            execution_can_resume: false,
            resume_decision_basis:
                "program repair cannot resume without declared post-attempt validation".to_string(),
            final_blocker_class: Some(blocker_class.to_string()),
        };
    }

    let mut failures = Vec::new();
    let mut results = Vec::new();
    for validation in &declared {
        match program_recovery_post_attempt_validation_result(
            validation,
            after_plan,
            control_root,
            blocker_class,
            live_replanned,
        ) {
            Ok(()) => results.push(format!("{validation}: pass")),
            Err(error) => {
                results.push(format!("{validation}: fail: {error}"));
                failures.push(format!("{validation}: {error}"));
            }
        }
    }
    if failures.is_empty() {
        ProgramRecoveryPostAttemptValidationOutcome {
            status: "passed".to_string(),
            failures,
            declared,
            results,
            execution_can_resume: true,
            resume_decision_basis:
                "repair route completed and all declared program post-attempt validations passed"
                    .to_string(),
            final_blocker_class: None,
        }
    } else {
        ProgramRecoveryPostAttemptValidationOutcome {
            status: "failed".to_string(),
            failures,
            declared,
            results,
            execution_can_resume: false,
            resume_decision_basis:
                "program repair route completed but declared post-attempt validation failed"
                    .to_string(),
            final_blocker_class: Some(blocker_class.to_string()),
        }
    }
}

fn program_recovery_post_attempt_validation_result(
    validation: &str,
    after_plan: &ProgramLifecyclePlanResult,
    control_root: &Path,
    blocker_class: &str,
    live_replanned: bool,
) -> std::result::Result<(), String> {
    match validation {
        "replan-live-state" => live_replanned
            .then_some(())
            .ok_or_else(|| "live replan did not run after program repair".to_string()),
        "blocker-cleared" => {
            let remaining_same_blocker = after_plan
                .program_blockers
                .iter()
                .any(|blocker| blocker.blocker_class == blocker_class);
            (!remaining_same_blocker)
                .then_some(())
                .ok_or_else(|| format!("program blocker {blocker_class} remains after repair"))
        }
        "authority-boundary-check" => {
            let remaining = after_plan.program_blockers.iter().find(|blocker| {
                matches!(
                    classify_program_blocker_class(&blocker.blocker_class),
                    ProgramBlockerDisposition::Unsafe | ProgramBlockerDisposition::Human
                )
            });
            remaining.is_none().then_some(()).ok_or_else(|| {
                format!(
                    "program authority or unsafe blocker remains after repair: {}",
                    remaining
                        .map(|blocker| blocker.blocker_class.as_str())
                        .unwrap_or("unknown")
                )
            })
        }
        "aggregate-closeout-check" => (after_plan.aggregate_state != "completed"
            || after_plan.final_verdict == "completed")
            .then_some(())
            .ok_or_else(|| {
                "aggregate state is completed without completed final verdict".to_string()
            }),
        "publication-freshness-cleared" => {
            let remaining_program = after_plan
                .program_blockers
                .iter()
                .any(|blocker| blocker.blocker_class == "publication-drift");
            if remaining_program {
                return Err("program publication-drift blocker remains after repair".to_string());
            }
            if !after_plan.child_states.values().any(|state| {
                state
                    .blockers
                    .iter()
                    .any(|blocker| blocker.blocker_class == "publication-drift")
            }) {
                return Ok(());
            }
            (blocker_class == "publication-drift"
                && remaining_publication_drift_is_limited_to_rerunnable_children(after_plan))
            .then_some(())
            .ok_or_else(|| {
                "publication-drift blocker remains after repair without a selected child recovery route"
                    .to_string()
            })
        }
        "replay-verify" => {
            verify_program_event_log_for_recovery(control_root).map_err(|error| error.to_string())
        }
        "receipt-fresh" | "receipt-freshness" => {
            Err("program-scope receipt freshness validation has no explicit source".to_string())
        }
        other => Err(format!(
            "unsupported program post-attempt validation {other}"
        )),
    }
}

fn remaining_publication_drift_is_limited_to_rerunnable_children(
    after_plan: &ProgramLifecyclePlanResult,
) -> bool {
    let mut saw_publication_drift = false;
    for state in after_plan.child_states.values() {
        for blocker in state
            .blockers
            .iter()
            .filter(|blocker| blocker.blocker_class == "publication-drift")
        {
            saw_publication_drift = true;
            let selected_route = state
                .selected_route
                .as_ref()
                .map(|route| route.route_id.as_str());
            if selected_route.is_none()
                || blocker.recovery_route.as_deref() != selected_route
                || !after_plan
                    .runnable_batch
                    .iter()
                    .any(|id| id == &state.child_id)
            {
                return false;
            }
        }
    }
    saw_publication_drift
}

fn verify_program_event_log_for_recovery(control_root: &Path) -> Result<()> {
    let events = read_program_events(control_root)?;
    let mut errors = Vec::new();
    let legacy_event_log = events
        .iter()
        .any(|event| event.schema_version == "octon-program-lifecycle-event-v1");
    if legacy_event_log {
        errors.push("legacy event log is not replay-verifiable for recovery".to_string());
    }
    if events.is_empty() {
        errors.push("missing event log entries".to_string());
    }
    validate_event_offsets(&events, &mut errors);
    validate_event_hash_chain(&events, legacy_event_log, &mut errors)?;
    validate_program_event_transitions(&events, &mut errors);
    if errors.is_empty() {
        Ok(())
    } else {
        bail!(
            "program recovery replay verification failed: {}",
            errors.join("; ")
        );
    }
}

fn select_program_recovery_action<'a>(
    program: &'a ProgramSpec,
    plan: &'a ProgramLifecyclePlanResult,
    checkpoint: Option<&ProgramLifecycleCheckpoint>,
) -> Option<(&'a str, &'a str)> {
    for blocker in &plan.program_blockers {
        let Some(action_id) = recovery_action_id(program, &blocker.blocker_class) else {
            continue;
        };
        if validate_autonomous_recovery_envelope_action(program, &blocker.blocker_class, action_id)
            .is_err()
        {
            continue;
        }
        let budget = recovery_attempt_budget(program, &blocker.blocker_class)
            .or(program.recovery_policy.max_recovery_attempts)
            .unwrap_or(1);
        let used = program_recovery_action_attempt_count_for_plan(
            checkpoint,
            &blocker.blocker_class,
            action_id,
            plan,
        );
        if used < budget
            || rebaseline_checkpoint_has_resettable_recovery_state(
                checkpoint,
                action_id,
                &blocker.blocker_class,
                plan,
            )
        {
            return Some((blocker.blocker_class.as_str(), action_id.as_str()));
        }
    }
    for state in plan.child_states.values() {
        for blocker in &state.blockers {
            let Some(action_id) = recovery_action_id(program, &blocker.blocker_class) else {
                continue;
            };
            if validate_autonomous_recovery_envelope_action(
                program,
                &blocker.blocker_class,
                action_id,
            )
            .is_err()
            {
                continue;
            }
            let budget = recovery_attempt_budget(program, &blocker.blocker_class)
                .or(program.recovery_policy.max_recovery_attempts)
                .unwrap_or(1);
            let used = program_recovery_action_attempt_count_for_plan(
                checkpoint,
                &blocker.blocker_class,
                action_id,
                plan,
            );
            if used < budget
                || rebaseline_checkpoint_has_resettable_recovery_state(
                    checkpoint,
                    action_id,
                    &blocker.blocker_class,
                    plan,
                )
            {
                return Some((blocker.blocker_class.as_str(), action_id.as_str()));
            }
        }
    }
    None
}

fn should_execute_program_recovery_before_child_dispatch(
    runnable_batch_empty: bool,
    publication_preflight_blocked: bool,
    selected_action: Option<(&str, &str)>,
) -> bool {
    if publication_preflight_blocked {
        return true;
    }
    if runnable_batch_empty {
        return selected_action.is_some();
    }
    matches!(
        selected_action,
        Some(("publication-drift", REFRESH_PUBLICATION_PROJECTIONS_ACTION))
    )
}

fn rebaseline_checkpoint_has_resettable_recovery_state(
    checkpoint: Option<&ProgramLifecycleCheckpoint>,
    action_id: &str,
    blocker_class: &str,
    before_plan: &ProgramLifecyclePlanResult,
) -> bool {
    if action_id != REBASELINE_CHECKPOINT_ACTION
        || !matches!(
            blocker_class,
            "recovery-integrity-risk" | "recovery-budget-override-required"
        )
    {
        return false;
    }
    let Some(checkpoint) = checkpoint else {
        return false;
    };
    before_plan.child_states.values().any(|state| {
        let child_attempt_prefix = format!("{}:", state.child_id);
        state
            .blockers
            .iter()
            .any(|blocker| blocker.blocker_class == blocker_class)
            && (checkpoint
                .recovery_attempts
                .keys()
                .any(|key| key == &state.child_id || key.starts_with(&child_attempt_prefix))
                || checkpoint
                    .recovery_progress_fingerprints
                    .values()
                    .any(|fingerprint| fingerprint.child_id == state.child_id))
    })
}

fn execute_selected_program_recovery_action(
    program: &ProgramSpec,
    plan: &ProgramLifecyclePlanResult,
    previous_checkpoint: Option<&ProgramLifecycleCheckpoint>,
    program_recovery_action_attempts: &mut BTreeMap<String, u32>,
    repo_root: &Path,
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<Option<ProgramRecoveryActionOutcome>> {
    let Some((blocker_class, action_id)) =
        select_program_recovery_action(program, plan, previous_checkpoint)
    else {
        return Ok(None);
    };
    let key = program_recovery_action_attempt_key_for_plan(blocker_class, action_id, plan);
    let attempt_number = program_recovery_action_attempts
        .get(&key)
        .copied()
        .unwrap_or(0)
        + 1;
    let outcome = execute_program_recovery_action(
        program,
        repo_root,
        control_root,
        evidence_root,
        program_run_id,
        blocker_class,
        action_id,
        attempt_number,
        step_context,
    )?;
    *program_recovery_action_attempts.entry(key).or_default() += 1;
    Ok(Some(outcome))
}

fn authority_paths_for_program_recovery_action(
    repo_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    action_id: &str,
) -> (Vec<PathBuf>, Vec<String>, &'static str) {
    match action_id {
        REFRESH_PUBLICATION_PROJECTIONS_ACTION => (
            vec![
                repo_root.join(".octon/generated"),
                repo_root.join(".claude"),
                repo_root.join(".cursor"),
                repo_root.join(".codex/commands"),
                repo_root.join(".codex/skills"),
            ],
            Vec::new(),
            OPERATION_CLASS_REFRESH_GENERATED_PROJECTION,
        ),
        REBASELINE_CHECKPOINT_ACTION => {
            let run_control = repo_root
                .join(".octon/state/control/execution/runs")
                .join(program_run_id);
            (
                vec![
                    evidence_root.to_path_buf(),
                    run_control.join(PROGRAM_CHECKPOINT_FILE),
                ],
                vec![authority_path_ref(repo_root, &run_control)],
                OPERATION_CLASS_PROGRAM_RECOVERY_ACTION,
            )
        }
        CLEANUP_CURRENT_RUN_ARTIFACTS_ACTION => {
            let run_control = repo_root
                .join(".octon/state/control/execution/runs")
                .join(program_run_id);
            (
                vec![
                    run_control.join("locks"),
                    run_control.join("tmp"),
                    run_control.join("scratch"),
                ],
                vec![authority_path_ref(repo_root, &run_control)],
                OPERATION_CLASS_CLEANUP_CURRENT_RUN_ARTIFACT,
            )
        }
        _ => (
            vec![evidence_root.to_path_buf()],
            Vec::new(),
            OPERATION_CLASS_PROGRAM_RECOVERY_ACTION,
        ),
    }
}

fn mark_no_progress_child_results(
    before_plan: &ProgramLifecyclePlanResult,
    after_plan: &ProgramLifecyclePlanResult,
    child_results: &mut [ProgramChildExecutionSummary],
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<Vec<String>> {
    let mut no_progress_blockers = Vec::new();
    for result in child_results.iter_mut() {
        if !matches!(result.status.as_str(), "completed" | "no-op") {
            continue;
        }
        let Some(blocker_class) = result.blocker_class.as_deref() else {
            continue;
        };
        let Some(before_state) = before_plan.child_states.get(&result.child_id) else {
            continue;
        };
        let Some(after_state) = after_plan.child_states.get(&result.child_id) else {
            continue;
        };
        let before = child_progress_fingerprint(before_state, &result.route_id, blocker_class);
        let after = child_progress_fingerprint(after_state, &result.route_id, blocker_class);
        if before != after {
            continue;
        }
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "child-route-no-progress",
            Some(&result.child_id),
            Some(&result.route_id),
            "child route completed without advancing child lifecycle progress",
            program_step_event_data(
                step_context.as_ref(),
                "child-batch-dispatch",
                [
                    ("blocker_class", blocker_class),
                    ("route_id", result.route_id.as_str()),
                ],
            ),
        )?;
        no_progress_blockers.push(blocker_class.to_string());
        result.status = "blocked".to_string();
        result.retryable = false;
        result.error_message = Some(format!(
            "route completed but child lifecycle progress did not change for blocker {blocker_class}"
        ));
    }
    no_progress_blockers.sort();
    no_progress_blockers.dedup();
    Ok(no_progress_blockers)
}

fn record_program_recovery_action_failure(
    plan: &mut ProgramLifecyclePlanResult,
    final_verdict: &mut String,
    terminal_outcome: &mut Option<String>,
    outcome: &ProgramRecoveryActionOutcome,
) {
    *final_verdict = "blocked-recoverable".to_string();
    *terminal_outcome = None;
    plan.final_verdict = final_verdict.clone();
    plan.terminal_outcome = None;
    plan.stop_reason = Some(format!(
        "program recovery action {} for {} failed at command {} (evidence: {}): {}",
        outcome.action_id,
        outcome.blocker_class,
        outcome.failed_command.as_deref().unwrap_or("unknown"),
        outcome.evidence_path,
        outcome
            .error_message
            .as_deref()
            .unwrap_or("no error message")
    ));
}

fn enforce_program_recovery_action_post_validations(
    repo_root: &Path,
    program: &ProgramSpec,
    after_plan: &ProgramLifecyclePlanResult,
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    outcome: &ProgramRecoveryActionOutcome,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<Option<ProgramRecoveryActionOutcome>> {
    let declared = recovery_post_attempt_validations(program, &outcome.blocker_class);
    let mut failures = Vec::new();
    if declared.is_empty() {
        failures.push(format!(
            "program recovery recipe for {} declared no post_attempt_validation",
            outcome.blocker_class
        ));
    }
    for validation in &declared {
        if let Err(error) = program_recovery_post_attempt_validation_result(
            validation,
            after_plan,
            control_root,
            &outcome.blocker_class,
            true,
        ) {
            failures.push(format!("{validation}: {error}"));
        }
    }
    if failures.is_empty() {
        return Ok(None);
    }
    let message = failures.join("; ");
    let failed_command = "post-validation";
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "program-recovery-action-validation-failed",
        None,
        Some(&outcome.action_id),
        "program recovery action post-validation failed",
        program_step_event_data(
            step_context.as_ref(),
            "program-recovery-action",
            [
                ("blocker_class", outcome.blocker_class.as_str()),
                ("action_id", outcome.action_id.as_str()),
                ("failed_command", failed_command),
                ("evidence_path", outcome.evidence_path.as_str()),
            ],
        ),
    )?;
    let action_root = if Path::new(&outcome.evidence_path).is_absolute() {
        PathBuf::from(&outcome.evidence_path)
    } else {
        repo_root.join(&outcome.evidence_path)
    };
    write_program_recovery_action_summary(
        repo_root,
        &action_root,
        &outcome.action_id,
        &outcome.blocker_class,
        "failed",
        Some(failed_command),
        Some(&message),
    )?;
    Ok(Some(ProgramRecoveryActionOutcome {
        action_id: outcome.action_id.clone(),
        blocker_class: outcome.blocker_class.clone(),
        status: "failed".to_string(),
        evidence_path: outcome.evidence_path.clone(),
        failed_command: Some(failed_command.to_string()),
        error_message: Some(message),
    }))
}

fn execute_program_recovery_action(
    program: &ProgramSpec,
    repo_root: &Path,
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    blocker_class: &str,
    action_id: &str,
    attempt_number: u32,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<ProgramRecoveryActionOutcome> {
    if !supported_program_recovery_action(action_id) {
        bail!("unsupported program recovery action: {action_id}");
    }
    validate_autonomous_recovery_envelope_action(program, blocker_class, action_id)?;
    let octon_dir = repo_root.join(".octon");
    let action_root = evidence_root
        .join("program-recovery-actions")
        .join(action_id)
        .join(format!("attempt-{attempt_number}"));
    fs::create_dir_all(&action_root)?;
    let (authority_paths, declared_write_scopes, operation_class) =
        authority_paths_for_program_recovery_action(
            repo_root,
            evidence_root,
            program_run_id,
            action_id,
        );
    let authority_decision = classify_authority_zone(
        repo_root,
        program_run_id,
        None,
        Some(action_id),
        Some(blocker_class),
        operation_class,
        &authority_paths,
        &declared_write_scopes,
        None,
    );
    let authority_decision_path =
        write_authority_zone_decision(evidence_root, &authority_decision)?;
    let recipe = recovery_recipe_for_blocker(program, blocker_class);
    if !authority_decision.autonomous_allowed
        || !recovery_recipe_allows_authority_decision(recipe, &authority_decision)
    {
        let evidence_path = rel_display(repo_root, &action_root);
        let message = format!(
            "program recovery action {action_id} denied by authority zone {} for artifact class {}; decision evidence: {authority_decision_path}",
            authority_decision.authority_zone, authority_decision.artifact_class
        );
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "program-recovery-action-authority-blocked",
            None,
            Some(action_id),
            "program recovery action blocked by authority-zone decision",
            program_step_event_data(
                step_context.as_ref(),
                "program-recovery-action",
                [
                    ("blocker_class", blocker_class),
                    ("action_id", action_id),
                    ("authority_zone", authority_decision.authority_zone.as_str()),
                    ("artifact_class", authority_decision.artifact_class.as_str()),
                    ("authority_decision", authority_decision_path.as_str()),
                ],
            ),
        )?;
        write_program_recovery_action_summary(
            repo_root,
            &action_root,
            action_id,
            blocker_class,
            "failed",
            Some(authority_decision.fail_closed_blocker.as_str()),
            Some(&message),
        )?;
        return Ok(ProgramRecoveryActionOutcome {
            action_id: action_id.to_string(),
            blocker_class: authority_decision.fail_closed_blocker,
            status: "failed".to_string(),
            evidence_path,
            failed_command: Some("authority-zone-decision".to_string()),
            error_message: Some(message),
        });
    }
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "program-recovery-action-started",
        None,
        Some(action_id),
        "program recovery action started",
        program_step_event_data(
            step_context.as_ref(),
            "program-recovery-action",
            [("blocker_class", blocker_class), ("action_id", action_id)],
        ),
    )?;

    if action_id == REBASELINE_CHECKPOINT_ACTION {
        let evidence_path = rel_display(repo_root, &action_root);
        fs::write(
            action_root.join("rebaseline-summary.yml"),
            format!(
                "schema_version: \"octon-program-rebaseline-checkpoint-v1\"\naction_id: \"{action_id}\"\nblocker_class: \"{blocker_class}\"\nstatus: \"completed\"\nreplan_required: true\n"
            ),
        )?;
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "program-recovery-action-finished",
            None,
            Some(action_id),
            "program recovery action finished",
            program_step_event_data(
                step_context.as_ref(),
                "program-recovery-action",
                [
                    ("blocker_class", blocker_class),
                    ("action_id", action_id),
                    ("status", "completed"),
                    ("evidence_path", evidence_path.as_str()),
                ],
            ),
        )?;
        write_program_recovery_action_summary(
            repo_root,
            &action_root,
            action_id,
            blocker_class,
            "completed",
            None,
            None,
        )?;
        return Ok(ProgramRecoveryActionOutcome {
            action_id: action_id.to_string(),
            blocker_class: blocker_class.to_string(),
            status: "completed".to_string(),
            evidence_path,
            failed_command: None,
            error_message: None,
        });
    }

    if action_id == CLEANUP_CURRENT_RUN_ARTIFACTS_ACTION {
        let evidence_path = rel_display(repo_root, &action_root);
        fs::write(
            action_root.join("cleanup-current-run-artifacts.yml"),
            format!(
                "schema_version: \"octon-program-current-run-cleanup-v1\"\naction_id: \"{action_id}\"\nblocker_class: \"{blocker_class}\"\nstatus: \"completed\"\nmutation_performed: false\nrationale: \"current-run artifact cleanup is executed through governed artifact cleanup operations; no standalone cleanup operation was selected by the blocker\"\nreplan_required: true\n"
            ),
        )?;
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "program-recovery-action-finished",
            None,
            Some(action_id),
            "program recovery action finished",
            program_step_event_data(
                step_context.as_ref(),
                "program-recovery-action",
                [
                    ("blocker_class", blocker_class),
                    ("action_id", action_id),
                    ("status", "completed"),
                    ("evidence_path", evidence_path.as_str()),
                ],
            ),
        )?;
        write_program_recovery_action_summary(
            repo_root,
            &action_root,
            action_id,
            blocker_class,
            "completed",
            None,
            None,
        )?;
        return Ok(ProgramRecoveryActionOutcome {
            action_id: action_id.to_string(),
            blocker_class: blocker_class.to_string(),
            status: "completed".to_string(),
            evidence_path,
            failed_command: None,
            error_message: None,
        });
    }

    let commands: Vec<(&str, Vec<String>, Vec<(&str, String)>)> = vec![
        (
            "publish-extension-state",
            vec![
                ".octon/framework/orchestration/runtime/_ops/scripts/publish-extension-state.sh"
                    .to_string(),
            ],
            Vec::new(),
        ),
        (
            "publish-capability-routing",
            vec![
                ".octon/framework/capabilities/_ops/scripts/publish-capability-routing.sh"
                    .to_string(),
            ],
            Vec::new(),
        ),
        (
            "publish-host-projections",
            vec![PUBLISH_HOST_PROJECTIONS_COMMAND.to_string()],
            Vec::new(),
        ),
        (
            "publish-pack-routes",
            vec![
                ".octon/framework/assurance/runtime/_ops/scripts/publish-pack-routes.sh"
                    .to_string(),
            ],
            Vec::new(),
        ),
        (
            "publish-runtime-route-bundle",
            vec![
                ".octon/framework/assurance/runtime/_ops/scripts/publish-runtime-route-bundle.sh"
                    .to_string(),
            ],
            Vec::new(),
        ),
        (
            "generate-run-health-read-model",
            vec![
                GENERATE_RUN_HEALTH_READ_MODEL_COMMAND.to_string(),
                "--all-runs".to_string(),
            ],
            Vec::new(),
        ),
        (
            "validate-publication-freshness-gates",
            vec![VALIDATE_PUBLICATION_FRESHNESS_GATES_COMMAND.to_string()],
            Vec::new(),
        ),
    ];

    let mut publication_freshness_pass_summary: Option<(String, String, String, i32)> = None;
    for (index, (command_id, argv, extra_env)) in commands.iter().enumerate() {
        let command_index = index + 1;
        let stdout_path = action_root.join(format!("{command_index:02}-{command_id}.stdout.log"));
        let stderr_path = action_root.join(format!("{command_index:02}-{command_id}.stderr.log"));
        let result_path = action_root.join(format!("{command_index:02}-{command_id}.result.yml"));
        let output = run_program_recovery_command(
            repo_root,
            &octon_dir,
            argv,
            extra_env,
            &stdout_path,
            &stderr_path,
        )?;
        let exit_code_value = output.status.code().unwrap_or(-1);
        let exit_code = exit_code_value.to_string();
        let status = if output.status.success() {
            "completed"
        } else {
            "failed"
        };
        fs::write(
            &result_path,
            format!(
                "schema_version: \"octon-program-recovery-action-command-v1\"\naction_id: \"{action_id}\"\nblocker_class: \"{blocker_class}\"\ncommand_id: \"{command_id}\"\nstatus: \"{status}\"\nexit_code: {exit_code}\nstdout_path: \"{}\"\nstderr_path: \"{}\"\n",
                rel_display(repo_root, &stdout_path),
                rel_display(repo_root, &stderr_path)
            ),
        )?;
        if !output.status.success() {
            let message =
                format!("program recovery action {action_id} failed at command {command_id}");
            let evidence_path = rel_display(repo_root, &action_root);
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "program-recovery-action-validation-failed",
                None,
                Some(action_id),
                "program recovery action validation failed",
                program_step_event_data(
                    step_context.as_ref(),
                    "program-recovery-action",
                    [
                        ("blocker_class", blocker_class),
                        ("action_id", action_id),
                        ("failed_command", command_id),
                        ("evidence_path", evidence_path.as_str()),
                    ],
                ),
            )?;
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "program-recovery-action-finished",
                None,
                Some(action_id),
                "program recovery action finished with failure",
                program_step_event_data(
                    step_context.as_ref(),
                    "program-recovery-action",
                    [
                        ("blocker_class", blocker_class),
                        ("action_id", action_id),
                        ("status", "failed"),
                        ("failed_command", command_id),
                        ("evidence_path", evidence_path.as_str()),
                    ],
                ),
            )?;
            write_program_recovery_action_summary(
                repo_root,
                &action_root,
                action_id,
                blocker_class,
                "failed",
                Some(command_id),
                Some(&message),
            )?;
            return Ok(ProgramRecoveryActionOutcome {
                action_id: action_id.to_string(),
                blocker_class: blocker_class.to_string(),
                status: "failed".to_string(),
                evidence_path,
                failed_command: Some(command_id.to_string()),
                error_message: Some(message),
            });
        }
        if *command_id == "generate-run-health-read-model" {
            let recovery_run_health_root = action_root.join("run-health");
            fs::create_dir_all(&recovery_run_health_root)?;
            let generation_receipt = repo_root
                .join(PROGRAM_RECOVERY_RUN_HEALTH_EVIDENCE_ROOT_REL)
                .join("generation.yml");
            fs::copy(
                &generation_receipt,
                recovery_run_health_root.join("generation.yml"),
            )
            .with_context(|| {
                format!(
                    "program recovery action {action_id} could not bind run-health generation receipt: {}",
                    generation_receipt.display()
                )
            })?;
        }
        if *command_id == "validate-publication-freshness-gates" {
            publication_freshness_pass_summary = Some((
                publication_freshness_evidence_digest_from_parts(
                    true,
                    &output.stdout,
                    &output.stderr,
                    exit_code_value,
                ),
                rel_display(repo_root, &stdout_path),
                rel_display(repo_root, &stderr_path),
                exit_code_value,
            ));
        }
    }

    if action_id == REFRESH_PUBLICATION_PROJECTIONS_ACTION {
        let Some((
            publication_freshness_digest,
            validation_stdout_path,
            validation_stderr_path,
            validation_exit_code,
        )) = publication_freshness_pass_summary
        else {
            bail!("publication projection refresh did not run the publication freshness validator");
        };
        let preflight_root = evidence_root.join("publication-freshness-preflight");
        fs::create_dir_all(&preflight_root)?;
        fs::write(
            preflight_root.join("summary.yml"),
            format!(
                "schema_version: \"octon-program-publication-freshness-preflight-v1\"\nstatus: \"pass\"\nblocker_class: \"none\"\nrecovery_action_id: \"{REFRESH_PUBLICATION_PROJECTIONS_ACTION}\"\npublication_freshness_digest: {}\ncanonical_recovery_commands:\n{}selected_children:\n{}stdout_path: {}\nstderr_path: {}\nexit_code: {validation_exit_code}\ngenerated_outputs_authority: \"derived-only\"\nrecovered_by_action_id: \"{REFRESH_PUBLICATION_PROJECTIONS_ACTION}\"\nrecovery_evidence_path: {}\n",
                yaml_scalar(&publication_freshness_digest),
                yaml_list(&canonical_publication_recovery_commands()),
                yaml_list(&Vec::<String>::new()),
                yaml_scalar(&validation_stdout_path),
                yaml_scalar(&validation_stderr_path),
                yaml_scalar(&rel_display(repo_root, &action_root)),
            ),
        )?;
    }

    write_program_recovery_changed_paths(repo_root, &action_root)?;
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "program-recovery-action-finished",
        None,
        Some(action_id),
        "program recovery action finished",
        program_step_event_data(
            step_context.as_ref(),
            "program-recovery-action",
            [
                ("blocker_class", blocker_class),
                ("action_id", action_id),
                ("status", "completed"),
            ],
        ),
    )?;
    write_program_recovery_action_summary(
        repo_root,
        &action_root,
        action_id,
        blocker_class,
        "completed",
        None,
        None,
    )?;
    Ok(ProgramRecoveryActionOutcome {
        action_id: action_id.to_string(),
        blocker_class: blocker_class.to_string(),
        status: "completed".to_string(),
        evidence_path: rel_display(repo_root, &action_root),
        failed_command: None,
        error_message: None,
    })
}

fn run_program_recovery_command(
    repo_root: &Path,
    octon_dir: &Path,
    argv: &[String],
    extra_env: &Vec<(&str, String)>,
    stdout_path: &Path,
    stderr_path: &Path,
) -> Result<std::process::Output> {
    let (script, args) = argv
        .split_first()
        .context("program recovery command missing script")?;
    let mut command = program_lifecycle_command(repo_root, "bash")?;
    command
        .arg(script)
        .args(args)
        .current_dir(repo_root)
        .env("OCTON_DIR_OVERRIDE", octon_dir)
        .env("OCTON_ROOT_DIR", repo_root);
    for (key, value) in extra_env {
        command.env(key, value);
    }
    let output = command.output()?;
    fs::write(stdout_path, &output.stdout)?;
    fs::write(stderr_path, &output.stderr)?;
    Ok(output)
}

#[derive(Debug, Deserialize)]
struct ProgramRecoveryRunHealthGenerationReceipt {
    schema_version: String,
    #[serde(default)]
    published_paths: Vec<String>,
    #[serde(default)]
    pruned_paths: Vec<String>,
    #[serde(default)]
    outputs: Vec<ProgramRecoveryRunHealthGenerationOutput>,
}

#[derive(Debug, Deserialize)]
struct ProgramRecoveryRunHealthGenerationOutput {
    #[serde(default)]
    health_ref: String,
}

fn validate_program_recovery_repo_relative_path(path: &str, field: &str) -> Result<()> {
    if !is_safe_repo_relative(path) {
        bail!(
            "program recovery run-health receipt {field} path must be safe repo-relative: {path}"
        );
    }
    Ok(())
}

fn parse_git_status_path(line: &str) -> Option<String> {
    let raw = line.get(3..)?.trim();
    if raw.is_empty() {
        return None;
    }
    let path = raw
        .rsplit_once(" -> ")
        .map(|(_, current)| current.trim())
        .unwrap_or(raw);
    if path.is_empty() {
        None
    } else {
        Some(path.to_string())
    }
}

fn read_program_recovery_run_health_changed_paths(
    repo_root: &Path,
    action_root: &Path,
) -> Result<BTreeSet<String>> {
    let receipt_path = action_root.join("run-health").join("generation.yml");
    let bytes = fs::read(&receipt_path).with_context(|| {
        format!(
            "program recovery run-health generation receipt missing: {}",
            receipt_path.display()
        )
    })?;
    let receipt: ProgramRecoveryRunHealthGenerationReceipt = serde_yaml::from_slice(&bytes)
        .with_context(|| {
            format!(
                "program recovery run-health generation receipt is not valid YAML: {}",
                receipt_path.display()
            )
        })?;
    if receipt.schema_version != "run-health-generation-receipt-v1" {
        bail!(
            "program recovery run-health generation receipt has unsupported schema_version: {}",
            receipt.schema_version
        );
    }
    if receipt.published_paths.is_empty() {
        bail!("program recovery run-health generation receipt must publish at least one path");
    }
    if receipt.outputs.is_empty() {
        bail!("program recovery run-health generation receipt must include outputs");
    }

    let mut published = BTreeSet::new();
    for path in &receipt.published_paths {
        validate_program_recovery_repo_relative_path(path, "published_paths")?;
        if !published.insert(path.clone()) {
            bail!("program recovery run-health generation receipt contains duplicate published_paths entry: {path}");
        }
        if !repo_root.join(path).is_file() {
            bail!("program recovery run-health generation receipt published path is missing on disk: {path}");
        }
    }

    let mut pruned = BTreeSet::new();
    for path in &receipt.pruned_paths {
        validate_program_recovery_repo_relative_path(path, "pruned_paths")?;
        if !pruned.insert(path.clone()) {
            bail!("program recovery run-health generation receipt contains duplicate pruned_paths entry: {path}");
        }
        if published.contains(path) {
            bail!("program recovery run-health generation receipt path appears in both published_paths and pruned_paths: {path}");
        }
        if repo_root.join(path).exists() {
            bail!("program recovery run-health generation receipt pruned path still exists on disk: {path}");
        }
    }

    for output in &receipt.outputs {
        if output.health_ref.trim().is_empty() {
            bail!("program recovery run-health generation receipt output health_ref must not be empty");
        }
        validate_program_recovery_repo_relative_path(&output.health_ref, "outputs.health_ref")?;
        if !published.contains(&output.health_ref) {
            bail!(
                "program recovery run-health generation receipt output health_ref is missing from published_paths: {}",
                output.health_ref
            );
        }
    }

    let mut changed_paths = published;
    changed_paths.extend(pruned);
    Ok(changed_paths)
}

fn write_program_recovery_changed_paths(repo_root: &Path, action_root: &Path) -> Result<()> {
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .arg("status")
        .arg("--short")
        .arg("--")
        .arg(".octon/generated")
        .arg(PROGRAM_RECOVERY_RUN_HEALTH_EVIDENCE_ROOT_REL)
        .arg(".octon/state/evidence/validation/publication")
        .arg(".claude/commands")
        .arg(".claude/skills")
        .arg(".cursor/commands")
        .arg(".cursor/skills")
        .arg(".codex/commands")
        .arg(".codex/skills")
        .output()?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut changed_paths = stdout
        .lines()
        .filter_map(parse_git_status_path)
        .filter(|path| {
            rel_path_under(path, ".octon/generated")
                || rel_path_under(path, ".octon/state/evidence/validation/publication")
                || rel_path_under(path, ".claude/commands")
                || rel_path_under(path, ".claude/skills")
                || rel_path_under(path, ".cursor/commands")
                || rel_path_under(path, ".cursor/skills")
                || rel_path_under(path, ".codex/commands")
                || rel_path_under(path, ".codex/skills")
                || path.ends_with("support-envelope-reconciliation.yml")
                || rel_path_under(path, PROGRAM_RECOVERY_RUN_HEALTH_EVIDENCE_ROOT_REL)
        })
        .collect::<BTreeSet<_>>();
    if action_root
        .join("run-health")
        .join("generation.yml")
        .is_file()
    {
        changed_paths.extend(read_program_recovery_run_health_changed_paths(
            repo_root,
            action_root,
        )?);
    }
    let changed_paths = if changed_paths.is_empty() {
        String::new()
    } else {
        let mut text = changed_paths.into_iter().collect::<Vec<_>>().join("\n");
        text.push('\n');
        text
    };
    fs::write(action_root.join("changed-paths.txt"), changed_paths)?;
    Ok(())
}

fn write_program_recovery_action_summary(
    repo_root: &Path,
    action_root: &Path,
    action_id: &str,
    blocker_class: &str,
    status: &str,
    failed_command: Option<&str>,
    error_message: Option<&str>,
) -> Result<()> {
    let failed_command = failed_command.unwrap_or("");
    let error_message = error_message.unwrap_or("");
    fs::write(
        action_root.join("summary.yml"),
        format!(
            "schema_version: \"octon-program-recovery-action-v1\"\naction_id: \"{action_id}\"\nblocker_class: \"{blocker_class}\"\nstatus: \"{status}\"\nfailed_command: \"{failed_command}\"\nerror_message: \"{error_message}\"\nevidence_path: \"{}\"\n",
            rel_display(repo_root, action_root)
        ),
    )?;
    Ok(())
}

fn recovery_recipe_matches(recipe: &ProgramRecoveryRecipeSpec, blocker_class: &str) -> bool {
    recipe.blocker_class == blocker_class
}

fn execute_atomic_program(
    octon_dir: &Path,
    repo_root: &Path,
    program_run_id: &str,
    run_inputs: &BTreeMap<String, String>,
    options: &RunLifecycleOptions,
    plan: &ProgramLifecyclePlanResult,
    evidence_root: &Path,
    control_root: &Path,
    approvals: Option<&Vec<ProgramApprovalGrant>>,
) -> Result<Vec<ProgramChildExecutionSummary>> {
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "atomic-preflight",
        None,
        None,
        "program-atomic preflight started",
        BTreeMap::new(),
    )?;
    if !plan.program_blockers.is_empty() {
        bail!("program-atomic preflight blocked by program blockers");
    }
    if !plan.approval_blockers.is_empty() {
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "approval-pause",
            None,
            None,
            "program-atomic paused for approval",
            BTreeMap::new(),
        )?;
        return Ok(plan
            .approval_blockers
            .iter()
            .map(|blocker| ProgramChildExecutionSummary {
                child_id: blocker.child_id.clone(),
                child_run_id: format!("{program_run_id}-{}", blocker.child_id),
                route_id: blocker.route_id.clone(),
                status: "human-boundary-blocked".to_string(),
                attempts: 0,
                retryable: false,
                blocker_class: Some(
                    blocker
                        .blocker_class
                        .clone()
                        .unwrap_or_else(|| "authority-ambiguity".to_string()),
                ),
                error_message: Some(blocker.reason.clone()),
                error_class: None,
                evidence_paths: Vec::new(),
                worktree_hygiene_foreign_fingerprint: None,
            })
            .collect());
    }
    let participants = plan
        .child_states
        .values()
        .filter(|state| state.required && !state.deferred && state.terminal_outcome.is_none())
        .collect::<Vec<_>>();
    if participants.is_empty() {
        return Ok(Vec::new());
    }
    let runnable = plan.runnable_batch.iter().cloned().collect::<BTreeSet<_>>();
    let missing_runnable = participants
        .iter()
        .filter(|state| !runnable.contains(&state.child_id))
        .map(|state| state.child_id.clone())
        .collect::<Vec<_>>();
    if !missing_runnable.is_empty() {
        return Ok(missing_runnable
            .into_iter()
            .map(|child_id| {
                ProgramChildExecutionSummary {
                    child_id: child_id.clone(),
                    child_run_id: format!("{program_run_id}-{child_id}-atomic-preflight"),
                    route_id: "program-atomic".to_string(),
                    status: "blocked-unsafe".to_string(),
                    attempts: 0,
                    retryable: false,
                    blocker_class: Some("unsafe-resume".to_string()),
                    error_message: Some(
                        "program-atomic requires every required non-deferred participant to be runnable"
                            .to_string(),
                    ),
                    error_class: None,
                    evidence_paths: Vec::new(),
                    worktree_hygiene_foreign_fingerprint: None,
                }
            })
            .collect());
    }
    let previous_barrier =
        reconstruct_atomic_barrier_state(&read_program_events(control_root)?).unwrap_or_default();

    let mut locks = Vec::new();
    for state in &participants {
        let lock_path = match acquire_child_lock(control_root, &state.child_id) {
            Ok(lock_path) => lock_path,
            Err(error) => {
                let error_message = error.to_string();
                release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
                append_program_event(
                    control_root,
                    evidence_root,
                    program_run_id,
                    "atomic-lock-stale",
                    Some(&state.child_id),
                    None,
                    "program-atomic encountered stale or unsafe child lock",
                    event_data([("error", error_message.as_str())]),
                )?;
                return Ok(vec![ProgramChildExecutionSummary {
                    child_id: state.child_id.clone(),
                    child_run_id: format!("{program_run_id}-{}-atomic-lock", state.child_id),
                    route_id: "program-atomic".to_string(),
                    status: "blocked-unsafe".to_string(),
                    attempts: 0,
                    retryable: false,
                    blocker_class: Some("unsafe-resume".to_string()),
                    error_message: Some(error_message),
                    error_class: None,
                    evidence_paths: Vec::new(),
                    worktree_hygiene_foreign_fingerprint: None,
                }]);
            }
        };
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "atomic-lock-acquired",
            Some(&state.child_id),
            None,
            "program-atomic acquired child lock",
            BTreeMap::new(),
        )?;
        locks.push((state.child_id.clone(), lock_path));
    }

    let executor = DefaultLifecycleRouteExecutor::new(repo_root.to_path_buf());
    let mut summaries = Vec::new();
    let mut staged = Vec::new();
    let mut atomic_specs = BTreeMap::new();

    for state in &participants {
        let source_route = state
            .selected_route
            .as_ref()
            .context("program-atomic child missing selected route")?;
        let child_contract = load_lifecycle_contract(octon_dir, &state.child_lifecycle_id)?;
        let atomic = atomic_spec_for_route(&child_contract.contract, &source_route.route_id)?;
        atomic_specs.insert(state.child_id.clone(), atomic.clone());
        if previous_barrier
            .staged_children
            .iter()
            .any(|child_id| child_id == &state.child_id)
        {
            staged.push(state.child_id.clone());
            continue;
        }
        let summary = match execute_atomic_route_phase(
            octon_dir,
            &executor,
            program_run_id,
            run_inputs,
            options,
            state,
            &atomic.stage_route_id,
            "atomic-stage",
            evidence_root,
            control_root,
            approvals,
        ) {
            Ok(summary) => summary,
            Err(error) => {
                let error_message = error.to_string();
                rollback_atomic_children(
                    octon_dir,
                    &executor,
                    program_run_id,
                    run_inputs,
                    options,
                    plan,
                    &atomic_specs,
                    &staged,
                    evidence_root,
                    control_root,
                    "atomic-rollback",
                    approvals,
                )?
                .into_iter()
                .for_each(|summary| summaries.push(summary));
                release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
                summaries.push(ProgramChildExecutionSummary {
                    child_id: state.child_id.clone(),
                    child_run_id: format!("{program_run_id}-{}-atomic-stage", state.child_id),
                    route_id: atomic.stage_route_id.clone(),
                    status: "blocked-unsafe".to_string(),
                    attempts: 0,
                    retryable: false,
                    blocker_class: Some("unsafe-resume".to_string()),
                    error_message: Some(error_message),
                    error_class: None,
                    evidence_paths: Vec::new(),
                    worktree_hygiene_foreign_fingerprint: None,
                });
                return Ok(summaries);
            }
        };
        let completed = summary.status == "completed";
        summaries.push(summary);
        if completed {
            staged.push(state.child_id.clone());
        } else {
            rollback_atomic_children(
                octon_dir,
                &executor,
                program_run_id,
                run_inputs,
                options,
                plan,
                &atomic_specs,
                &staged,
                evidence_root,
                control_root,
                "atomic-rollback",
                approvals,
            )?
            .into_iter()
            .for_each(|summary| summaries.push(summary));
            release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
            return Ok(summaries);
        }
    }

    let staged_children = staged.join(",");
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "atomic-barrier-verified",
        None,
        None,
        "program-atomic barrier verified after all required children staged",
        event_data([("staged_children", staged_children.as_str())]),
    )?;

    let mut committed = Vec::new();
    for state in &participants {
        if previous_barrier
            .committed_children
            .iter()
            .any(|child_id| child_id == &state.child_id)
        {
            committed.push(state.child_id.clone());
            continue;
        }
        let atomic = atomic_specs
            .get(&state.child_id)
            .context("missing atomic metadata after stage")?;
        let summary = match execute_atomic_route_phase(
            octon_dir,
            &executor,
            program_run_id,
            run_inputs,
            options,
            state,
            &atomic.commit_route_id,
            "atomic-commit",
            evidence_root,
            control_root,
            approvals,
        ) {
            Ok(summary) => summary,
            Err(error) => {
                let error_message = error.to_string();
                let compensation = rollback_atomic_children(
                    octon_dir,
                    &executor,
                    program_run_id,
                    run_inputs,
                    options,
                    plan,
                    &atomic_specs,
                    &committed,
                    evidence_root,
                    control_root,
                    "atomic-compensation",
                    approvals,
                )?;
                summaries.extend(compensation);
                release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
                summaries.push(ProgramChildExecutionSummary {
                    child_id: state.child_id.clone(),
                    child_run_id: format!("{program_run_id}-{}-atomic-commit", state.child_id),
                    route_id: atomic.commit_route_id.clone(),
                    status: "blocked-unsafe".to_string(),
                    attempts: 0,
                    retryable: false,
                    blocker_class: Some("unsafe-resume".to_string()),
                    error_message: Some(error_message),
                    error_class: None,
                    evidence_paths: Vec::new(),
                    worktree_hygiene_foreign_fingerprint: None,
                });
                return Ok(summaries);
            }
        };
        let completed = summary.status == "completed";
        summaries.push(summary);
        if completed {
            committed.push(state.child_id.clone());
        } else {
            let compensation = rollback_atomic_children(
                octon_dir,
                &executor,
                program_run_id,
                run_inputs,
                options,
                plan,
                &atomic_specs,
                &committed,
                evidence_root,
                control_root,
                "atomic-compensation",
                approvals,
            )?;
            if compensation
                .iter()
                .any(|summary| summary.status != "completed")
            {
                summaries.extend(compensation);
                summaries.push(ProgramChildExecutionSummary {
                    child_id: state.child_id.clone(),
                    child_run_id: format!("{program_run_id}-{}-atomic-unsafe", state.child_id),
                    route_id: "program-atomic".to_string(),
                    status: "blocked-unsafe".to_string(),
                    attempts: 0,
                    retryable: false,
                    blocker_class: Some("authority-boundary-ambiguous".to_string()),
                    error_message: Some(
                        "program-atomic commit failed and compensation did not complete"
                            .to_string(),
                    ),
                    error_class: None,
                    evidence_paths: Vec::new(),
                    worktree_hygiene_foreign_fingerprint: None,
                });
            } else {
                summaries.extend(compensation);
            }
            release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
            return Ok(summaries);
        }
    }

    release_atomic_locks(control_root, evidence_root, program_run_id, locks)?;
    Ok(summaries)
}

fn execute_atomic_route_phase(
    octon_dir: &Path,
    executor: &DefaultLifecycleRouteExecutor,
    program_run_id: &str,
    run_inputs: &BTreeMap<String, String>,
    options: &RunLifecycleOptions,
    state: &ProgramChildPlanState,
    route_id: &str,
    phase: &str,
    evidence_root: &Path,
    control_root: &Path,
    approvals: Option<&Vec<ProgramApprovalGrant>>,
) -> Result<ProgramChildExecutionSummary> {
    let child_contract = load_lifecycle_contract(octon_dir, &state.child_lifecycle_id)?;
    let route = route_by_id(&child_contract.contract, route_id)
        .with_context(|| format!("program-atomic {phase} route missing: {route_id}"))?;
    let route_plan = route_plan_state(route.clone());
    let child_run_id = sanitize_run_id(&format!("{program_run_id}-{}-{phase}", state.child_id))?;
    let child_evidence_root = evidence_root
        .join("children")
        .join(&state.child_id)
        .join(phase);
    let child_control_root = control_root
        .join("children")
        .join(&state.child_id)
        .join(phase);
    fs::create_dir_all(&child_evidence_root)?;
    fs::create_dir_all(&child_control_root)?;
    let repo_root = repo_root_for_octon(octon_dir)?;
    let authority_decision = child_route_authority_decision(
        &repo_root,
        program_run_id,
        state,
        route_id,
        OPERATION_CLASS_EXECUTE_CHILD_ROUTE,
    );
    let invocation_authority = invocation_authority_for_child_route(
        &options.invocation_authority,
        approvals,
        &state.child_id,
        route_id,
        None,
        None,
        route_spec_delegation_contract_basis(route_id, route).is_some(),
        Some(&authority_decision),
    );
    let authority_decision_path =
        write_authority_zone_decision(evidence_root, &authority_decision)?;
    let atomic_authority_allowed = invocation_authority == "grant-consumption"
        || authority_decision.autonomous_allowed
        || (authority_decision.authority_zone == AUTHORITY_ZONE_WORKSPACE_DECLARED
            && authority_decision.workspace_contained
            && authority_decision.declared_scope_contained
            && route.route_type != "workflow")
        || (invocation_authority == "unattended"
            && route_spec_delegation_contract_basis(route_id, route).is_some()
            && authority_decision_allows_route_unattended(&authority_decision));
    if !atomic_authority_allowed {
        let dispatch_blocker_class = if authority_decision.authority_zone
            == AUTHORITY_ZONE_WORKSPACE_DECLARED
            && route.route_type == "workflow"
        {
            "authority-ambiguity".to_string()
        } else {
            authority_decision.fail_closed_blocker.clone()
        };
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "atomic-child-route-authority-blocked",
            Some(&state.child_id),
            Some(route_id),
            "program atomic child route blocked by authority-zone decision",
            event_data([
                ("authority_zone", authority_decision.authority_zone.as_str()),
                ("artifact_class", authority_decision.artifact_class.as_str()),
                ("authority_decision", authority_decision_path.as_str()),
            ]),
        )?;
        return Ok(ProgramChildExecutionSummary {
            child_id: state.child_id.clone(),
            child_run_id,
            route_id: route_id.to_string(),
            status: if dispatch_blocker_class == "authority-ambiguity" {
                "human-boundary-blocked".to_string()
            } else if classify_program_blocker_class(&dispatch_blocker_class)
                == ProgramBlockerDisposition::Unsafe
            {
                "blocked-unsafe".to_string()
            } else {
                "blocked-human".to_string()
            },
            attempts: 0,
            retryable: false,
            blocker_class: Some(dispatch_blocker_class),
            error_message: Some(format!(
                "authority zone {} does not permit atomic route dispatch for artifact class {}",
                authority_decision.authority_zone, authority_decision.artifact_class
            )),
            error_class: Some("authority-zone".to_string()),
            evidence_paths: vec![authority_decision_path],
            worktree_hygiene_foreign_fingerprint: None,
        });
    }
    if invocation_authority == "grant-consumption" {
        write_program_approval_execution_evidence(
            &repo_root,
            &child_evidence_root,
            program_run_id,
            &state.child_id,
            route_id,
            None,
            None,
            approvals,
        )?;
    }
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        phase,
        Some(&state.child_id),
        Some(route_id),
        "program-atomic route phase started",
        BTreeMap::new(),
    )?;
    let child_target_abs = resolve_lifecycle_target_path(&repo_root, Path::new(&state.target))?;
    let route_gate_results = run_required_gates(
        &repo_root,
        &child_contract.contract,
        &child_target_abs,
        route_id,
    )?;
    let request = lifecycle_execution_request_for_route(
        octon_dir,
        &child_run_id,
        &state.child_lifecycle_id,
        &state.target,
        Some(phase),
        &route_plan,
        options.executor,
        options.timeout_seconds.unwrap_or(1800),
        &invocation_authority,
        0,
        run_inputs,
        &route_gate_results,
        child_evidence_root,
        child_control_root.join("lifecycle-checkpoint.yml"),
        Some(lifecycle_cancellation_token_path(control_root)),
        Some(program_child_approval_context(
            program_run_id,
            &state.child_id,
            &child_run_id,
            &state.child_lifecycle_id,
            &state.target,
            route_id,
        )),
    )?
    .with_context(|| format!("failed to build program-atomic request for {route_id}"))?;
    let result = executor.execute_route(request)?;
    append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        &format!("{phase}-finished"),
        Some(&state.child_id),
        Some(route_id),
        "program-atomic route phase finished",
        event_data([("status", result.status.as_str())]),
    )?;
    Ok(ProgramChildExecutionSummary {
        child_id: state.child_id.clone(),
        child_run_id,
        route_id: route_id.to_string(),
        status: result.status,
        attempts: 1,
        retryable: result.retryable,
        blocker_class: None,
        error_message: result.error_message.clone(),
        error_class: result
            .error_class
            .as_ref()
            .map(|class| class.as_str().to_string()),
        evidence_paths: result
            .evidence_paths
            .iter()
            .map(|path| rel_path_string(path))
            .collect(),
        worktree_hygiene_foreign_fingerprint: None,
    })
}

fn rollback_atomic_children(
    octon_dir: &Path,
    executor: &DefaultLifecycleRouteExecutor,
    program_run_id: &str,
    run_inputs: &BTreeMap<String, String>,
    options: &RunLifecycleOptions,
    plan: &ProgramLifecyclePlanResult,
    atomic_specs: &BTreeMap<String, RouteAtomicSpec>,
    child_ids: &[String],
    evidence_root: &Path,
    control_root: &Path,
    phase: &str,
    approvals: Option<&Vec<ProgramApprovalGrant>>,
) -> Result<Vec<ProgramChildExecutionSummary>> {
    let mut summaries = Vec::new();
    for child_id in child_ids.iter().rev() {
        let Some(state) = plan.child_states.get(child_id) else {
            continue;
        };
        let Some(atomic) = atomic_specs.get(child_id) else {
            continue;
        };
        let route_id = if phase == "atomic-compensation" {
            atomic.compensation_route_id.as_deref()
        } else {
            atomic.rollback_route_id.as_deref()
        };
        let Some(route_id) = route_id else {
            summaries.push(ProgramChildExecutionSummary {
                child_id: child_id.clone(),
                child_run_id: format!("{program_run_id}-{child_id}-{phase}"),
                route_id: phase.to_string(),
                status: "blocked-unsafe".to_string(),
                attempts: 0,
                retryable: false,
                blocker_class: Some("authority-boundary-ambiguous".to_string()),
                error_message: Some("missing rollback or compensation route".to_string()),
                error_class: None,
                evidence_paths: Vec::new(),
                worktree_hygiene_foreign_fingerprint: None,
            });
            continue;
        };
        summaries.push(execute_atomic_route_phase(
            octon_dir,
            executor,
            program_run_id,
            run_inputs,
            options,
            state,
            route_id,
            phase,
            evidence_root,
            control_root,
            approvals,
        )?);
    }
    Ok(summaries)
}

fn release_atomic_locks(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    locks: Vec<(String, PathBuf)>,
) -> Result<()> {
    for (child_id, lock_path) in locks {
        let operation = ProgramArtifactOperation {
            operation_id: format!("remove_atomic_child_lock-{child_id}-program-atomic"),
            child_id: child_id.clone(),
            route_id: "program-atomic".to_string(),
            operation: "remove_atomic_child_lock".to_string(),
            destructive_operation: "remove_file".to_string(),
            artifact_paths: vec![lock_path.clone()],
            command_or_operation: "fs::remove_file".to_string(),
        };
        let criticality_evidence = match perform_governed_artifact_cleanup(
            control_root,
            evidence_root,
            program_run_id,
            &operation,
        ) {
            Ok(path) => path,
            Err(error) => {
                let error_message = error.to_string();
                append_program_event(
                    control_root,
                    evidence_root,
                    program_run_id,
                    "atomic-lock-stale",
                    Some(&child_id),
                    None,
                    "program-atomic could not release child lock",
                    event_data([("error", error_message.as_str())]),
                )?;
                bail!(
                    "program-atomic could not release child lock for {child_id}: {error_message}"
                );
            }
        };
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "atomic-lock-released",
            Some(&child_id),
            None,
            "program-atomic released child lock",
            event_data([("criticality_evidence", criticality_evidence.as_str())]),
        )?;
    }
    Ok(())
}

fn execute_child_jobs(
    repo_root: &Path,
    program_run_id: &str,
    control_root: &Path,
    evidence_root: &Path,
    jobs: Vec<ChildExecutionJob>,
    max_concurrency: usize,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<Vec<ProgramChildExecutionSummary>> {
    let executor = DefaultLifecycleRouteExecutor::new(repo_root.to_path_buf());
    let mut summaries = Vec::new();
    let mut pending = jobs.into_iter().collect::<VecDeque<_>>();
    while !pending.is_empty() {
        let chunk = (0..max_concurrency)
            .filter_map(|_| pending.pop_front())
            .collect::<Vec<ChildExecutionJob>>();
        if chunk.is_empty() {
            break;
        }
        for job in &chunk {
            if let Err(error) = append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "child-route-started",
                Some(&job.child_id),
                Some(&job.route_id),
                "child route execution started",
                program_step_event_data(
                    step_context.as_ref(),
                    "child-batch-dispatch",
                    std::iter::empty::<(&str, &str)>(),
                ),
            ) {
                release_child_locks_after_build_failure(
                    control_root,
                    evidence_root,
                    program_run_id,
                    &chunk,
                )?;
                return Err(error);
            }
            if let Some(blocker_class) = job.blocker_class.as_deref() {
                if let Err(error) = append_program_event(
                    control_root,
                    evidence_root,
                    program_run_id,
                    "recovery-attempt",
                    Some(&job.child_id),
                    Some(&job.route_id),
                    "child recovery route execution started",
                    program_step_event_data(
                        step_context.as_ref(),
                        "child-batch-dispatch",
                        [("blocker_class", blocker_class)],
                    ),
                ) {
                    release_child_locks_after_build_failure(
                        control_root,
                        evidence_root,
                        program_run_id,
                        &chunk,
                    )?;
                    return Err(error);
                }
            }
        }
        let mut handles = Vec::new();
        let mut lock_records = Vec::new();
        for job in chunk {
            lock_records.push((
                job.child_id.clone(),
                job.route_id.clone(),
                job.lock_path.clone(),
            ));
            let executor = executor.clone();
            handles.push(thread::spawn(move || execute_child_job(executor, job)));
        }
        for (handle, (child_id, route_id, lock_path)) in
            handles.into_iter().zip(lock_records.into_iter())
        {
            let outcome = match handle.join() {
                Ok(Ok(outcome)) => outcome,
                Ok(Err(error)) => {
                    release_child_lock(
                        control_root,
                        evidence_root,
                        program_run_id,
                        &child_id,
                        &route_id,
                        &lock_path,
                    )?;
                    return Err(error);
                }
                Err(_) => {
                    release_child_lock(
                        control_root,
                        evidence_root,
                        program_run_id,
                        &child_id,
                        &route_id,
                        &lock_path,
                    )?;
                    return Err(anyhow::anyhow!(
                        "program child executor thread panicked for {child_id}"
                    ));
                }
            };
            let summary = finish_child_execution(
                control_root,
                evidence_root,
                program_run_id,
                outcome,
                step_context,
            )?;
            let child_cancelled = summary.status == "cancelled";
            summaries.push(summary);
            if child_cancelled {
                release_pending_child_locks_after_cancellation(
                    control_root,
                    evidence_root,
                    program_run_id,
                    pending,
                    step_context,
                )?;
                append_program_event(
                    control_root,
                    evidence_root,
                    program_run_id,
                    "cancelled",
                    Some(&child_id),
                    Some(&route_id),
                    "program lifecycle cancellation observed during child route dispatch",
                    program_step_event_data(
                        step_context.as_ref(),
                        "child-batch-dispatch",
                        [("final_verdict", "cancelled")],
                    ),
                )?;
                return Ok(summaries);
            }
        }
    }
    Ok(summaries)
}

fn release_pending_child_locks_after_cancellation(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    pending: VecDeque<ChildExecutionJob>,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<()> {
    for job in pending {
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "child-route-skipped-cancelled",
            Some(&job.child_id),
            Some(&job.route_id),
            "program child route skipped because cancellation was observed before dispatch",
            program_step_event_data(
                step_context.as_ref(),
                "child-batch-dispatch",
                [("final_verdict", "cancelled")],
            ),
        )?;
        release_child_lock(
            control_root,
            evidence_root,
            program_run_id,
            &job.child_id,
            &job.route_id,
            &job.lock_path,
        )?;
    }
    Ok(())
}

fn finish_child_execution(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    outcome: ChildExecutionOutcome,
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<ProgramChildExecutionSummary> {
    let summary = outcome.summary;
    let attempts = summary.attempts.to_string();
    let finish_event = append_program_event(
        control_root,
        evidence_root,
        program_run_id,
        "child-route-finished",
        Some(&summary.child_id),
        Some(&summary.route_id),
        "child route execution finished",
        program_step_event_data(
            step_context.as_ref(),
            "child-batch-dispatch",
            [
                ("status", summary.status.as_str()),
                ("attempts", attempts.as_str()),
            ],
        ),
    );
    let release = release_child_lock(
        control_root,
        evidence_root,
        program_run_id,
        &summary.child_id,
        &summary.route_id,
        &outcome.lock_path,
    );
    match (finish_event, release) {
        (Ok(_), Ok(())) => Ok(summary),
        (Err(finish_error), Ok(())) => Err(finish_error).with_context(|| {
            format!(
                "program child finish event append failed after execution for {}:{}",
                summary.child_id, summary.route_id
            )
        }),
        (Ok(_), Err(release_error)) => Err(release_error),
        (Err(finish_error), Err(release_error)) => {
            bail!(
                "program child finish event append failed after execution for {}:{}: {}; lock cleanup also failed: {}",
                summary.child_id,
                summary.route_id,
                finish_error,
                release_error
            );
        }
    }
}

fn execute_child_job(
    executor: DefaultLifecycleRouteExecutor,
    mut job: ChildExecutionJob,
) -> Result<ChildExecutionOutcome> {
    let mut last_result: Option<LifecycleRouteExecutionResult> = None;
    let mut attempts = 0;
    for attempt in 0..job.max_attempts {
        attempts = attempt + 1;
        job.request.policy.retry_attempt = attempt;
        let result = match executor.execute_route(job.request.clone()) {
            Ok(result) => result,
            Err(error) => {
                let error_message = error.to_string();
                let (blocker_class, retryable) = adapter_error_blocker_class(&error);
                let evidence_paths = write_child_adapter_error_evidence(&job, &error)?;
                if let Some(evidence) = job.unsafe_repair.clone() {
                    write_unsafe_repair_evidence(
                        &job.request.evidence_root,
                        evidence,
                        None,
                        Some(&error_message),
                    )?;
                }
                return Ok(ChildExecutionOutcome {
                    summary: ProgramChildExecutionSummary {
                        child_id: job.child_id,
                        child_run_id: job.child_run_id,
                        route_id: job.route_id,
                        status: "failed".to_string(),
                        attempts,
                        retryable,
                        blocker_class: job.blocker_class.or_else(|| Some(blocker_class)),
                        error_message: Some(error_message),
                        error_class: Some(error.class.as_str().to_string()),
                        evidence_paths,
                        worktree_hygiene_foreign_fingerprint: None,
                    },
                    lock_path: job.lock_path,
                });
            }
        };
        let result = enforce_child_route_completion_contract(&job, result)?;
        let retry = result.retryable
            && matches!(result.status.as_str(), "failed" | "timed-out" | "cancelled")
            && attempt + 1 < job.max_attempts;
        last_result = Some(result);
        if !retry {
            break;
        }
    }
    let result = last_result.context("child execution produced no result")?;
    if let Some(evidence) = job.unsafe_repair.clone() {
        write_unsafe_repair_evidence(&job.request.evidence_root, evidence, Some(&result), None)?;
    }
    Ok(ChildExecutionOutcome {
        summary: ProgramChildExecutionSummary {
            child_id: job.child_id,
            child_run_id: job.child_run_id,
            route_id: job.route_id,
            status: result.status.clone(),
            attempts,
            retryable: result.retryable,
            blocker_class: job
                .blocker_class
                .or_else(|| execution_result_blocker_class(&result)),
            error_message: result.error_message.clone(),
            error_class: result
                .error_class
                .as_ref()
                .map(|class| class.as_str().to_string()),
            evidence_paths: result
                .evidence_paths
                .iter()
                .map(|path| rel_path_string(path))
                .collect(),
            worktree_hygiene_foreign_fingerprint:
                execution_result_worktree_hygiene_foreign_fingerprint(&result),
        },
        lock_path: job.lock_path,
    })
}

fn enforce_child_route_completion_contract(
    job: &ChildExecutionJob,
    result: LifecycleRouteExecutionResult,
) -> Result<LifecycleRouteExecutionResult> {
    if result.status != "completed" {
        return Ok(result);
    }
    if job.route_id == ROUTE_ID_PROPOSAL_PACKET_TERMINAL_CLOSEOUT {
        if let Some(blocker) = terminal_closeout_blocking_receipt(job)? {
            return block_terminal_closeout_completion_contract(job, result, blocker);
        }
        return Ok(result);
    }
    if job.route_id == "revise-packet" {
        if revise_packet_has_valid_current_review_revision_receipt(&job.request.target)? {
            return Ok(result);
        }
        return block_child_route_completion_contract(
            job,
            result,
            "revise-packet-completion-contract-blocker.yml",
            "revision-receipt-missing",
            "completed revise-packet executor result lacked a current-review revision receipt with post_revision_digest and no pending placeholders",
            "revise-packet completed without a valid current-review revision receipt",
        );
    }
    if job.route_id != "review-packet" {
        return Ok(result);
    }
    if review_packet_has_receipt_atomic_accepted_architecture_review(&job.request.target)? {
        return Ok(result);
    }
    block_child_route_completion_contract(
        job,
        result,
        "review-packet-completion-contract-blocker.yml",
        "accepted-review-receipt-atomicity-missing",
        "completed review-packet executor result accepted an architecture proposal without refreshing the strict pre-integration architecture receipt to the proposal-review packet digest",
        "review-packet completed without a fresh accepted architecture review receipt",
    )
}

struct TerminalCloseoutReceiptBlocker {
    blocker_class: String,
    terminal_blocker_class: String,
    message: String,
    terminal_receipt_ref: String,
    failing_evidence_ref: Option<String>,
    next_canonical_route: Option<String>,
    worktree_hygiene_foreign_fingerprint: Option<String>,
}

fn terminal_closeout_blocking_receipt(
    job: &ChildExecutionJob,
) -> Result<Option<TerminalCloseoutReceiptBlocker>> {
    let repo_root = repo_root_from_request_target(&job.request.target)?;
    let receipt_path = job
        .request
        .target
        .join("support/proposal-terminal-closeout.yml");
    if !receipt_path.is_file() {
        return Ok(None);
    }
    let receipt: serde_yaml::Value = serde_yaml::from_slice(&fs::read(&receipt_path)?)?;
    if !yaml_top_level_string_eq(&receipt, "terminal_verdict", "blocked") {
        return Ok(None);
    }
    let terminal_blocker_class = receipt
        .get("blocker")
        .and_then(|blocker| blocker.get("class"))
        .and_then(|value| value.as_str())
        .unwrap_or("terminal-closeout-blocked")
        .to_string();
    let worktree_hygiene_blocked =
        yaml_nested_field_string(&receipt, "worktree_hygiene", "verdict") == Some("blocked");
    let blocker_class = if terminal_blocker_class == "hygiene-blocked" || worktree_hygiene_blocked {
        "worktree-hygiene-blocked".to_string()
    } else {
        terminal_blocker_class.clone()
    };
    let detail = receipt
        .get("blocker")
        .and_then(|blocker| blocker.get("detail"))
        .and_then(|value| value.as_str())
        .unwrap_or("proposal-packet-terminal-closeout wrote a blocked terminal receipt");
    let failing_evidence_ref = receipt
        .get("blocker")
        .and_then(|blocker| blocker.get("failing_evidence_ref"))
        .and_then(|value| value.as_str())
        .filter(|value| is_safe_repo_relative(value))
        .map(str::to_string)
        .or_else(|| {
            receipt
                .get("worktree_hygiene")
                .and_then(|worktree| worktree.get("classification_ref"))
                .and_then(|value| value.as_str())
                .filter(|value| is_safe_repo_relative(value))
                .map(str::to_string)
        });
    let next_canonical_route = receipt
        .get("blocker")
        .and_then(|blocker| blocker.get("next_canonical_route"))
        .and_then(|value| value.as_str())
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string);
    let terminal_receipt_ref = authority_path_ref(&repo_root, &receipt_path);
    let worktree_hygiene_foreign_fingerprint =
        failing_evidence_ref.as_deref().and_then(|evidence_ref| {
            terminal_worktree_report_foreign_fingerprint(&repo_root, evidence_ref)
                .ok()
                .flatten()
        });
    Ok(Some(TerminalCloseoutReceiptBlocker {
        blocker_class,
        terminal_blocker_class,
        message: detail.to_string(),
        terminal_receipt_ref,
        failing_evidence_ref,
        next_canonical_route,
        worktree_hygiene_foreign_fingerprint,
    }))
}

fn block_terminal_closeout_completion_contract(
    job: &ChildExecutionJob,
    mut result: LifecycleRouteExecutionResult,
    blocker: TerminalCloseoutReceiptBlocker,
) -> Result<LifecycleRouteExecutionResult> {
    let evidence_path = job
        .request
        .evidence_root
        .join("proposal-packet-terminal-closeout-blocked-receipt.yml");
    fs::create_dir_all(job.request.evidence_root.as_path())?;
    fs::write(
        &evidence_path,
        format!(
            "schema_version: octon-child-terminal-closeout-blocked-receipt-v1\nroute_id: {}\nchild_run_id: {}\nstatus: blocked\nblocker_class: {}\nterminal_blocker_class: {}\nerror_class: terminal-receipt-blocked\nmessage: {}\nterminal_receipt_ref: {}\nfailing_evidence_ref: {}\nnext_canonical_route: {}\nworktree_hygiene_foreign_fingerprint: {}\ntarget: {}\nrecorded_at: {}\n",
            yaml_scalar(&job.route_id),
            yaml_scalar(&job.child_run_id),
            yaml_scalar(&blocker.blocker_class),
            yaml_scalar(&blocker.terminal_blocker_class),
            yaml_scalar(&blocker.message),
            yaml_scalar(&blocker.terminal_receipt_ref),
            yaml_scalar(blocker.failing_evidence_ref.as_deref().unwrap_or("none")),
            yaml_scalar(blocker.next_canonical_route.as_deref().unwrap_or("none")),
            yaml_scalar(
                blocker
                    .worktree_hygiene_foreign_fingerprint
                    .as_deref()
                    .unwrap_or("none")
            ),
            yaml_scalar(&rel_path_string(&job.request.target)),
            now_rfc3339()?
        ),
    )?;

    result.status = "blocked".to_string();
    result.retryable = false;
    result.next_action = "replan".to_string();
    result.error_class = Some(LifecycleErrorClass::CompletionNotObserved);
    result.error_message = Some(blocker.message);
    result
        .evidence_paths
        .push(PathBuf::from(blocker.terminal_receipt_ref));
    if let Some(failing_evidence_ref) = blocker.failing_evidence_ref {
        result
            .evidence_paths
            .push(PathBuf::from(failing_evidence_ref));
    }
    result.evidence_paths.push(evidence_path);
    Ok(result)
}

fn terminal_worktree_report_foreign_fingerprint(
    repo_root: &Path,
    report_ref: &str,
) -> Result<Option<String>> {
    if !is_safe_repo_relative(report_ref) {
        return Ok(None);
    }
    let report_path = repo_root.join(report_ref);
    if !report_path.is_file() {
        return Ok(None);
    }
    let body = fs::read_to_string(report_path)?;
    let mut in_foreign_section = false;
    let mut rows = Vec::new();
    for line in body.lines() {
        if line.trim() == "## Foreign Or Ambiguous" {
            in_foreign_section = true;
            continue;
        }
        if in_foreign_section && line.starts_with("## ") {
            break;
        }
        if !in_foreign_section {
            continue;
        }
        let Some(path) = line
            .trim()
            .strip_prefix("- `")
            .and_then(|value| value.strip_suffix("`"))
        else {
            continue;
        };
        if is_safe_repo_relative(path) {
            rows.push(path.to_string());
        }
    }
    if rows.is_empty() {
        return Ok(None);
    }
    rows.sort();
    Ok(Some(sha256_digest(rows.join("\n").as_bytes())))
}

fn repo_root_from_request_target(target: &Path) -> Result<PathBuf> {
    for ancestor in target.ancestors() {
        if ancestor.join(".git").exists() || ancestor.join(".octon").exists() {
            return Ok(ancestor.to_path_buf());
        }
    }
    bail!(
        "could not resolve git repo root from lifecycle request target {}",
        target.display()
    )
}

fn block_child_route_completion_contract(
    job: &ChildExecutionJob,
    mut result: LifecycleRouteExecutionResult,
    file_name: &str,
    blocker_class: &str,
    evidence: &str,
    error_message: &str,
) -> Result<LifecycleRouteExecutionResult> {
    let evidence_path = job.request.evidence_root.join(file_name);
    fs::create_dir_all(job.request.evidence_root.as_path())?;
    fs::write(
        &evidence_path,
        format!(
            "schema_version: octon-child-route-completion-contract-blocker-v1\nroute_id: {}\nchild_run_id: {}\nstatus: blocked\nblocker_class: {}\nerror_class: completion-not-observed\nevidence: {}\ntarget: {}\nrecorded_at: {}\n",
            yaml_scalar(&job.route_id),
            yaml_scalar(&job.child_run_id),
            yaml_scalar(blocker_class),
            yaml_scalar(evidence),
            yaml_scalar(&rel_path_string(&job.request.target)),
            now_rfc3339()?
        ),
    )?;

    result.status = "blocked".to_string();
    result.retryable = false;
    result.next_action = "replan".to_string();
    result.error_class = Some(LifecycleErrorClass::CompletionNotObserved);
    result.error_message = Some(error_message.to_string());
    result.evidence_paths.push(evidence_path);
    Ok(result)
}

fn revise_packet_has_valid_current_review_revision_receipt(target_abs: &Path) -> Result<bool> {
    let review_path = target_abs.join("support/proposal-review.md");
    if !review_path.is_file() {
        return Ok(false);
    }
    let review_fields = parse_receipt_fields(&review_path)?;
    let Some(review_id) = review_fields
        .get("review_id")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
    else {
        return Ok(false);
    };
    let revisions_dir = target_abs.join("support/revisions");
    let Ok(entries) = fs::read_dir(&revisions_dir) else {
        return Ok(false);
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("md") {
            continue;
        }
        let fields = parse_receipt_fields(&path)?;
        if revision_receipt_fields_satisfy_current_review(&fields, review_id) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn revision_receipt_fields_satisfy_current_review(
    fields: &BTreeMap<String, String>,
    review_id: &str,
) -> bool {
    let required = [
        "revision_id",
        "source_review_id",
        "changed_packet_files",
        "addressed_finding_ids",
        "remaining_blocking_count",
        "post_revision_digest",
        "validators_rerun",
        "catalog_checksum_registry_refresh",
    ];
    if required.iter().any(|field| {
        fields
            .get(*field)
            .map(|value| value.trim().is_empty())
            .unwrap_or(true)
    }) {
        return false;
    }
    if fields.get("source_review_id").map(|value| value.trim()) != Some(review_id) {
        return false;
    }
    let Some(digest) = fields.get("post_revision_digest").map(|value| value.trim()) else {
        return false;
    };
    if !digest.starts_with("sha256:") || digest.len() <= "sha256:".len() {
        return false;
    }
    if fields.contains_key("post_revision_packet_digest") {
        return false;
    }
    !fields.values().any(|value| {
        value
            .split(',')
            .any(|part| part.trim().eq_ignore_ascii_case("pending"))
    })
}

fn review_packet_has_receipt_atomic_accepted_architecture_review(
    target_abs: &Path,
) -> Result<bool> {
    let review_path = target_abs.join("support/proposal-review.md");
    if !review_path.is_file() {
        return Ok(false);
    }
    let review_fields = parse_receipt_fields(&review_path)?;
    if review_fields.get("verdict").map(|value| value.trim()) != Some("accepted") {
        return Ok(true);
    }
    let Some(reviewed_packet_digest) = review_fields
        .get("reviewed_packet_digest")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
    else {
        return Ok(false);
    };
    let architecture_manifest = target_abs.join("architecture-proposal.yml");
    let architecture_receipt = target_abs.join("support/pre-integration-architecture-review.yml");
    if !architecture_manifest.is_file() && !architecture_receipt.is_file() {
        return Ok(true);
    }
    if !architecture_receipt.is_file() {
        return Ok(false);
    }
    let architecture_fields = parse_receipt_fields(&architecture_receipt)?;
    if architecture_fields
        .get("review_mode")
        .map(|value| value.trim())
        != Some("pre-integration-architecture-review")
    {
        return Ok(false);
    }
    if architecture_fields.get("verdict").map(|value| value.trim()) != Some("pass") {
        return Ok(false);
    }
    Ok(architecture_fields
        .get("packet_digest")
        .map(|value| value.trim())
        == Some(reviewed_packet_digest))
}

#[derive(Clone, Copy)]
struct ProgramHandoffRequestSpec {
    requested_capability: &'static str,
    requested_lifecycle_id: &'static str,
    requested_route_surface: &'static str,
    requested_atomic_unit_type: &'static str,
    requested_target_outcome: &'static str,
    expected_return_evidence: &'static [&'static str],
    phase_id: &'static str,
}

fn emit_program_child_handoff_requests(
    repo_root: &Path,
    evidence_root: &Path,
    control_root: &Path,
    program_run_id: &str,
    lifecycle_id: &str,
    target_rel: &str,
    plan: &ProgramLifecyclePlanResult,
    child_results: &mut [ProgramChildExecutionSummary],
    step_context: Option<ProgramExecutionStepContext>,
) -> Result<Vec<String>> {
    let mut request_refs = Vec::new();
    for result in child_results.iter_mut() {
        let Some(spec) = program_handoff_request_spec(result) else {
            continue;
        };
        let Some(state) = plan.child_states.get(&result.child_id) else {
            continue;
        };
        let request_ref = write_program_child_handoff_request(
            repo_root,
            evidence_root,
            program_run_id,
            lifecycle_id,
            target_rel,
            state,
            result,
            spec,
        )?;
        result.evidence_paths.push(request_ref.clone());
        push_unique_string(&mut request_refs, request_ref.clone());
        let mut data = program_step_event_data(
            step_context.as_ref(),
            spec.phase_id,
            [
                ("interaction_request_ref", request_ref.as_str()),
                ("interaction_profile", PROGRAM_HANDOFF_PROFILE_ID),
                ("requested_route_surface", spec.requested_route_surface),
                (
                    "requested_atomic_unit_type",
                    spec.requested_atomic_unit_type,
                ),
                ("authority", "non-authorizing-request"),
                (
                    "blocker_class",
                    result.blocker_class.as_deref().unwrap_or("none"),
                ),
                (
                    "foreign_fingerprint",
                    result
                        .worktree_hygiene_foreign_fingerprint
                        .as_deref()
                        .unwrap_or("none"),
                ),
            ],
        );
        data.insert(
            "forbidden_transfer".to_string(),
            PROGRAM_HANDOFF_FORBIDDEN_TRANSFERS.join(","),
        );
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "lifecycle-interaction-requested",
            Some(&result.child_id),
            Some(&result.route_id),
            "program lifecycle requested target-owned closeout handoff evidence",
            data,
        )?;
    }
    Ok(request_refs)
}

fn program_handoff_request_spec(
    result: &ProgramChildExecutionSummary,
) -> Option<ProgramHandoffRequestSpec> {
    if result.status == "blocked"
        && matches!(
            result.route_id.as_str(),
            "closeout-packet" | "archive-proposal" | ROUTE_ID_PROPOSAL_PACKET_TERMINAL_CLOSEOUT
        )
        && matches!(
            result.blocker_class.as_deref(),
            Some("artifact-ownership-unclear")
                | Some("worktree-handoff-evidence-changed")
                | Some("stale-closeout-worktree-return")
                | Some("worktree-hygiene-blocked")
                | Some("hygiene-blocked")
        )
    {
        return Some(ProgramHandoffRequestSpec {
            requested_capability: "closeout-worktree",
            requested_lifecycle_id: "closeout-worktree",
            requested_route_surface: "closeout-worktree",
            requested_atomic_unit_type: "worktree",
            requested_target_outcome: "preserved",
            expected_return_evidence: &["closeout-worktree-report-v1"],
            phase_id: "closeout-worktree-hygiene",
        });
    }
    if result.status != "completed" {
        return None;
    }
    match result.route_id.as_str() {
        "run-packet-implementation"
        | "run-program-implementation-orchestration"
        | "run-implementation" => Some(ProgramHandoffRequestSpec {
            requested_capability: "change-closeout",
            requested_lifecycle_id: "change-closeout",
            requested_route_surface: "closeout-change",
            requested_atomic_unit_type: "change",
            requested_target_outcome: "cleaned",
            expected_return_evidence: &["change-receipt-v1"],
            phase_id: "child-batch-dispatch",
        }),
        _ => None,
    }
}

fn write_program_child_handoff_request(
    repo_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    lifecycle_id: &str,
    target_rel: &str,
    state: &ProgramChildPlanState,
    result: &ProgramChildExecutionSummary,
    spec: ProgramHandoffRequestSpec,
) -> Result<String> {
    let include_paths = program_handoff_include_paths(repo_root, state, result, spec)?;
    let exclude_paths = program_handoff_exclude_paths(&include_paths);
    let boundary_digest = lifecycle_interaction_boundary_digest(&include_paths, &exclude_paths)?;
    let interaction_identity = if result.status == "blocked"
        && spec.requested_lifecycle_id == "closeout-worktree"
        && matches!(
            result.route_id.as_str(),
            "closeout-packet" | "archive-proposal" | ROUTE_ID_PROPOSAL_PACKET_TERMINAL_CLOSEOUT
        ) {
        let handoff_discriminator = short_digest_suffix(
            format!(
                "{}:{}",
                result.blocker_class.as_deref().unwrap_or("none"),
                result
                    .worktree_hygiene_foreign_fingerprint
                    .as_deref()
                    .unwrap_or("none")
            )
            .as_bytes(),
        );
        format!(
            "{PROGRAM_HANDOFF_PROFILE_ID}-{program_run_id}-{}-{}-{handoff_discriminator}",
            result.child_id, result.route_id
        )
    } else {
        format!(
            "{PROGRAM_HANDOFF_PROFILE_ID}-{program_run_id}-{}-{}",
            result.child_id, result.route_id
        )
    };
    let interaction_id = lifecycle_interaction_id(&interaction_identity);
    let interaction_root = evidence_root.join("lifecycle-interactions");
    fs::create_dir_all(&interaction_root)?;
    let basis_path = interaction_root.join(format!("{interaction_id}-basis.yml"));
    let classifier_output_ref = handoff_worktree_evidence_path(result);
    let classifier_output_digest = match classifier_output_ref {
        Some(path) => handoff_evidence_digest(repo_root, path)?,
        None => None,
    };
    let classifier_stderr_ref =
        handoff_evidence_path_by_suffix(result, "worktree-hygiene-preflight.stderr.log");
    let classifier_stderr_digest = match classifier_stderr_ref {
        Some(path) => handoff_evidence_digest(repo_root, path)?,
        None => None,
    };
    fs::write(
        &basis_path,
        format!(
            "schema_version: octon-program-lifecycle-interaction-basis-v1\nprogram_run_id: {}\nchild_id: {}\nchild_run_id: {}\nsource_lifecycle_id: {}\nchild_lifecycle_id: {}\nroute_id: {}\nroute_status: {}\nblocker_class: {}\nforeign_fingerprint: {}\nclassifier_output_ref: {}\nclassifier_output_digest: {}\nclassifier_stderr_ref: {}\nclassifier_stderr_digest: {}\ninclude_paths:\n{}\nexclude_paths:\n{}\nrequired_return_evidence:\n{}\nnon_authorizing: true\nparent_summary_not_child_closeout_receipt: true\nchild_closeout_authority_preserved: true\nboundary_digest: {}\nrecorded_at: {}\n",
            yaml_scalar(program_run_id),
            yaml_scalar(&result.child_id),
            yaml_scalar(&result.child_run_id),
            yaml_scalar(lifecycle_id),
            yaml_scalar(&state.child_lifecycle_id),
            yaml_scalar(&result.route_id),
            yaml_scalar(&result.status),
            yaml_scalar(result.blocker_class.as_deref().unwrap_or("none")),
            yaml_scalar(
                result
                    .worktree_hygiene_foreign_fingerprint
                    .as_deref()
                    .unwrap_or("none"),
            ),
            yaml_scalar(
                classifier_output_ref.unwrap_or("none"),
            ),
            yaml_scalar(
                classifier_output_digest.as_deref().unwrap_or("none"),
            ),
            yaml_scalar(
                classifier_stderr_ref.unwrap_or("none"),
            ),
            yaml_scalar(
                classifier_stderr_digest.as_deref().unwrap_or("none"),
            ),
            yaml_list_block(include_paths.iter().map(String::as_str)),
            yaml_list_block(exclude_paths.iter().map(String::as_str)),
            yaml_list_block(spec.expected_return_evidence.iter().copied()),
            yaml_scalar(&boundary_digest),
            yaml_scalar(&now_rfc3339()?),
        ),
    )?;
    let evidence_offered =
        program_handoff_evidence_offered(repo_root, result, &basis_path, &interaction_root)?;
    let request_path = interaction_root.join(format!("{interaction_id}.json"));
    let request = serde_json::json!({
        "schema_version": LIFECYCLE_INTERACTION_REQUEST_SCHEMA,
        "interaction_id": interaction_id,
        "created_at": now_rfc3339()?,
        "source": {
            "lifecycle_id": lifecycle_id,
            "run_id": program_run_id,
            "atomic_unit_type": "proposal-program",
            "target_ref": target_rel,
            "phase_id": spec.phase_id,
        },
        "request": {
            "interaction_profile": PROGRAM_HANDOFF_PROFILE_ID,
            "interaction_kind": "follow_on_work_required",
            "requested_capability": spec.requested_capability,
            "requested_lifecycle_id": spec.requested_lifecycle_id,
            "requested_route_surface": spec.requested_route_surface,
            "requested_atomic_unit_type": spec.requested_atomic_unit_type,
            "requested_target_outcome": spec.requested_target_outcome,
        },
        "scope": {
            "include_paths": include_paths,
            "exclude_paths": exclude_paths,
            "boundary_digest": boundary_digest,
        },
        "evidence_offered": evidence_offered,
        "authority_boundary": {
            "forbidden_transfer": PROGRAM_HANDOFF_FORBIDDEN_TRANSFERS,
        },
        "stop_conditions": [
            "target-gate-missing",
            "boundary-digest-mismatch",
            "authority-transfer-attempt",
            "returned-evidence-missing",
        ],
        "expected_return_evidence": spec.expected_return_evidence,
    });
    fs::write(
        &request_path,
        format!("{}\n", serde_json::to_string_pretty(&request)?),
    )?;
    Ok(rel_display(repo_root, &request_path))
}

fn program_handoff_include_paths(
    repo_root: &Path,
    state: &ProgramChildPlanState,
    result: &ProgramChildExecutionSummary,
    spec: ProgramHandoffRequestSpec,
) -> Result<Vec<String>> {
    if result.status == "blocked"
        && spec.requested_lifecycle_id == "closeout-worktree"
        && matches!(
            result.route_id.as_str(),
            "closeout-packet" | "archive-proposal" | ROUTE_ID_PROPOSAL_PACKET_TERMINAL_CLOSEOUT
        )
    {
        if let Some(classifier_ref) = handoff_worktree_evidence_path(result) {
            let foreign_paths = worktree_hygiene_foreign_paths(repo_root, classifier_ref)?;
            if !foreign_paths.is_empty() {
                return Ok(foreign_paths);
            }
        }
    }
    program_handoff_state_scope_paths(state)
}

fn program_handoff_state_scope_paths(state: &ProgramChildPlanState) -> Result<Vec<String>> {
    let mut paths = BTreeSet::new();
    if !is_safe_repo_relative(&state.target) {
        bail!(
            "program handoff child target is not repo-relative: {}",
            state.target
        );
    }
    paths.insert(state.target.clone());
    for scope in &state.write_scopes {
        if !is_safe_repo_relative(scope) {
            bail!("program handoff write scope is not repo-relative: {scope}");
        }
        paths.insert(scope.clone());
    }
    Ok(paths.into_iter().collect())
}

fn worktree_hygiene_foreign_paths(repo_root: &Path, classifier_ref: &str) -> Result<Vec<String>> {
    let Some((_, classifier_path)) =
        normalize_existing_program_evidence_ref(repo_root, classifier_ref)
    else {
        return Ok(Vec::new());
    };
    let classifier_bytes = fs::read(classifier_path)?;
    let mut paths = BTreeSet::new();
    if let Ok(value) = serde_yaml::from_slice::<serde_yaml::Value>(&classifier_bytes) {
        if let Some(items) = value
            .get("worktree_hygiene_partitions")
            .and_then(|partitions| {
                partitions.get("manual_review_foreign_ambiguous_unsafe_or_user_owned")
            })
            .and_then(|items| items.as_sequence())
        {
            for item in items {
                let source_bucket = item.get("source_bucket").and_then(|value| value.as_str());
                let path = item.get("path").and_then(|value| value.as_str());
                if source_bucket == Some("foreign_or_ambiguous")
                    && path.map(is_safe_repo_relative).unwrap_or(false)
                {
                    paths.insert(path.unwrap().to_string());
                }
            }
        }
        if paths.is_empty() {
            if let Some(items) = value
                .get("foreign_or_ambiguous")
                .and_then(|items| items.as_sequence())
            {
                for item in items {
                    let path = item
                        .get("path")
                        .and_then(|value| value.as_str())
                        .or_else(|| item.as_str());
                    if path.map(is_safe_repo_relative).unwrap_or(false) {
                        paths.insert(path.unwrap().to_string());
                    }
                }
            }
        }
    }
    if paths.is_empty() {
        let body = String::from_utf8_lossy(&classifier_bytes);
        for path in terminal_markdown_foreign_paths(&body) {
            paths.insert(path);
        }
    }
    Ok(paths.into_iter().collect())
}

fn terminal_markdown_foreign_paths(body: &str) -> Vec<String> {
    let mut in_foreign_section = false;
    let mut rows = BTreeSet::new();
    for line in body.lines() {
        if line.trim() == "## Foreign Or Ambiguous" {
            in_foreign_section = true;
            continue;
        }
        if in_foreign_section && line.starts_with("## ") {
            break;
        }
        if !in_foreign_section {
            continue;
        }
        let Some(path) = line
            .trim()
            .strip_prefix("- `")
            .and_then(|value| value.strip_suffix("`"))
        else {
            continue;
        };
        if is_safe_repo_relative(path) {
            rows.insert(path.to_string());
        }
    }
    rows.into_iter().collect()
}

fn program_handoff_exclude_paths(include_paths: &[String]) -> Vec<String> {
    PROGRAM_HANDOFF_EXCLUDE_PATHS
        .iter()
        .filter(|path| !include_paths.iter().any(|include| include == **path))
        .map(|path| (*path).to_string())
        .collect()
}

fn lifecycle_interaction_boundary_digest(
    include_paths: &[String],
    exclude_paths: &[String],
) -> Result<String> {
    let mut payload = BTreeMap::new();
    payload.insert("exclude_paths", exclude_paths);
    payload.insert("include_paths", include_paths);
    Ok(sha256_digest(&serde_json::to_vec(&payload)?))
}

fn program_handoff_evidence_offered(
    repo_root: &Path,
    result: &ProgramChildExecutionSummary,
    basis_path: &Path,
    interaction_root: &Path,
) -> Result<Vec<serde_json::Value>> {
    let mut offered = Vec::new();
    let basis_ref = rel_display(repo_root, basis_path);
    offered.push(serde_json::json!({
        "ref": basis_ref,
        "digest": file_digest(basis_path)?,
        "acceptance_class": "advisory-context",
    }));
    let mut seen = BTreeSet::from([rel_display(repo_root, basis_path)]);
    for raw_path in &result.evidence_paths {
        let Some((evidence_ref, evidence_abs)) =
            normalize_existing_program_evidence_ref(repo_root, raw_path)
        else {
            continue;
        };
        if evidence_abs.starts_with(interaction_root) {
            continue;
        }
        // Context packs are regenerated across attempts; request authority must rest on
        // stable basis and route evidence so pending handoffs do not stale themselves.
        if evidence_ref.contains("/context/") {
            continue;
        }
        if seen.insert(evidence_ref.clone()) {
            offered.push(serde_json::json!({
                "ref": evidence_ref,
                "digest": file_digest(&evidence_abs)?,
                "acceptance_class": "validation-evidence",
            }));
        }
    }
    Ok(offered)
}

fn handoff_evidence_path_by_suffix<'a>(
    result: &'a ProgramChildExecutionSummary,
    suffix: &str,
) -> Option<&'a str> {
    result
        .evidence_paths
        .iter()
        .map(String::as_str)
        .find(|path| {
            path.ends_with(suffix)
                || (suffix == "worktree-hygiene-preflight.stdout.yml"
                    && is_worktree_hygiene_preflight_stdout_ref(path))
                || (suffix == "worktree-hygiene-preflight.stderr.log"
                    && is_worktree_hygiene_preflight_stderr_ref(path))
        })
}

fn handoff_worktree_evidence_path(result: &ProgramChildExecutionSummary) -> Option<&str> {
    handoff_evidence_path_by_suffix(result, "worktree-hygiene-preflight.stdout.yml")
        .or_else(|| handoff_evidence_path_by_suffix(result, "worktree-hygiene-classification.md"))
}

fn is_worktree_hygiene_preflight_stdout_ref(path: &str) -> bool {
    let file_name = path.rsplit('/').next().unwrap_or(path);
    file_name == "worktree-hygiene-preflight.stdout.yml"
        || (file_name.starts_with("worktree-hygiene-preflight-")
            && file_name.ends_with(".stdout.yml"))
}

fn is_worktree_hygiene_preflight_stderr_ref(path: &str) -> bool {
    let file_name = path.rsplit('/').next().unwrap_or(path);
    file_name == "worktree-hygiene-preflight.stderr.log"
        || (file_name.starts_with("worktree-hygiene-preflight-")
            && file_name.ends_with(".stderr.log"))
}

fn handoff_evidence_digest(repo_root: &Path, path: &str) -> Result<Option<String>> {
    let Some((_, absolute)) = normalize_existing_program_evidence_ref(repo_root, path) else {
        return Ok(None);
    };
    Ok(Some(file_digest(&absolute)?))
}

fn yaml_list_block<'a>(items: impl IntoIterator<Item = &'a str>) -> String {
    let mut rendered = String::new();
    for item in items {
        rendered.push_str("  - ");
        rendered.push_str(&yaml_scalar(item));
        rendered.push('\n');
    }
    if rendered.is_empty() {
        "  []\n".to_string()
    } else {
        rendered
    }
}

fn normalize_existing_program_evidence_ref(
    repo_root: &Path,
    raw_path: &str,
) -> Option<(String, PathBuf)> {
    let path = Path::new(raw_path);
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        repo_root.join(path)
    };
    if !absolute.is_file() {
        return None;
    }
    let rel = rel_display(repo_root, &absolute);
    if is_safe_repo_relative(&rel) {
        Some((rel, absolute))
    } else {
        None
    }
}

fn lifecycle_interaction_id(raw: &str) -> String {
    let mut id = String::new();
    let mut previous_hyphen = false;
    for ch in raw.chars() {
        let next = if ch.is_ascii_alphanumeric() {
            ch.to_ascii_lowercase()
        } else {
            '-'
        };
        if next == '-' {
            if !previous_hyphen {
                id.push(next);
            }
            previous_hyphen = true;
        } else {
            id.push(next);
            previous_hyphen = false;
        }
    }
    let id = id.trim_matches('-');
    if id
        .chars()
        .next()
        .map(|ch| ch.is_ascii_lowercase())
        .unwrap_or(false)
    {
        id.to_string()
    } else {
        format!("program-handoff-{id}")
    }
}

fn child_result_interaction_request_refs(
    repo_root: &Path,
    child_results: &[ProgramChildExecutionSummary],
) -> Result<Vec<String>> {
    let mut refs = Vec::new();
    for result in child_results {
        for raw_path in &result.evidence_paths {
            let Some((request_ref, request_abs)) =
                normalize_existing_program_evidence_ref(repo_root, raw_path)
            else {
                continue;
            };
            if !request_ref.contains("/lifecycle-interactions/") || !request_ref.ends_with(".json")
            {
                continue;
            }
            let value: serde_json::Value = serde_json::from_slice(&fs::read(&request_abs)?)?;
            if value
                .get("schema_version")
                .and_then(|schema| schema.as_str())
                == Some(LIFECYCLE_INTERACTION_REQUEST_SCHEMA)
            {
                push_unique_string(&mut refs, request_ref);
            }
        }
    }
    Ok(refs)
}

fn push_unique_string(values: &mut Vec<String>, value: String) {
    if !values.iter().any(|existing| existing == &value) {
        values.push(value);
    }
}

fn insert_program_interaction_event_context(
    data: &mut BTreeMap<String, String>,
    request_refs: &[String],
    return_refs: &[String],
) {
    if !request_refs.is_empty() {
        data.insert(
            "interaction_request_refs".to_string(),
            request_refs.join(","),
        );
    }
    if !return_refs.is_empty() {
        data.insert("interaction_return_refs".to_string(), return_refs.join(","));
        data.insert(
            "interaction_return_schema".to_string(),
            LIFECYCLE_INTERACTION_RETURN_SCHEMA.to_string(),
        );
    }
}

fn pending_lifecycle_interaction_request_refs(
    repo_root: &Path,
    previous_checkpoint: Option<&ProgramLifecycleCheckpoint>,
    incoming_request_refs: &[String],
    incoming_return_refs: &[String],
) -> Result<Vec<String>> {
    let incoming_request_refs =
        actionable_lifecycle_interaction_request_refs(repo_root, incoming_request_refs.to_vec())?;
    let Some(checkpoint) = previous_checkpoint else {
        return Ok(incoming_request_refs);
    };
    if matches!(
        normalize_program_state_value(&checkpoint.final_verdict),
        ProgramNormalizedCategory::Terminal | ProgramNormalizedCategory::Cancellation
    ) {
        return Ok(incoming_request_refs);
    }
    let mut refs = actionable_lifecycle_interaction_request_refs(
        repo_root,
        checkpoint.interaction_request_refs.clone(),
    )?;
    for incoming_ref in incoming_request_refs {
        push_unique_string(&mut refs, incoming_ref);
    }
    if refs.is_empty() {
        return Ok(Vec::new());
    }
    let mut return_refs = checkpoint.interaction_return_refs.clone();
    for incoming_ref in incoming_return_refs {
        push_unique_string(&mut return_refs, incoming_ref.clone());
    }
    unresolved_lifecycle_interaction_request_refs(repo_root, refs, &return_refs)
}

fn apply_pending_interaction_route_suppression(
    repo_root: &Path,
    program_run_id: &str,
    pending_request_refs: &[String],
    plan: &mut ProgramLifecyclePlanResult,
    block_suppressed_nonrunnable_child: bool,
) -> Result<Vec<String>> {
    if pending_request_refs.is_empty() {
        return Ok(Vec::new());
    }

    let mut global_blocking_refs = Vec::new();
    let mut suppressed_request_refs = Vec::new();
    let mut suppressed_children = BTreeSet::new();
    for request_ref in pending_request_refs {
        let binding = lifecycle_interaction_request_binding_from_ref(repo_root, request_ref)?;
        let Some((child_id, route_id)) = binding.child_route.as_ref() else {
            if block_suppressed_nonrunnable_child {
                push_unique_string(&mut global_blocking_refs, request_ref.clone());
            }
            continue;
        };
        let Some(state) = plan.child_states.get(child_id) else {
            continue;
        };
        let child_is_runnable = plan.runnable_batch.iter().any(|id| id == child_id);
        let route_matches_state = state
            .selected_route
            .as_ref()
            .map(|route| route.route_id.as_str())
            == Some(route_id.as_str())
            || state.blockers.iter().any(|blocker| {
                blocker.recovery_route.as_deref() == Some(route_id.as_str())
                    || (route_has_closeout_hygiene_preflight(route_id)
                        && matches!(
                            blocker.blocker_class.as_str(),
                            "artifact-ownership-unclear"
                                | "worktree-hygiene-blocked"
                                | "hygiene-blocked"
                        ))
            });
        if !route_matches_state {
            continue;
        }
        if !child_is_runnable && (plan.program_route.is_some() || !plan.runnable_batch.is_empty()) {
            continue;
        }
        if !pending_interaction_request_matches_current_child_route(
            repo_root,
            program_run_id,
            state,
            route_id,
            &binding,
        )? {
            continue;
        }
        if child_is_runnable {
            suppressed_children.insert(child_id.clone());
            push_unique_string(&mut suppressed_request_refs, request_ref.clone());
        } else if block_suppressed_nonrunnable_child {
            push_unique_string(&mut global_blocking_refs, request_ref.clone());
        }
    }

    if !global_blocking_refs.is_empty() {
        for request_ref in suppressed_request_refs {
            push_unique_string(&mut global_blocking_refs, request_ref);
        }
        return Ok(global_blocking_refs);
    }
    if suppressed_children.is_empty() {
        return Ok(Vec::new());
    }
    plan.runnable_batch
        .retain(|child_id| !suppressed_children.contains(child_id));
    if plan.program_route.is_none() && plan.runnable_batch.is_empty() {
        Ok(suppressed_request_refs)
    } else {
        Ok(Vec::new())
    }
}

fn should_block_suppressed_pending_interactions_on_resume(
    previous_checkpoint: Option<&ProgramLifecycleCheckpoint>,
    incoming_interaction_return_refs: &[String],
    step_context: Option<ProgramExecutionStepContext>,
) -> bool {
    if !incoming_interaction_return_refs.is_empty() {
        return false;
    }
    if step_context
        .map(|context| context.step_index != 0)
        .unwrap_or(false)
    {
        return false;
    }
    previous_checkpoint.is_some_and(|checkpoint| {
        checkpoint.final_verdict == "step-budget-exhausted-continuable"
            && !checkpoint.closeout_hygiene_suppressions.is_empty()
    })
}

fn pending_interaction_request_matches_current_child_route(
    repo_root: &Path,
    program_run_id: &str,
    state: &ProgramChildPlanState,
    route_id: &str,
    binding: &LifecycleInteractionRequestBinding,
) -> Result<bool> {
    let Some(pending_fingerprint) = binding
        .worktree_hygiene_foreign_fingerprint
        .as_deref()
        .filter(|value| !value.trim().is_empty() && *value != "none")
    else {
        return Ok(true);
    };
    if !route_has_closeout_hygiene_preflight(route_id) {
        return Ok(true);
    }
    let Some(current) =
        closeout_worktree_hygiene_classifier(repo_root, &state.target, program_run_id)?
    else {
        return Ok(true);
    };
    let current_fingerprint = current.decision.foreign_fingerprint.as_deref();
    Ok(residue_cleanup_fingerprint(current_fingerprint)
        == residue_cleanup_fingerprint(Some(pending_fingerprint)))
}

fn actionable_lifecycle_interaction_request_refs(
    repo_root: &Path,
    refs: Vec<String>,
) -> Result<Vec<String>> {
    let mut actionable_refs = Vec::new();
    for request_ref in refs {
        if unsupported_promotion_closeout_worktree_request_without_classifier(
            repo_root,
            &request_ref,
        )? {
            continue;
        }
        push_unique_string(&mut actionable_refs, request_ref);
    }
    Ok(actionable_refs)
}

fn unresolved_lifecycle_interaction_request_refs(
    repo_root: &Path,
    request_refs: Vec<String>,
    return_refs: &[String],
) -> Result<Vec<String>> {
    let request_refs = actionable_lifecycle_interaction_request_refs(repo_root, request_refs)?;
    if request_refs.is_empty() {
        return Ok(Vec::new());
    }
    let completed_return_bindings =
        completed_current_lifecycle_interaction_return_bindings(repo_root, return_refs)?;
    let mut unresolved_refs = Vec::new();
    for request_ref in request_refs {
        let normalized_request_ref =
            normalize_existing_program_evidence_ref(repo_root, &request_ref)
                .map(|(normalized, _)| normalized)
                .unwrap_or_else(|| request_ref.clone());
        let request_binding =
            lifecycle_interaction_request_binding_from_ref(repo_root, &request_ref)?;
        let resolved_by_id =
            request_binding
                .interaction_id
                .as_ref()
                .is_some_and(|interaction_id| {
                    completed_return_bindings
                        .interaction_ids
                        .contains(interaction_id)
                });
        let resolved_by_request_ref = completed_return_bindings
            .interaction_request_refs
            .contains(&normalized_request_ref);
        let resolved_by_child_route = lifecycle_interaction_child_route_return_matches_request(
            &completed_return_bindings,
            &request_binding,
        );
        if !resolved_by_id && !resolved_by_request_ref && !resolved_by_child_route {
            push_unique_string(&mut unresolved_refs, request_ref);
        }
    }
    Ok(unresolved_refs)
}

#[derive(Default)]
struct CompletedLifecycleInteractionReturnBindings {
    interaction_ids: BTreeSet<String>,
    interaction_request_refs: BTreeSet<String>,
    child_routes: BTreeSet<(String, String)>,
    child_route_fingerprints: BTreeSet<(String, String, String)>,
}

fn lifecycle_interaction_child_route_return_matches_request(
    completed_return_bindings: &CompletedLifecycleInteractionReturnBindings,
    request_binding: &LifecycleInteractionRequestBinding,
) -> bool {
    let Some((child_id, route_id)) = request_binding.child_route.as_ref() else {
        return false;
    };
    let Some(request_fingerprint) = request_binding
        .worktree_hygiene_foreign_fingerprint
        .as_deref()
        .filter(|value| !value.trim().is_empty() && *value != "none")
    else {
        return completed_return_bindings
            .child_routes
            .contains(&(child_id.clone(), route_id.clone()));
    };
    completed_return_bindings
        .child_route_fingerprints
        .contains(&(
            child_id.clone(),
            route_id.clone(),
            residue_cleanup_fingerprint(Some(request_fingerprint)),
        ))
}

fn completed_current_lifecycle_interaction_return_bindings(
    repo_root: &Path,
    return_refs: &[String],
) -> Result<CompletedLifecycleInteractionReturnBindings> {
    let mut bindings = CompletedLifecycleInteractionReturnBindings::default();
    for return_ref in return_refs {
        let Some((_, return_path)) = normalize_existing_program_evidence_ref(repo_root, return_ref)
        else {
            continue;
        };
        let Some(receipt) = read_valid_lifecycle_interaction_return_receipt(&return_path)? else {
            continue;
        };
        if !receipt.outcome.is_completed()
            || !lifecycle_interaction_return_evidence_refs_are_current(repo_root, &receipt)?
        {
            continue;
        }
        if valid_lifecycle_interaction_id(&receipt.interaction_id) {
            bindings
                .interaction_ids
                .insert(receipt.interaction_id.clone());
        }
        for evidence in &receipt.return_evidence_refs {
            let Some((_, report_path)) =
                normalize_existing_program_evidence_ref(repo_root, &evidence.ref_path)
            else {
                continue;
            };
            if file_digest(&report_path)? != evidence.digest {
                continue;
            }
            let report: CloseoutWorktreeReport =
                match serde_yaml::from_slice(&fs::read(&report_path)?) {
                    Ok(report) => report,
                    Err(_) => continue,
                };
            for candidate in &report.candidates {
                let Some(auth) = candidate.proposal_program_handoff_authorization.as_ref() else {
                    continue;
                };
                if auth.interaction_request_ref.is_empty() {
                    if !auth.child_id.is_empty() && !auth.route_id.is_empty() {
                        bindings
                            .child_routes
                            .insert((auth.child_id.clone(), auth.route_id.clone()));
                        let fingerprint = auth
                            .foreign_fingerprint
                            .as_deref()
                            .or(Some(auth.authorized_foreign_fingerprint.as_str()));
                        bindings.child_route_fingerprints.insert((
                            auth.child_id.clone(),
                            auth.route_id.clone(),
                            residue_cleanup_fingerprint(fingerprint),
                        ));
                    }
                    continue;
                }
                let Some((normalized_request_ref, _)) = normalize_existing_program_evidence_ref(
                    repo_root,
                    &auth.interaction_request_ref,
                ) else {
                    if !auth.child_id.is_empty() && !auth.route_id.is_empty() {
                        bindings
                            .child_routes
                            .insert((auth.child_id.clone(), auth.route_id.clone()));
                        let fingerprint = auth
                            .foreign_fingerprint
                            .as_deref()
                            .or(Some(auth.authorized_foreign_fingerprint.as_str()));
                        bindings.child_route_fingerprints.insert((
                            auth.child_id.clone(),
                            auth.route_id.clone(),
                            residue_cleanup_fingerprint(fingerprint),
                        ));
                    }
                    continue;
                };
                bindings
                    .interaction_request_refs
                    .insert(normalized_request_ref);
                if !auth.child_id.is_empty() && !auth.route_id.is_empty() {
                    bindings
                        .child_routes
                        .insert((auth.child_id.clone(), auth.route_id.clone()));
                    let fingerprint = auth
                        .foreign_fingerprint
                        .as_deref()
                        .or(Some(auth.authorized_foreign_fingerprint.as_str()));
                    bindings.child_route_fingerprints.insert((
                        auth.child_id.clone(),
                        auth.route_id.clone(),
                        residue_cleanup_fingerprint(fingerprint),
                    ));
                }
            }
        }
    }
    Ok(bindings)
}

#[derive(Default)]
struct LifecycleInteractionRequestBinding {
    interaction_id: Option<String>,
    child_route: Option<(String, String)>,
    blocker_class: Option<String>,
    worktree_hygiene_foreign_fingerprint: Option<String>,
}

fn lifecycle_interaction_request_binding_from_ref(
    repo_root: &Path,
    request_ref: &str,
) -> Result<LifecycleInteractionRequestBinding> {
    let Some((_, request_path)) = normalize_existing_program_evidence_ref(repo_root, request_ref)
    else {
        return Ok(LifecycleInteractionRequestBinding::default());
    };
    let value: serde_json::Value = match serde_json::from_slice(&fs::read(&request_path)?) {
        Ok(value) => value,
        Err(_) => return Ok(LifecycleInteractionRequestBinding::default()),
    };
    if value.get("schema_version").and_then(|value| value.as_str())
        != Some(LIFECYCLE_INTERACTION_REQUEST_SCHEMA)
    {
        return Ok(LifecycleInteractionRequestBinding::default());
    }
    let mut binding = LifecycleInteractionRequestBinding::default();
    if let Some(interaction_id) = value.get("interaction_id").and_then(|value| value.as_str()) {
        if valid_lifecycle_interaction_id(interaction_id) {
            binding.interaction_id = Some(interaction_id.to_string());
        }
    }
    if let Some(evidence_offered) = value
        .get("evidence_offered")
        .and_then(|value| value.as_array())
    {
        for evidence in evidence_offered {
            let Some(evidence_ref) = evidence.get("ref").and_then(|value| value.as_str()) else {
                continue;
            };
            let Some((_, basis_path)) =
                normalize_existing_program_evidence_ref(repo_root, evidence_ref)
            else {
                continue;
            };
            let basis: serde_yaml::Value = match serde_yaml::from_slice(&fs::read(&basis_path)?) {
                Ok(value) => value,
                Err(_) => continue,
            };
            if basis.get("schema_version").and_then(|value| value.as_str())
                != Some("octon-program-lifecycle-interaction-basis-v1")
            {
                continue;
            }
            let child_id = basis.get("child_id").and_then(|value| value.as_str());
            let route_id = basis.get("route_id").and_then(|value| value.as_str());
            if let (Some(child_id), Some(route_id)) = (child_id, route_id) {
                if valid_program_id(child_id) && valid_program_id(route_id) {
                    binding.child_route = Some((child_id.to_string(), route_id.to_string()));
                    binding.blocker_class = basis
                        .get("blocker_class")
                        .and_then(|value| value.as_str())
                        .filter(|value| !value.trim().is_empty())
                        .map(ToString::to_string);
                    binding.worktree_hygiene_foreign_fingerprint = basis
                        .get("foreign_fingerprint")
                        .and_then(|value| value.as_str())
                        .filter(|value| !value.trim().is_empty())
                        .map(ToString::to_string);
                    break;
                }
            }
        }
    }
    Ok(binding)
}

fn unsupported_promotion_closeout_worktree_request_without_classifier(
    repo_root: &Path,
    request_ref: &str,
) -> Result<bool> {
    let Some((normalized_ref, request_path)) =
        normalize_existing_program_evidence_ref(repo_root, request_ref)
    else {
        return Ok(false);
    };
    let value: serde_json::Value = match serde_json::from_slice(&fs::read(&request_path)?) {
        Ok(value) => value,
        Err(_) => return Ok(false),
    };
    if value
        .get("schema_version")
        .and_then(|schema| schema.as_str())
        != Some(LIFECYCLE_INTERACTION_REQUEST_SCHEMA)
    {
        return Ok(false);
    }
    if value
        .get("source")
        .and_then(|source| source.get("phase_id"))
        .and_then(|phase| phase.as_str())
        != Some("promotion-evidence-convergence")
    {
        return Ok(false);
    }
    let request = value.get("request");
    if request
        .and_then(|request| request.get("requested_lifecycle_id"))
        .and_then(|lifecycle| lifecycle.as_str())
        != Some("closeout-worktree")
        || request
            .and_then(|request| request.get("requested_route_surface"))
            .and_then(|surface| surface.as_str())
            != Some("closeout-worktree")
        || request
            .and_then(|request| request.get("requested_target_outcome"))
            .and_then(|outcome| outcome.as_str())
            != Some("cleaned")
    {
        return Ok(false);
    }
    let basis_ref = normalized_ref
        .strip_suffix(".json")
        .map(|stem| format!("{stem}-basis.yml"));
    let Some(basis_ref) = basis_ref else {
        return Ok(false);
    };
    let Some((_, basis_path)) = normalize_existing_program_evidence_ref(repo_root, &basis_ref)
    else {
        return Ok(false);
    };
    let fields = match parse_receipt_fields(&basis_path) {
        Ok(fields) => fields,
        Err(_) => return Ok(false),
    };
    Ok(
        fields.get("route_id").map(String::as_str) == Some(ROUTE_ID_PROMOTE_PROPOSAL)
            && fields.get("route_status").map(String::as_str) == Some("completed")
            && fields.get("blocker_class").map(String::as_str) == Some("none")
            && fields.get("foreign_fingerprint").map(String::as_str) == Some("none")
            && fields.get("classifier_output_ref").map(String::as_str) == Some("none")
            && fields.get("classifier_output_digest").map(String::as_str) == Some("none")
            && fields.get("non_authorizing").map(String::as_str) == Some("true")
            && fields
                .get("child_closeout_authority_preserved")
                .map(String::as_str)
                == Some("true"),
    )
}

fn adapter_error_blocker_class(error: &LifecycleExecutionError) -> (String, bool) {
    match &error.class {
        LifecycleErrorClass::Timeout => ("executor-timed-out".to_string(), true),
        LifecycleErrorClass::ExecutorFailed | LifecycleErrorClass::ExecutorUnavailable => {
            ("executor-failed".to_string(), true)
        }
        LifecycleErrorClass::AuthorizationProofFailed
        | LifecycleErrorClass::HumanBoundaryRequired
        | LifecycleErrorClass::InputBinding => ("executor-preflight-blocked".to_string(), false),
        _ => ("executor-failed".to_string(), false),
    }
}

fn write_child_adapter_error_evidence(
    job: &ChildExecutionJob,
    error: &LifecycleExecutionError,
) -> Result<Vec<String>> {
    fs::create_dir_all(&job.request.evidence_root)?;
    let evidence_path = job
        .request
        .evidence_root
        .join(format!("{}-adapter-error.yml", job.route_id));
    fs::write(
        &evidence_path,
        format!(
            "schema_version: octon-program-child-adapter-error-v1\nchild_id: {}\nchild_run_id: {}\nroute_id: {}\nstatus: failed\nerror_class: {}\nretryable: {}\nmessage: {}\nrecorded_at: {}\n",
            job.child_id,
            job.child_run_id,
            job.route_id,
            error.class.as_str(),
            matches!(
                &error.class,
                LifecycleErrorClass::Timeout
                    | LifecycleErrorClass::ExecutorFailed
                    | LifecycleErrorClass::ExecutorUnavailable
            ),
            yaml_scalar(&error.message),
            now_rfc3339()?
        ),
    )?;
    Ok(vec![rel_path_string(&evidence_path)])
}

fn execution_result_blocker_class(result: &LifecycleRouteExecutionResult) -> Option<String> {
    if result.route_id == ROUTE_ID_ARCHIVE_PROPOSAL {
        if let Some(evidence) = result
            .evidence_paths
            .iter()
            .find_map(|path| archive_blocked_evidence_at_path(path))
        {
            return evidence
                .blocker_class
                .or_else(|| Some("archive-route-failed".to_string()));
        }
        if result.executor_used == "workflow-leaf"
            && matches!(
                result.status.as_str(),
                "failed" | "timed-out" | "blocked" | "cancelled"
            )
        {
            return Some("archive-route-failed".to_string());
        }
    }
    if result.status == "executor-preflight-blocked" {
        return Some("executor-preflight-blocked".to_string());
    }
    if let Some(blocker_class) = execution_result_evidence_blocker_class(result) {
        return Some(blocker_class);
    }
    if result.route_id == "revise-packet"
        && result.error_class.as_ref() == Some(&LifecycleErrorClass::CompletionNotObserved)
    {
        return Some("revision-receipt-missing".to_string());
    }
    if result.route_id == "review-packet"
        && result.error_class.as_ref() == Some(&LifecycleErrorClass::CompletionNotObserved)
    {
        return Some("accepted-review-receipt-atomicity-missing".to_string());
    }
    if !result.retryable {
        return None;
    }
    match result.error_class.as_ref().map(|class| class.as_str()) {
        Some("timeout") => Some("executor-timed-out".to_string()),
        Some("executor-failed") | Some("executor-unavailable") => {
            Some("executor-failed".to_string())
        }
        _ if result.status == "timed-out" => Some("executor-timed-out".to_string()),
        _ if result.status == "failed" => Some("executor-failed".to_string()),
        _ => None,
    }
}

fn execution_result_evidence_blocker_class(
    result: &LifecycleRouteExecutionResult,
) -> Option<String> {
    result.evidence_paths.iter().find_map(|path| {
        if !path.is_file() {
            return None;
        }
        let fields = parse_receipt_fields(path).ok()?;
        fields
            .get("blocker_class")
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    })
}

fn execution_result_worktree_hygiene_foreign_fingerprint(
    result: &LifecycleRouteExecutionResult,
) -> Option<String> {
    result.evidence_paths.iter().rev().find_map(|path| {
        if !path.is_file() {
            return None;
        }
        let fields = parse_receipt_fields(path).ok()?;
        fields
            .get("worktree_hygiene_foreign_fingerprint")
            .map(|value| value.trim())
            .filter(|value| value.starts_with("sha256:") || *value == "none")
            .filter(|value| *value != "none")
            .map(str::to_string)
    })
}

fn write_unsafe_repair_evidence(
    child_evidence_root: &Path,
    mut evidence: ProgramUnsafeRepairEvidence,
    result: Option<&LifecycleRouteExecutionResult>,
    error_message: Option<&str>,
) -> Result<()> {
    if let Some(result) = result {
        let mut changed = result
            .evidence_paths
            .iter()
            .map(|path| rel_path_string(path))
            .collect::<Vec<_>>();
        changed.extend(
            result
                .receipts_observed
                .iter()
                .map(|receipt| rel_path_string(&receipt.path)),
        );
        if let Some(path) = result.stdout_path.as_ref() {
            changed.push(rel_path_string(path));
        }
        if let Some(path) = result.stderr_path.as_ref() {
            changed.push(rel_path_string(path));
        }
        if let Some(path) = result.prompt_packet_path.as_ref() {
            changed.push(rel_path_string(path));
        }
        if !changed.is_empty() {
            changed.sort();
            changed.dedup();
            evidence.files_artifacts_changed = changed;
        }
        evidence.after_validation = format!(
            "repair route status {}; retryable {}; receipts_observed {}",
            result.status,
            result.retryable,
            result.receipts_observed.len()
        );
        evidence.route_execution_status = result.status.clone();
        evidence.post_attempt_validation_status =
            if matches!(result.status.as_str(), "completed" | "no-op") {
                "pending".to_string()
            } else {
                "not-run-route-not-completed".to_string()
            };
        evidence.execution_can_resume = false;
        evidence.final_execution_can_resume = false;
    } else if let Some(error_message) = error_message {
        evidence.after_validation =
            format!("repair route failed before completion: {error_message}");
        evidence.route_execution_status = "failed".to_string();
        evidence.post_attempt_validation_status = "not-run-route-error".to_string();
        evidence.post_attempt_validation_failures = vec![error_message.to_string()];
        evidence.execution_can_resume = false;
        evidence.final_execution_can_resume = false;
    }
    fs::create_dir_all(child_evidence_root)?;
    fs::write(
        child_evidence_root.join("unsafe-repair-decision.yml"),
        serde_yaml::to_string(&evidence)?,
    )?;
    Ok(())
}

fn finalize_unsafe_repair_evidence(
    evidence_root: &Path,
    result: &ProgramChildExecutionSummary,
) -> Result<()> {
    finalize_unsafe_repair_evidence_with_outcome(evidence_root, result, None)
}

fn finalize_unsafe_repair_evidence_with_outcome(
    evidence_root: &Path,
    result: &ProgramChildExecutionSummary,
    outcome: Option<&ProgramRecoveryPostAttemptValidationOutcome>,
) -> Result<()> {
    let evidence_path = evidence_root.join("unsafe-repair-decision.yml");
    if !evidence_path.is_file() {
        return Ok(());
    }
    let mut evidence: ProgramUnsafeRepairEvidence =
        serde_yaml::from_slice(&fs::read(&evidence_path)?)?;
    evidence.final_blocker_class = outcome
        .and_then(|outcome| outcome.final_blocker_class.clone())
        .or_else(|| result.blocker_class.clone());
    evidence.post_attempt_validation_failures.clear();
    if evidence.route_execution_status.is_empty() {
        evidence.route_execution_status = if evidence.execution_can_resume {
            "completed".to_string()
        } else {
            result.status.clone()
        };
    }
    if let Some(outcome) = outcome {
        evidence.post_attempt_validations_declared = outcome.declared.clone();
        evidence.post_attempt_validation_results = outcome.results.clone();
        evidence.post_attempt_validation_status = outcome.status.clone();
        evidence.post_attempt_validation_failures = outcome.failures.clone();
        evidence.resume_decision_basis = outcome.resume_decision_basis.clone();
        evidence.final_execution_can_resume = outcome.execution_can_resume;
        evidence.execution_can_resume = outcome.execution_can_resume;
        fs::write(&evidence_path, serde_yaml::to_string(&evidence)?)?;
        return Ok(());
    }
    let route_completed = matches!(
        evidence.route_execution_status.as_str(),
        "completed" | "no-op"
    );
    if matches!(result.status.as_str(), "completed" | "no-op") && route_completed {
        evidence.post_attempt_validation_status = "passed".to_string();
        evidence.post_attempt_validation_results = vec!["summary-status: pass".to_string()];
        evidence.resume_decision_basis =
            "repair route completed/no-op and post-attempt validations passed".to_string();
        evidence.final_execution_can_resume = true;
        evidence.execution_can_resume = true;
    } else {
        evidence.post_attempt_validation_status = if route_completed {
            "failed".to_string()
        } else {
            "not-run-route-not-completed".to_string()
        };
        if let Some(message) = result.error_message.as_ref() {
            evidence
                .post_attempt_validation_failures
                .push(message.clone());
        } else {
            evidence
                .post_attempt_validation_failures
                .push(format!("repair route final status {}", result.status));
        }
        evidence.post_attempt_validation_results =
            vec![format!("summary-status: fail: {}", result.status)];
        evidence.resume_decision_basis =
            "repair route did not satisfy final post-attempt validation status".to_string();
        evidence.final_execution_can_resume = false;
        evidence.execution_can_resume = false;
    }
    fs::write(&evidence_path, serde_yaml::to_string(&evidence)?)?;
    Ok(())
}

fn finalize_child_unsafe_repair_evidence(
    evidence_root: &Path,
    child_results: &[ProgramChildExecutionSummary],
) -> Result<()> {
    for result in child_results
        .iter()
        .filter(|result| result.blocker_class.is_some())
    {
        let child_evidence_root = evidence_root.join("children").join(&result.child_id);
        finalize_unsafe_repair_evidence(&child_evidence_root, result)?;
    }
    Ok(())
}

fn finalize_parent_unsafe_repair_evidence(
    evidence_root: &Path,
    result: &LifecycleRouteExecutionResult,
    outcome: &ProgramRecoveryPostAttemptValidationOutcome,
) -> Result<()> {
    let summary = ProgramChildExecutionSummary {
        child_id: "program".to_string(),
        child_run_id: "program".to_string(),
        route_id: "program-parent-route".to_string(),
        status: if matches!(result.status.as_str(), "completed" | "no-op")
            && outcome.execution_can_resume
        {
            result.status.clone()
        } else if matches!(result.status.as_str(), "completed" | "no-op") {
            "failed".to_string()
        } else {
            result.status.clone()
        },
        attempts: 1,
        retryable: result.retryable,
        blocker_class: outcome.final_blocker_class.clone(),
        error_message: if matches!(result.status.as_str(), "completed" | "no-op")
            && !outcome.execution_can_resume
        {
            Some(outcome.failures.join("; "))
        } else {
            result.error_message.clone()
        },
        error_class: result
            .error_class
            .as_ref()
            .map(|class| class.as_str().to_string()),
        evidence_paths: result
            .evidence_paths
            .iter()
            .map(|path| rel_path_string(path))
            .collect(),
        worktree_hygiene_foreign_fingerprint: None,
    };
    finalize_unsafe_repair_evidence_with_outcome(
        &evidence_root.join("parent"),
        &summary,
        Some(outcome),
    )
}

fn acquire_child_lock(control_root: &Path, child_id: &str) -> Result<PathBuf> {
    let lock_root = control_root.join("locks");
    fs::create_dir_all(&lock_root)?;
    let lock_path = lock_root.join(format!("{child_id}.lock"));
    let mut file = OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&lock_path)
        .with_context(|| format!("child target lock already exists for {child_id}"))?;
    writeln!(file, "child_id: {child_id}")?;
    Ok(lock_path)
}

fn acquire_child_lock_for_route(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    child_id: &str,
    route_id: &str,
) -> Result<PathBuf> {
    match acquire_child_lock(control_root, child_id) {
        Ok(lock_path) => Ok(lock_path),
        Err(error) => {
            let lock_path = control_root.join("locks").join(format!("{child_id}.lock"));
            let Some(stale_route_id) =
                recoverable_stale_child_lock_route(control_root, child_id, &lock_path)?
            else {
                return Err(error);
            };
            let lock_path_display = lock_path.to_string_lossy().to_string();
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "stale-child-lock-recovery-started",
                Some(child_id),
                Some(&stale_route_id),
                "program lifecycle found recoverable stale child lock before dispatch",
                event_data([
                    ("new_route_id", route_id),
                    ("lock_path", lock_path_display.as_str()),
                ]),
            )?;
            release_child_lock(
                control_root,
                evidence_root,
                program_run_id,
                child_id,
                &stale_route_id,
                &lock_path,
            )
            .with_context(|| {
                format!("program child stale lock recovery failed for {child_id}:{stale_route_id}")
            })?;
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "stale-child-lock-recovered",
                Some(child_id),
                Some(&stale_route_id),
                "program lifecycle recovered stale child lock before dispatch",
                event_data([
                    ("new_route_id", route_id),
                    ("lock_path", lock_path_display.as_str()),
                ]),
            )?;
            acquire_child_lock(control_root, child_id).with_context(|| {
                format!(
                    "child target lock could not be reacquired after stale recovery for {child_id}"
                )
            })
        }
    }
}

fn recoverable_stale_child_lock_route(
    control_root: &Path,
    child_id: &str,
    lock_path: &Path,
) -> Result<Option<String>> {
    let expected_lock_path = control_root.join("locks").join(format!("{child_id}.lock"));
    if lock_path != expected_lock_path || !lock_path.is_file() {
        return Ok(None);
    }
    let contents = fs::read_to_string(lock_path)?;
    if contents.trim() != format!("child_id: {child_id}") {
        return Ok(None);
    }
    let events = read_program_events(control_root)?;
    let Some(started) = events.iter().rev().find(|event| {
        event.child_id.as_deref() == Some(child_id) && event.event_type == "child-route-started"
    }) else {
        return Ok(None);
    };
    if events.iter().any(|event| {
        event.event_index > started.event_index
            && event.child_id.as_deref() == Some(child_id)
            && matches!(
                event.event_type.as_str(),
                "child-lock-released" | "atomic-lock-released"
            )
    }) {
        return Ok(None);
    }
    let controller_advanced_after_start = events.iter().any(|event| {
        event.event_index > started.event_index
            && matches!(
                event.event_type.as_str(),
                "plan-created"
                    | "parent-route-started"
                    | "parent-route-finished"
                    | "aggregate-terminal-blockers"
                    | "compact-evidence-written"
                    | "token-budget-ledger-written"
                    | "publication-freshness-preflight-passed"
                    | "publication-freshness-preflight-blocked"
                    | "program-recovery-action-started"
                    | "program-recovery-action-finished"
                    | "schedule-created"
            )
    });
    if !controller_advanced_after_start {
        return Ok(None);
    }
    Ok(started.route_id.clone())
}

fn recover_terminal_child_stale_locks(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    plan: &ProgramLifecyclePlanResult,
) -> Result<()> {
    for (child_id, state) in &plan.child_states {
        if state.terminal_outcome.is_none() {
            continue;
        }
        let lock_path = control_root.join("locks").join(format!("{child_id}.lock"));
        let Some(stale_route_id) =
            recoverable_stale_child_lock_route(control_root, child_id, &lock_path)?
        else {
            continue;
        };
        let terminal_outcome = state.terminal_outcome.as_deref().unwrap_or("unknown");
        let lock_path_display = lock_path.to_string_lossy().to_string();
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "stale-child-lock-terminal-recovery-started",
            Some(child_id),
            Some(&stale_route_id),
            "program lifecycle found stale child lock after fresh terminal child evidence",
            event_data([
                ("terminal_outcome", terminal_outcome),
                ("lock_path", lock_path_display.as_str()),
            ]),
        )?;
        release_child_lock(
            control_root,
            evidence_root,
            program_run_id,
            child_id,
            &stale_route_id,
            &lock_path,
        )
        .with_context(|| {
            format!(
                "program terminal child stale lock recovery failed for {child_id}:{stale_route_id}"
            )
        })?;
        append_program_event(
            control_root,
            evidence_root,
            program_run_id,
            "stale-child-lock-terminal-recovered",
            Some(child_id),
            Some(&stale_route_id),
            "program lifecycle recovered stale child lock after fresh terminal child evidence",
            event_data([
                ("terminal_outcome", terminal_outcome),
                ("lock_path", lock_path_display.as_str()),
            ]),
        )?;
    }
    Ok(())
}

fn release_child_locks_after_build_failure(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    jobs: &[ChildExecutionJob],
) -> Result<()> {
    for job in jobs {
        release_child_lock(
            control_root,
            evidence_root,
            program_run_id,
            &job.child_id,
            &job.route_id,
            &job.lock_path,
        )
        .with_context(|| {
            format!(
                "program child lock cleanup failed after job construction error for {}:{}",
                job.child_id, job.route_id
            )
        })?;
    }
    Ok(())
}

fn release_child_lock(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    child_id: &str,
    route_id: &str,
    lock_path: &Path,
) -> Result<()> {
    let operation = ProgramArtifactOperation {
        operation_id: format!("remove_child_lock-{child_id}-{route_id}"),
        child_id: child_id.to_string(),
        route_id: route_id.to_string(),
        operation: "remove_child_lock".to_string(),
        destructive_operation: "remove_file".to_string(),
        artifact_paths: vec![lock_path.to_path_buf()],
        command_or_operation: "fs::remove_file".to_string(),
    };
    let criticality = assess_program_artifact_criticality(control_root, program_run_id, &operation);
    match perform_governed_artifact_cleanup(control_root, evidence_root, program_run_id, &operation)
    {
        Ok(criticality_evidence) => {
            let artifact_paths = criticality.artifact_paths.join(",");
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "child-lock-released",
                Some(child_id),
                Some(route_id),
                "program child execution lock released",
                event_data([
                    ("criticality", criticality.criticality.as_str()),
                    ("artifact_path", artifact_paths.as_str()),
                    ("criticality_evidence", criticality_evidence.as_str()),
                ]),
            )?;
            Ok(())
        }
        Err(error) if !criticality.autonomous_allowed => {
            let artifact_paths = criticality.artifact_paths.join(",");
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "child-lock-cleanup-blocked",
                Some(child_id),
                Some(route_id),
                "program child execution lock cleanup requires human input",
                event_data([
                    ("criticality", criticality.criticality.as_str()),
                    ("artifact_path", artifact_paths.as_str()),
                    ("criticality_evidence", "artifact-criticality"),
                ]),
            )?;
            bail!(
                "program child execution lock cleanup requires human input: {}",
                criticality.rationale
            );
        }
        Err(error) => {
            let message = format!(
                "program child execution lock could not be released: {}",
                error
            );
            let artifact_paths = criticality.artifact_paths.join(",");
            append_program_event(
                control_root,
                evidence_root,
                program_run_id,
                "child-lock-stale",
                Some(child_id),
                Some(route_id),
                &message,
                event_data([
                    ("status", "blocked-unsafe"),
                    ("criticality", criticality.criticality.as_str()),
                    ("artifact_path", artifact_paths.as_str()),
                ]),
            )?;
            bail!("{message}");
        }
    }
}

fn assess_program_artifact_criticality(
    control_root: &Path,
    program_run_id: &str,
    operation: &ProgramArtifactOperation,
) -> ProgramArtifactCriticalityDecision {
    let lock_root = control_root.join("locks");
    let tmp_root = control_root.join("tmp");
    let scratch_root = control_root.join("scratch");
    let primary_path = operation
        .artifact_paths
        .first()
        .cloned()
        .unwrap_or_else(PathBuf::new);
    let expected_lock_path = lock_root.join(format!("{}.lock", operation.child_id));
    let path_matches_expected = primary_path == expected_lock_path;
    let under_lock_root = primary_path.starts_with(&lock_root);
    let under_current_run_generated_root =
        primary_path.starts_with(&tmp_root) || primary_path.starts_with(&scratch_root);
    let current_run_control_artifact = primary_path == control_root.join(PROGRAM_CHECKPOINT_FILE)
        || primary_path == control_root.join("program-events.ndjson");
    let workspace_root = control_root
        .ancestors()
        .find(|path| {
            path.file_name()
                .map(|name| name == ".octon")
                .unwrap_or(false)
        })
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| control_root.to_path_buf());
    let workspace_contained = primary_path.starts_with(&workspace_root);
    let declared_cleanup_scopes = vec![authority_path_ref(&workspace_root, control_root)];
    let authority_decision = classify_authority_zone(
        &workspace_root,
        program_run_id,
        Some(&operation.child_id),
        Some(&operation.route_id),
        None,
        OPERATION_CLASS_CLEANUP_CURRENT_RUN_ARTIFACT,
        &operation.artifact_paths,
        &declared_cleanup_scopes,
        None,
    );
    let declared_scope_contained = under_lock_root || under_current_run_generated_root;
    let exists = primary_path.exists();
    let is_file = primary_path.is_file();
    let is_dir = primary_path.is_dir();
    let artifact_path = primary_path.to_string_lossy().to_string();
    let retained_evidence = artifact_path.contains("/state/evidence/runs/workflows/");
    let archive_metadata = artifact_path.contains("/.archive/");
    let operation_supported = supported_destructive_operation(&operation.destructive_operation);
    let authority_surface = if retained_evidence {
        "retained-lifecycle-evidence"
    } else if archive_metadata {
        "archive-metadata"
    } else if authority_decision.authority_zone == AUTHORITY_ZONE_CURRENT_RUN_AGENT_ARTIFACT {
        if under_lock_root {
            "current-run-control-lock"
        } else {
            "current-run-generated-artifact"
        }
    } else if authority_decision.authority_zone == AUTHORITY_ZONE_AUTHORED_GOVERNANCE {
        "authored-contract-or-policy"
    } else if authority_decision.authority_zone == AUTHORITY_ZONE_RUN_BOUND {
        "current-run-control-or-evidence"
    } else if artifact_path.contains("/.octon/framework/")
        || artifact_path.contains("/.octon/instance/")
        || artifact_path.contains("/.octon/inputs/additive/extensions/")
    {
        "authored-contract-or-policy"
    } else if under_lock_root {
        "current-run-control-lock"
    } else if under_current_run_generated_root {
        "current-run-generated-artifact"
    } else {
        "unclear"
    };
    let before_validation = format!(
        "exists={exists}; is_file={is_file}; is_dir={is_dir}; under_current_run_lock_root={under_lock_root}; under_current_run_generated_root={under_current_run_generated_root}; current_run_control_artifact={current_run_control_artifact}; path_matches_child_lock={path_matches_expected}; authority_surface={authority_surface}; operation_supported={operation_supported}"
    );
    let generated_operation = matches!(
        operation.operation.as_str(),
        "generated_artifact_cleanup" | "remove_generated_artifact"
    );
    let current_run_control_operation = matches!(
        operation.operation.as_str(),
        "current_run_control_artifact_cleanup" | "remove_current_run_control_artifact"
    );
    if operation_supported
        && workspace_contained
        && (declared_scope_contained || current_run_control_artifact)
        && authority_decision.autonomous_allowed
        && ((path_matches_expected && under_lock_root)
            || (generated_operation && under_current_run_generated_root)
            || (current_run_control_operation && current_run_control_artifact))
    {
        ProgramArtifactCriticalityDecision {
            schema_version: "octon-program-artifact-criticality-decision-v1".to_string(),
            program_run_id: program_run_id.to_string(),
            classification_policy_version: "octon-program-artifact-criticality-policy-v2"
                .to_string(),
            operation_id: operation.operation_id.clone(),
            child_id: operation.child_id.clone(),
            route_id: operation.route_id.clone(),
            operation: operation.operation.clone(),
            destructive_operation: operation.destructive_operation.clone(),
            artifact_paths: vec![artifact_path],
            classification_inputs: vec![
                format!("path_matches_child_lock={path_matches_expected}"),
                format!("under_current_run_lock_root={under_lock_root}"),
                format!("under_current_run_generated_root={under_current_run_generated_root}"),
                format!("current_run_control_artifact={current_run_control_artifact}"),
                format!("workspace_contained={workspace_contained}"),
                format!(
                    "declared_scope_contained={}",
                    declared_scope_contained || current_run_control_artifact
                ),
                format!("authority_surface={authority_surface}"),
                format!("operation_supported={operation_supported}"),
            ],
            artifact_owner: "current-run".to_string(),
            authority_surface: authority_surface.to_string(),
            authority_zone: authority_decision.authority_zone,
            artifact_class: authority_decision.artifact_class,
            authority_zone_decision: None,
            criticality: "non-critical".to_string(),
            ownership: if under_lock_root {
                "current-run-child-lock".to_string()
            } else if current_run_control_artifact {
                "current-run-control-artifact".to_string()
            } else {
                "current-run-generated-artifact".to_string()
            },
            workspace_contained,
            declared_scope_contained: declared_scope_contained || current_run_control_artifact,
            human_input_required: false,
            autonomous_allowed: true,
            rationale: if under_lock_root {
                "lock is a current-run coordination artifact, is named for the selected child, and is safe to remove after route completion or abandoned job construction".to_string()
            } else if current_run_control_artifact {
                "artifact is a current-run control artifact with retained evidence copy and is safe to remove after classification".to_string()
            } else {
                "artifact is a current-run generated temporary or scratch artifact and is safe to remove after classification".to_string()
            },
            command_or_operation: operation.command_or_operation.clone(),
            before_validation,
            after_validation: "pending".to_string(),
            operation_supported,
            mutation_performed: false,
            mutation_status: "pending".to_string(),
            blocked_reason: None,
        }
    } else {
        let (criticality, ownership, rationale, blocked_reason) = if !operation_supported {
            (
                "unclear",
                "unclear",
                "cleanup operation is unsupported and cannot be classified as safe",
                "unsupported-destructive-operation",
            )
        } else if retained_evidence
            || artifact_path.contains("/.octon/state/evidence/")
            || authority_surface == "authored-contract-or-policy"
            || authority_surface == "archive-metadata"
            || authority_decision.authority_zone == AUTHORITY_ZONE_AUTHORED_GOVERNANCE
        {
            (
                    "critical",
                    authority_surface,
                    "artifact is retained lifecycle evidence or authored authority surface and must not be cleaned autonomously",
                    "critical-artifact",
                )
        } else {
            (
                    "unclear",
                    "unclear",
                    "artifact path is not the expected current-run generated artifact path; ownership is unclear",
                    "artifact-ownership-unclear",
                )
        };
        ProgramArtifactCriticalityDecision {
            schema_version: "octon-program-artifact-criticality-decision-v1".to_string(),
            program_run_id: program_run_id.to_string(),
            classification_policy_version: "octon-program-artifact-criticality-policy-v2"
                .to_string(),
            operation_id: operation.operation_id.clone(),
            child_id: operation.child_id.clone(),
            route_id: operation.route_id.clone(),
            operation: operation.operation.clone(),
            destructive_operation: operation.destructive_operation.clone(),
            artifact_paths: vec![artifact_path],
            classification_inputs: vec![
                format!("path_matches_child_lock={path_matches_expected}"),
                format!("under_current_run_lock_root={under_lock_root}"),
                format!("under_current_run_generated_root={under_current_run_generated_root}"),
                format!("current_run_control_artifact={current_run_control_artifact}"),
                format!("workspace_contained={workspace_contained}"),
                format!(
                    "declared_scope_contained={}",
                    declared_scope_contained || current_run_control_artifact
                ),
                format!("authority_surface={authority_surface}"),
                format!("operation_supported={operation_supported}"),
            ],
            artifact_owner: ownership.to_string(),
            authority_surface: authority_surface.to_string(),
            authority_zone: authority_decision.authority_zone,
            artifact_class: authority_decision.artifact_class,
            authority_zone_decision: None,
            criticality: criticality.to_string(),
            ownership: ownership.to_string(),
            workspace_contained,
            declared_scope_contained,
            human_input_required: true,
            autonomous_allowed: false,
            rationale: rationale.to_string(),
            command_or_operation: operation.command_or_operation.clone(),
            before_validation,
            after_validation: "not-run-human-input-required".to_string(),
            operation_supported,
            mutation_performed: false,
            mutation_status: "blocked".to_string(),
            blocked_reason: Some(blocked_reason.to_string()),
        }
    }
}

fn supported_destructive_operation(operation: &str) -> bool {
    matches!(operation, "remove_file" | "remove_dir" | "remove_dir_all")
}

fn write_artifact_criticality_decision(
    evidence_root: &Path,
    decision: &ProgramArtifactCriticalityDecision,
) -> Result<String> {
    let root = evidence_root.join("artifact-criticality");
    fs::create_dir_all(&root)?;
    let file_stem = sanitize_run_id(&format!(
        "{}-{}-{}",
        decision.operation, decision.child_id, decision.route_id
    ))?;
    let path = root.join(format!("{file_stem}.yml"));
    fs::write(&path, serde_yaml::to_string(decision)?)?;
    Ok(rel_path_string(&path))
}

fn perform_governed_artifact_cleanup(
    control_root: &Path,
    evidence_root: &Path,
    program_run_id: &str,
    operation: &ProgramArtifactOperation,
) -> Result<String> {
    let mut decision = assess_program_artifact_criticality(control_root, program_run_id, operation);
    let workspace_root = control_root
        .ancestors()
        .find(|path| {
            path.file_name()
                .map(|name| name == ".octon")
                .unwrap_or(false)
        })
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| control_root.to_path_buf());
    let declared_cleanup_scopes = vec![authority_path_ref(&workspace_root, control_root)];
    let authority_decision = classify_authority_zone(
        &workspace_root,
        program_run_id,
        Some(&operation.child_id),
        Some(&operation.route_id),
        None,
        OPERATION_CLASS_CLEANUP_CURRENT_RUN_ARTIFACT,
        &operation.artifact_paths,
        &declared_cleanup_scopes,
        None,
    );
    decision.authority_zone_decision = Some(write_authority_zone_decision(
        evidence_root,
        &authority_decision,
    )?);
    write_artifact_criticality_decision(evidence_root, &decision)?;
    if !decision.autonomous_allowed {
        decision.after_validation = "not-run-human-input-required".to_string();
        decision.mutation_performed = false;
        decision.mutation_status = "blocked-human-input-required".to_string();
        if decision.blocked_reason.is_none() {
            decision.blocked_reason = Some("human-input-required".to_string());
        }
        let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
        bail!(
            "program artifact cleanup requires human input: {}; evidence: {}",
            decision.rationale,
            evidence_path
        );
    }
    let Some(path) = operation.artifact_paths.first() else {
        decision.after_validation = "cleanup failed: missing artifact path".to_string();
        write_artifact_criticality_decision(evidence_root, &decision)?;
        bail!("program artifact cleanup failed: missing artifact path");
    };
    match operation.destructive_operation.as_str() {
        "remove_file" => match fs::remove_file(path) {
            Ok(()) => {
                decision.after_validation =
                    "lock artifact absent after autonomous cleanup".to_string();
                decision.mutation_performed = true;
                decision.mutation_status = "completed".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                decision.after_validation =
                    "lock artifact already absent before autonomous cleanup".to_string();
                decision.mutation_performed = false;
                decision.mutation_status = "already-absent".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) => {
                decision.after_validation = format!("cleanup failed: {error}");
                decision.mutation_performed = false;
                decision.mutation_status = "failed".to_string();
                write_artifact_criticality_decision(evidence_root, &decision)?;
                Err(error).with_context(|| "program artifact cleanup failed")
            }
        },
        "remove_dir" => match fs::remove_dir(path) {
            Ok(()) => {
                decision.after_validation =
                    "directory artifact absent after autonomous cleanup".to_string();
                decision.mutation_performed = true;
                decision.mutation_status = "completed".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                decision.after_validation =
                    "directory artifact already absent before autonomous cleanup".to_string();
                decision.mutation_performed = false;
                decision.mutation_status = "already-absent".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) => {
                decision.after_validation = format!("cleanup failed: {error}");
                decision.mutation_performed = false;
                decision.mutation_status = "failed".to_string();
                write_artifact_criticality_decision(evidence_root, &decision)?;
                Err(error).with_context(|| "program artifact cleanup failed")
            }
        },
        "remove_dir_all" => match fs::remove_dir_all(path) {
            Ok(()) => {
                decision.after_validation =
                    "directory tree artifact absent after autonomous cleanup".to_string();
                decision.mutation_performed = true;
                decision.mutation_status = "completed".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                decision.after_validation =
                    "directory tree artifact already absent before autonomous cleanup".to_string();
                decision.mutation_performed = false;
                decision.mutation_status = "already-absent".to_string();
                let evidence_path = write_artifact_criticality_decision(evidence_root, &decision)?;
                Ok(evidence_path)
            }
            Err(error) => {
                decision.after_validation = format!("cleanup failed: {error}");
                decision.mutation_performed = false;
                decision.mutation_status = "failed".to_string();
                write_artifact_criticality_decision(evidence_root, &decision)?;
                Err(error).with_context(|| "program artifact cleanup failed")
            }
        },
        other => {
            decision.after_validation = format!("cleanup failed: unsupported operation {other}");
            decision.mutation_performed = false;
            decision.mutation_status = "blocked-unsupported-operation".to_string();
            decision.blocked_reason = Some("unsupported-destructive-operation".to_string());
            write_artifact_criticality_decision(evidence_root, &decision)?;
            bail!("program artifact cleanup failed: unsupported operation {other}");
        }
    }
}

fn checkpoint_from_plan(
    run_id: &str,
    lifecycle_id: &str,
    target: &str,
    executor: ExecutorKind,
    invocation_authority: &str,
    run_inputs: &BTreeMap<String, String>,
    plan: &ProgramLifecyclePlanResult,
    child_results: &[ProgramChildExecutionSummary],
    final_verdict: &str,
    terminal_outcome: Option<String>,
    latest_event_offset: u64,
    mut previous_recovery_attempts: BTreeMap<String, u32>,
    previous_program_recovery_action_attempts: BTreeMap<String, u32>,
    mut previous_progress_fingerprints: BTreeMap<String, ProgramRecoveryProgressFingerprint>,
    mut closeout_hygiene_suppressions: BTreeMap<String, ProgramCloseoutHygieneSuppression>,
    approvals: Vec<ProgramApprovalGrant>,
) -> ProgramLifecycleCheckpoint {
    let child_states = plan
        .child_states
        .iter()
        .map(|(id, state)| {
            (
                id.clone(),
                ProgramChildCheckpointState {
                    child_lifecycle_id: state.child_lifecycle_id.clone(),
                    target: state.target.clone(),
                    current_state: state
                        .selected_route
                        .as_ref()
                        .map(|route| route.route_id.clone())
                        .or_else(|| state.terminal_outcome.clone()),
                    final_verdict: state.final_verdict.clone(),
                    receipt_digests: state.receipt_digests.clone(),
                    gate_status: state.gate_status.clone(),
                    dependency_gate_status: state.dependency_gate_status.clone(),
                    write_scopes: state.write_scopes.clone(),
                },
            )
        })
        .collect();
    for result in child_results {
        let key = recovery_attempt_key(
            &result.child_id,
            result.blocker_class.as_deref().unwrap_or("route"),
        );
        *previous_recovery_attempts.entry(key).or_default() += result.attempts;
        *previous_recovery_attempts
            .entry(result.child_id.clone())
            .or_default() += result.attempts;
        if result.attempts > 0 {
            if let Some(state) = plan.child_states.get(&result.child_id) {
                let blocker_class = result.blocker_class.as_deref().unwrap_or("route");
                previous_progress_fingerprints.insert(
                    recovery_progress_key(&result.child_id, &result.route_id, blocker_class),
                    child_progress_fingerprint(state, &result.route_id, blocker_class),
                );
            }
        }
        if route_has_closeout_hygiene_preflight(&result.route_id) {
            let key = closeout_hygiene_suppression_key(&result.child_id, &result.route_id);
            if result.status == "blocked"
                && result.blocker_class.as_deref() == Some("artifact-ownership-unclear")
            {
                closeout_hygiene_suppressions.insert(
                    key,
                    ProgramCloseoutHygieneSuppression {
                        child_id: result.child_id.clone(),
                        route_id: result.route_id.clone(),
                        blocker_class: "artifact-ownership-unclear".to_string(),
                        message: result.error_message.clone().unwrap_or_else(|| {
                            "closeout/archive blocked by foreign or ambiguous worktree hygiene"
                                .to_string()
                        }),
                        evidence_paths: result.evidence_paths.clone(),
                        worktree_hygiene_foreign_fingerprint: result
                            .worktree_hygiene_foreign_fingerprint
                            .clone(),
                    },
                );
            } else {
                closeout_hygiene_suppressions.remove(&key);
            }
        }
    }

    ProgramLifecycleCheckpoint {
        schema_version: "octon-program-lifecycle-checkpoint-v1".to_string(),
        run_id: run_id.to_string(),
        lifecycle_id: lifecycle_id.to_string(),
        execution_strategy: plan.execution_strategy.clone(),
        target: target.to_string(),
        executor: Some(executor.as_str().to_string()),
        invocation_authority: invocation_authority.to_string(),
        timeout_seconds: None,
        max_steps: None,
        max_child_concurrency: None,
        child_registry_digest: plan.child_registry_digest.clone(),
        execution_mode: plan.execution_mode.clone(),
        run_inputs: run_inputs.clone(),
        scheduler_decision: plan.runnable_batch.clone(),
        child_states,
        recovery_attempts: previous_recovery_attempts,
        program_recovery_action_attempts: previous_program_recovery_action_attempts,
        recovery_progress_fingerprints: previous_progress_fingerprints,
        closeout_hygiene_suppressions,
        aggregate_terminal_blockers: plan.aggregate_terminal_blockers.clone(),
        residue_cleanup_attempts: BTreeMap::new(),
        worktree_baseline_ref: None,
        interaction_request_refs: Vec::new(),
        interaction_return_refs: Vec::new(),
        approvals,
        program_recovery_recipe_validation_status: plan
            .program_recovery_recipe_validation_status
            .clone(),
        program_recovery_recipe_validation_failures: plan
            .program_recovery_recipe_validation_failures
            .clone(),
        program_recovery_recipe_blocker_class: plan.program_recovery_recipe_blocker_class.clone(),
        program_recovery_recipe_route_id: plan.program_recovery_recipe_route_id.clone(),
        program_recovery_recipe_delegation_contract_basis: plan
            .program_recovery_recipe_delegation_contract_basis
            .clone(),
        latest_event_offset,
        latest_event_index: latest_event_offset,
        latest_event_sha256: None,
        event_log_sha256: None,
        derived_from_event_index: latest_event_offset,
        atomic_barrier_state: None,
        cancelled_at: if final_verdict == "cancelled" {
            Some(now_rfc3339().unwrap_or_else(|_| "unknown".to_string()))
        } else {
            None
        },
        cancel_reason: if final_verdict == "cancelled" {
            Some("cancellation token observed during route dispatch".to_string())
        } else {
            None
        },
        cancellation_evidence_path: None,
        terminal_outcome,
        final_verdict: final_verdict.to_string(),
        resume_instruction: format!("octon lifecycle resume --run-id {run_id}"),
    }
}

fn write_program_checkpoint_snapshot(
    octon_dir: &Path,
    control_root: &Path,
    evidence_root: &Path,
    run_id: &str,
    lifecycle_id: &str,
    target: &str,
    executor: ExecutorKind,
    invocation_authority: &str,
    run_inputs: &BTreeMap<String, String>,
    plan: &ProgramLifecyclePlanResult,
    child_results: &[ProgramChildExecutionSummary],
    final_verdict: &str,
    terminal_outcome: Option<String>,
    previous_checkpoint: Option<&ProgramLifecycleCheckpoint>,
    options: &RunLifecycleOptions,
    residue_cleanup_attempts: Option<&BTreeMap<String, ProgramResidueCleanupAttempt>>,
) -> Result<ProgramLifecycleCheckpoint> {
    let mut checkpoint = checkpoint_from_plan(
        run_id,
        lifecycle_id,
        target,
        executor,
        invocation_authority,
        run_inputs,
        plan,
        child_results,
        final_verdict,
        terminal_outcome,
        count_program_events(control_root)?,
        previous_checkpoint
            .map(|checkpoint| checkpoint.recovery_attempts.clone())
            .unwrap_or_default(),
        previous_checkpoint
            .map(|checkpoint| checkpoint.program_recovery_action_attempts.clone())
            .unwrap_or_default(),
        previous_checkpoint
            .map(|checkpoint| checkpoint.recovery_progress_fingerprints.clone())
            .unwrap_or_default(),
        plan.closeout_hygiene_suppressions.clone(),
        previous_checkpoint
            .map(|checkpoint| checkpoint.approvals.clone())
            .unwrap_or_default(),
    );
    checkpoint.residue_cleanup_attempts = residue_cleanup_attempts
        .cloned()
        .or_else(|| {
            previous_checkpoint.map(|checkpoint| checkpoint.residue_cleanup_attempts.clone())
        })
        .unwrap_or_default();
    let repo_root = repo_root_for_octon(octon_dir)?;
    checkpoint.worktree_baseline_ref = previous_checkpoint
        .and_then(|checkpoint| checkpoint.worktree_baseline_ref.clone())
        .or_else(|| {
            let baseline = evidence_root.join(PROGRAM_WORKTREE_BASELINE_FILE);
            baseline
                .is_file()
                .then(|| rel_display(&repo_root, &baseline))
        });
    let previous_interaction_request_refs = previous_checkpoint
        .map(|checkpoint| checkpoint.interaction_request_refs.clone())
        .unwrap_or_default();
    let previous_interaction_request_refs = actionable_lifecycle_interaction_request_refs(
        &repo_root,
        previous_interaction_request_refs,
    )?;
    let previous_interaction_return_refs = previous_checkpoint
        .map(|checkpoint| checkpoint.interaction_return_refs.clone())
        .unwrap_or_default();
    let (input_interaction_request_refs, input_interaction_return_refs) =
        lifecycle_interaction_refs_from_run_inputs(&repo_root, run_inputs)?;
    let mut interaction_return_refs = previous_interaction_return_refs.clone();
    for input_ref in input_interaction_return_refs {
        push_unique_string(&mut interaction_return_refs, input_ref);
    }
    for retained_ref in lifecycle_interaction_return_refs_from_inputs_and_retained_dir(
        &repo_root, run_id, run_inputs,
    )? {
        push_unique_string(&mut interaction_return_refs, retained_ref);
    }
    let mut interaction_request_refs = previous_interaction_request_refs;
    for input_ref in input_interaction_request_refs {
        push_unique_string(&mut interaction_request_refs, input_ref);
    }
    for emitted_ref in child_result_interaction_request_refs(&repo_root, child_results)? {
        push_unique_string(&mut interaction_request_refs, emitted_ref);
    }
    checkpoint.interaction_request_refs = unresolved_lifecycle_interaction_request_refs(
        &repo_root,
        interaction_request_refs,
        &interaction_return_refs,
    )?;
    checkpoint.interaction_return_refs = interaction_return_refs;
    checkpoint.timeout_seconds = options.timeout_seconds;
    checkpoint.max_steps = options.max_steps;
    checkpoint.max_child_concurrency = options.max_child_concurrency;
    if final_verdict == "cancelled" {
        if let Some(existing) = read_program_checkpoint_for_run(octon_dir, run_id)? {
            if existing.cancelled_at.is_some() || existing.cancellation_evidence_path.is_some() {
                checkpoint.cancelled_at = existing.cancelled_at;
                checkpoint.cancel_reason = existing.cancel_reason;
                checkpoint.cancellation_evidence_path = existing.cancellation_evidence_path;
                checkpoint.terminal_outcome = Some("cancelled".to_string());
                checkpoint.resume_instruction =
                    "cancelled program lifecycle runs cannot resume dispatch".to_string();
            }
        }
    }
    enrich_checkpoint_event_metadata(&mut checkpoint, control_root)?;
    let checkpoint_path = program_checkpoint_path_for_run(octon_dir, run_id)?;
    write_program_checkpoint_files(&checkpoint_path, evidence_root, &checkpoint)?;
    Ok(checkpoint)
}

fn write_program_checkpoint_files(
    checkpoint_path: &Path,
    evidence_root: &Path,
    checkpoint: &ProgramLifecycleCheckpoint,
) -> Result<()> {
    let serialized = serde_yaml::to_string(checkpoint)?;
    fs::write(checkpoint_path, &serialized)?;
    fs::create_dir_all(evidence_root)?;
    fs::write(program_retained_checkpoint_path(evidence_root), serialized)?;
    Ok(())
}

fn program_retained_checkpoint_path(evidence_root: &Path) -> PathBuf {
    evidence_root.join(PROGRAM_CHECKPOINT_FILE)
}

fn enrich_checkpoint_event_metadata(
    checkpoint: &mut ProgramLifecycleCheckpoint,
    control_root: &Path,
) -> Result<()> {
    let events = read_program_events(control_root)?;
    let latest_index = events.last().map(|event| event.event_index).unwrap_or(0);
    checkpoint.latest_event_offset = latest_index;
    checkpoint.latest_event_index = latest_index;
    checkpoint.derived_from_event_index = latest_index;
    checkpoint.latest_event_sha256 = events.last().and_then(|event| event.event_sha256.clone());
    checkpoint.event_log_sha256 = program_event_log_digest(control_root)?;
    checkpoint.atomic_barrier_state = reconstruct_atomic_barrier_state(&events);
    Ok(())
}

fn program_checkpoint_cancelled(checkpoint: &ProgramLifecycleCheckpoint) -> bool {
    checkpoint.final_verdict == "cancelled" || checkpoint.cancelled_at.is_some()
}

fn program_cancelled_run_result(
    repo_root: &Path,
    evidence_root: &Path,
    control_root: &Path,
    checkpoint: &ProgramLifecycleCheckpoint,
    executor: &str,
) -> ProgramLifecycleRunResult {
    ProgramLifecycleRunResult {
        schema_version: "octon-program-lifecycle-run-result-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        execution_strategy: checkpoint.execution_strategy.clone(),
        target: checkpoint.target.clone(),
        executor: executor.to_string(),
        route_execution_mode: "none".to_string(),
        bundle_root: rel_display(repo_root, evidence_root),
        checkpoint_path: rel_display(repo_root, &control_root.join(PROGRAM_CHECKPOINT_FILE)),
        event_log_path: rel_display(repo_root, &program_control_event_log_path(control_root)),
        latest_event_offset: checkpoint.latest_event_offset,
        selected_parent_route: None,
        parent_route_result: None,
        selected_children: Vec::new(),
        child_results: Vec::new(),
        interaction_request_refs: checkpoint.interaction_request_refs.clone(),
        interaction_return_refs: checkpoint.interaction_return_refs.clone(),
        terminal_outcome: Some("cancelled".to_string()),
        final_verdict: "cancelled".to_string(),
    }
}

fn validate_program_checkpoint_binding(
    repo_root: &Path,
    checkpoint: &ProgramLifecycleCheckpoint,
    sanitized_run_id: &str,
    lifecycle_id: &str,
    execution_strategy: &str,
    target: &str,
    child_registry_digest: &str,
) -> Result<()> {
    if checkpoint.run_id != sanitized_run_id {
        bail!(
            "program lifecycle run id {sanitized_run_id} is inconsistent with checkpoint run_id {}",
            checkpoint.run_id
        );
    }
    if checkpoint.lifecycle_id != lifecycle_id
        || !program_checkpoint_targets_match(repo_root, &checkpoint.target, target)?
    {
        bail!(
            "program lifecycle run id {sanitized_run_id} is already bound to lifecycle {} target {}; requested lifecycle {lifecycle_id} target {target}",
            checkpoint.lifecycle_id,
            checkpoint.target
        );
    }
    if checkpoint.execution_strategy != execution_strategy {
        bail!(
            "program lifecycle run id {sanitized_run_id} checkpoint execution_strategy {} differs from loaded contract strategy {execution_strategy}",
            checkpoint.execution_strategy
        );
    }
    if checkpoint.child_registry_digest != child_registry_digest
        && checkpoint.child_registry_digest != MISSING_CHILD_REGISTRY_DIGEST
    {
        bail!(
            "unsafe program resume: child registry digest changed from {} to {}",
            checkpoint.child_registry_digest,
            child_registry_digest
        );
    }
    Ok(())
}

fn program_checkpoint_targets_match(
    repo_root: &Path,
    checkpoint_target: &str,
    requested_target: &str,
) -> Result<bool> {
    if checkpoint_target == requested_target {
        return Ok(true);
    }
    if !is_safe_repo_relative(checkpoint_target) || !is_safe_repo_relative(requested_target) {
        return Ok(false);
    }
    let checkpoint_path = Path::new(checkpoint_target);
    let requested_path = Path::new(requested_target);
    for (active, archived_candidate) in [
        (checkpoint_path, requested_target),
        (requested_path, checkpoint_target),
    ] {
        let Some(archived_path) = archived_target_for_active_target(active) else {
            continue;
        };
        if rel_path_string(&archived_path) != archived_candidate {
            continue;
        }
        if proposal_status_at_target(&repo_root.join(&archived_path))?.as_deref()
            == Some("archived")
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn read_program_checkpoint_for_run(
    octon_dir: &Path,
    run_id: &str,
) -> Result<Option<ProgramLifecycleCheckpoint>> {
    let path = program_checkpoint_path_for_run(octon_dir, run_id)?;
    if !path.is_file() {
        return Ok(None);
    }
    Ok(Some(serde_yaml::from_slice(&fs::read(path)?)?))
}

fn program_checkpoint_path_for_run(octon_dir: &Path, run_id: &str) -> Result<PathBuf> {
    Ok(octon_dir
        .join(RUN_CONTROL_ROOT_REL)
        .join(sanitize_run_id(run_id)?)
        .join(PROGRAM_CHECKPOINT_FILE))
}

fn declared_or_default_write_scopes(
    child: &ProgramChildSpec,
    child_target_rel: &str,
) -> Result<Vec<String>> {
    if child.write_scopes.is_empty() {
        return Ok(vec![child_target_rel.to_string()]);
    }
    let mut scopes = BTreeSet::new();
    scopes.insert(child_target_rel.to_string());
    for scope in &child.write_scopes {
        if !is_safe_repo_relative(scope) {
            bail!("child write scope must be repo-relative: {scope}");
        }
        scopes.insert(scope.clone());
    }
    Ok(scopes.into_iter().collect())
}

fn write_program_compact_evidence_bundle(
    repo_root: &Path,
    evidence_root: &Path,
    run_id: &str,
    token_ledger_path: &Path,
) -> Result<ProgramCompactEvidenceBundle> {
    let generated_at = now_rfc3339()?;
    let raw_sources = collect_program_raw_log_sources(evidence_root)?;
    let failing_slice_manifest_path = evidence_root.join("failing-slice-manifest.yml");
    let (failing_slice_manifest, raw_summary_records) =
        build_program_failing_slice_manifest(repo_root, run_id, &generated_at, &raw_sources)?;
    fs::write(
        &failing_slice_manifest_path,
        serde_yaml::to_string(&failing_slice_manifest)?,
    )?;

    let raw_log_summary_path = evidence_root.join("raw-log-summary.yml");
    let raw_log_summary = ProgramRawLogSummary {
        schema_version: "octon-raw-log-summary-v1".to_string(),
        run_id: run_id.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        generated_at: generated_at.clone(),
        authority_boundary: compact_evidence_authority_boundary(),
        token_ceiling: COMPACT_EVIDENCE_TOKEN_CEILING,
        default_reader_preference: "prefer-compact-summary-then-handle-only-raw-ref".to_string(),
        source_count: raw_summary_records.len(),
        summaries: raw_summary_records,
        failure_behavior: compact_evidence_failure_behavior(),
    };
    fs::write(
        &raw_log_summary_path,
        serde_yaml::to_string(&raw_log_summary)?,
    )?;

    let evidence_index_path = write_program_evidence_index(
        repo_root,
        evidence_root,
        run_id,
        token_ledger_path,
        &raw_sources,
        &generated_at,
    )?;

    Ok(ProgramCompactEvidenceBundle {
        evidence_index_path,
        raw_log_summary_path,
        failing_slice_manifest_path,
    })
}

fn refresh_program_evidence_index(
    repo_root: &Path,
    evidence_root: &Path,
    run_id: &str,
    token_ledger_path: &Path,
) -> Result<PathBuf> {
    let generated_at = now_rfc3339()?;
    let raw_sources = collect_program_raw_log_sources(evidence_root)?;
    write_program_evidence_index(
        repo_root,
        evidence_root,
        run_id,
        token_ledger_path,
        &raw_sources,
        &generated_at,
    )
}

fn write_program_evidence_index(
    repo_root: &Path,
    evidence_root: &Path,
    run_id: &str,
    token_ledger_path: &Path,
    raw_sources: &[ProgramCompactEvidenceSource],
    generated_at: &str,
) -> Result<PathBuf> {
    let evidence_index_path = evidence_root.join("evidence-index.yml");
    let index_sources =
        collect_program_evidence_index_sources(evidence_root, token_ledger_path, raw_sources)?;
    let source_artifacts = index_sources
        .iter()
        .map(|source| evidence_index_source_artifact(repo_root, source))
        .collect::<Result<Vec<_>>>()?;
    let compact_artifacts = collect_program_evidence_index_compact_artifacts(
        repo_root,
        evidence_root,
        raw_sources.len(),
    )?;
    let evidence_index = ProgramEvidenceIndex {
        schema_version: "octon-evidence-index-v1".to_string(),
        run_id: run_id.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        generated_at: generated_at.to_string(),
        authority_boundary: compact_evidence_authority_boundary(),
        reader_preferences: ProgramEvidenceReaderPreferences {
            planner: format!(
                "read {PLANNER_STATE_FILE}, {PROGRAM_CONTEXT_CAPSULE_FILE}, and {BLOCKER_LEDGER_FILE} first; verify source_refs before raw refs"
            ),
            recovery: format!(
                "read {RECOVERY_DELTA_SUMMARY_FILE}, {BLOCKER_LEDGER_FILE}, raw-log-summary.yml, and failing-slice-manifest.yml before raw logs"
            ),
            closeout: "verify compact digests, then dereference raw evidence only when required"
                .to_string(),
            raw_body_policy: "handle-only-by-default".to_string(),
            raw_body_escalation_required: true,
        },
        source_artifacts,
        compact_artifacts,
        failure_behavior: compact_evidence_failure_behavior(),
    };
    fs::write(
        &evidence_index_path,
        serde_yaml::to_string(&evidence_index)?,
    )?;
    Ok(evidence_index_path)
}

fn collect_program_evidence_index_compact_artifacts(
    repo_root: &Path,
    evidence_root: &Path,
    raw_source_count: usize,
) -> Result<Vec<ProgramEvidenceIndexCompactArtifact>> {
    let mut artifacts = Vec::new();
    for (file_name, role) in [
        ("raw-log-summary.yml", "raw-log-summary"),
        ("failing-slice-manifest.yml", "failing-slice-manifest"),
        (BLOCKER_LEDGER_FILE, "blocker-ledger"),
        (RECOVERY_DELTA_SUMMARY_FILE, "recovery-delta-summary"),
        (
            COMPACT_BLOCKER_REMEDIATION_RECEIPT_FILE,
            "compact-blocker-remediation-receipt",
        ),
        (
            NO_DISPATCH_ATTEMPT_LEDGER_FILE,
            "no-dispatch-attempt-ledger",
        ),
        (PLANNER_STATE_FILE, "planner-state"),
        (PROGRAM_CONTEXT_CAPSULE_FILE, "program-context-capsule"),
        (ROUTE_DECISION_RECEIPT_FILE, "route-decision-receipt"),
        (MODEL_ROUTING_RECEIPT_FILE, "model-routing-receipt"),
        (ACTION_SLICE_LEDGER_FILE, "action-slice-ledger"),
        (
            COMPACT_COMPLETION_CAPSULE_FILE,
            "compact-completion-capsule",
        ),
    ] {
        let path = evidence_root.join(file_name);
        if !path.is_file() {
            continue;
        }
        let source_artifact_count = match file_name {
            "raw-log-summary.yml" | "failing-slice-manifest.yml" => raw_source_count,
            _ => compact_artifact_source_count(&path)?,
        };
        artifacts.push(evidence_index_compact_artifact(
            repo_root,
            &path,
            role,
            source_artifact_count,
        )?);
    }
    Ok(artifacts)
}

fn compact_artifact_source_count(path: &Path) -> Result<usize> {
    let value: serde_yaml::Value = serde_yaml::from_slice(&fs::read(path)?)?;
    Ok(value
        .get("source_refs")
        .or_else(|| value.get("source_evidence_refs"))
        .and_then(serde_yaml::Value::as_sequence)
        .map(|items| items.len())
        .unwrap_or(0))
}

fn write_program_planner_state_artifacts(
    repo_root: &Path,
    control_root: &Path,
    evidence_root: &Path,
    target_rel: &str,
    program: &ProgramSpec,
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
    token_ledger_path: &Path,
    compact_evidence: &ProgramCompactEvidenceBundle,
) -> Result<()> {
    let generated_at = now_rfc3339()?;
    let source_refs = program_compact_source_refs(
        repo_root,
        control_root,
        evidence_root,
        plan,
        token_ledger_path,
        compact_evidence,
    )?;
    let validation_binding = program_compact_validation_binding(checkpoint);
    let route_decision = program_context_route_decision(plan, checkpoint);
    write_program_routing_artifacts(
        repo_root,
        evidence_root,
        target_rel,
        plan,
        checkpoint,
        &source_refs,
        &validation_binding,
        &route_decision,
        &generated_at,
    )?;

    let planner_state_path = evidence_root.join(PLANNER_STATE_FILE);
    let planner_state = ProgramPlannerState {
        schema_version: "octon-program-planner-state-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        target: target_rel.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        generated_at: generated_at.clone(),
        authority_boundary: compact_evidence_authority_boundary(),
        default_reader_preference:
            "prefer-planner-state-when-source-refs-verify; otherwise reconstruct from checkpoint and event log"
                .to_string(),
        token_ceiling: PROGRAM_CONTEXT_CAPSULE_TOKEN_CEILING,
        aggregate_state: plan.aggregate_state.clone(),
        final_verdict: checkpoint.final_verdict.clone(),
        terminal_outcome: checkpoint.terminal_outcome.clone(),
        scheduler_phase: plan.scheduler_phase.clone(),
        route_decision: route_decision.clone(),
        runnable_batch: plan.runnable_batch.clone(),
        blocker_vector: program_blocker_vector(plan),
        diagnostics: program_planner_diagnostics(plan),
        nonblocking_diagnostics: program_nonblocking_diagnostics(plan),
        route_ready: program_route_ready_state(plan, checkpoint),
        blocker_counts: program_blocker_counts(plan),
        child_states: program_planner_child_states(plan),
        source_refs: source_refs.clone(),
        validation_binding: validation_binding.clone(),
    };
    fs::write(&planner_state_path, serde_yaml::to_string(&planner_state)?)?;
    verify_program_compact_artifact_source_refs(repo_root, &planner_state_path)?;

    let program_context_capsule_path = evidence_root.join(PROGRAM_CONTEXT_CAPSULE_FILE);
    let context_capsule = ProgramContextCapsule {
        schema_version: "octon-program-context-capsule-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        target: target_rel.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        generated_at: generated_at.clone(),
        authority_boundary: compact_evidence_authority_boundary(),
        default_reader_preference:
            "verify source_refs and validation_binding before using this capsule for planner context"
                .to_string(),
        child_status_table: program_context_child_status_table(plan),
        dependency_vector: program_context_dependency_vector(plan),
        runnable_batch: plan.runnable_batch.clone(),
        blockers: program_context_blockers(plan),
        blocker_vector: program_blocker_vector(plan),
        diagnostics: program_planner_diagnostics(plan),
        nonblocking_diagnostics: program_nonblocking_diagnostics(plan),
        route_ready: program_route_ready_state(plan, checkpoint),
        route_decision: route_decision.clone(),
        key_digests: program_context_key_digests(checkpoint, &source_refs),
        evidence_refs: source_refs
            .iter()
            .map(|source_ref| source_ref.artifact_ref.clone())
            .collect(),
        source_refs: source_refs.clone(),
        validation_binding: validation_binding.clone(),
    };
    fs::write(
        &program_context_capsule_path,
        serde_yaml::to_string(&context_capsule)?,
    )?;
    verify_program_compact_artifact_source_refs(repo_root, &program_context_capsule_path)?;

    write_program_blocker_recovery_artifacts(
        repo_root,
        evidence_root,
        target_rel,
        program,
        plan,
        checkpoint,
        &compact_evidence.failing_slice_manifest_path,
        &generated_at,
        &source_refs,
        &validation_binding,
    )?;

    if should_write_compact_completion_capsule(plan, checkpoint) {
        let terminal_outcome = checkpoint
            .terminal_outcome
            .clone()
            .context("compact completion capsule requires terminal outcome")?;
        let path = evidence_root.join(COMPACT_COMPLETION_CAPSULE_FILE);
        let capsule = ProgramCompactCompletionCapsule {
            schema_version: "octon-program-compact-completion-capsule-v1".to_string(),
            run_id: checkpoint.run_id.clone(),
            lifecycle_id: checkpoint.lifecycle_id.clone(),
            target: target_rel.to_string(),
            producer: "lifecycle-program-controller".to_string(),
            generated_at,
            authority_boundary: compact_evidence_authority_boundary(),
            completion_kind: "no-dispatch-terminal-parent".to_string(),
            final_verdict: checkpoint.final_verdict.clone(),
            terminal_outcome,
            route_decision,
            source_refs: source_refs.clone(),
            validation_binding,
        };
        fs::write(&path, serde_yaml::to_string(&capsule)?)?;
        verify_program_compact_artifact_source_refs(repo_root, &path)?;
    }

    Ok(())
}

fn write_program_routing_artifacts(
    repo_root: &Path,
    evidence_root: &Path,
    target_rel: &str,
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
    source_refs: &[ProgramCompactSourceRef],
    validation_binding: &ProgramCompactValidationBinding,
    route_decision: &ProgramContextRouteDecision,
    generated_at: &str,
) -> Result<()> {
    let source_digests = program_source_digest_map(source_refs);
    let evidence_refs = source_refs
        .iter()
        .map(|source_ref| source_ref.artifact_ref.clone())
        .collect::<Vec<_>>();
    let validation = program_routing_artifact_validation(
        checkpoint,
        route_decision,
        source_refs,
        &source_digests,
    )?;

    let route_decision_path = evidence_root.join(ROUTE_DECISION_RECEIPT_FILE);
    let route_receipt = ProgramRouteDecisionReceipt {
        schema_version: "octon-program-route-decision-receipt-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        target: target_rel.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        consumer: "proposal-program-planner-and-context-pack-builder".to_string(),
        generated_at: generated_at.to_string(),
        authority_boundary: compact_evidence_authority_boundary(),
        route_decision: route_decision.clone(),
        selected_route_owner: program_route_owner(plan),
        route_bypass_guard: program_route_bypass_guard(plan),
        route_selection_inputs: program_route_selection_inputs(
            plan,
            checkpoint,
            source_refs,
            &source_digests,
        ),
        blocked_alternatives: program_blocked_alternatives(plan),
        retry_fingerprint_inputs: program_retry_fingerprint_inputs(plan),
        resume_source_refs: program_resume_source_refs(checkpoint, source_refs, &validation),
        delivery_handoff: program_delivery_handoff_evidence(
            plan,
            checkpoint,
            &validation,
            ROUTE_DECISION_RECEIPT_FILE,
        ),
        deterministic_preflights: program_deterministic_preflights(plan),
        source_refs: source_refs.to_vec(),
        source_digests: source_digests.clone(),
        validation: validation.clone(),
        validation_binding: validation_binding.clone(),
        evidence_refs: evidence_refs.clone(),
        failure_behavior: program_routing_failure_behavior(),
    };
    fs::write(&route_decision_path, serde_yaml::to_string(&route_receipt)?)?;
    verify_program_compact_artifact_source_refs(repo_root, &route_decision_path)?;

    let model_routing_path = evidence_root.join(MODEL_ROUTING_RECEIPT_FILE);
    let selected_model_route = program_model_route_for_step(plan, checkpoint);
    let model_receipt = ProgramModelRoutingReceipt {
        schema_version: "octon-program-model-routing-receipt-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        target: target_rel.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        consumer: "proposal-program-route-executor".to_string(),
        generated_at: generated_at.to_string(),
        authority_boundary: compact_evidence_authority_boundary(),
        token_ceiling: token_ceiling_for_model_route(&selected_model_route, plan, checkpoint),
        selected_model_route,
        escalation_triggers_observed: program_escalation_triggers(plan),
        route_matrix: program_model_route_matrix(),
        fallback_behavior: program_model_routing_fallback_behavior(),
        raw_full_evidence_model_visible_by_default: false,
        source_refs: source_refs.to_vec(),
        source_digests: source_digests.clone(),
        validation: validation.clone(),
        validation_binding: validation_binding.clone(),
        evidence_refs: evidence_refs.clone(),
        failure_behavior: program_routing_failure_behavior(),
    };
    fs::write(&model_routing_path, serde_yaml::to_string(&model_receipt)?)?;
    verify_program_compact_artifact_source_refs(repo_root, &model_routing_path)?;

    let action_slice_path = evidence_root.join(ACTION_SLICE_LEDGER_FILE);
    let ledger = ProgramActionSliceLedger {
        schema_version: "octon-program-action-slice-ledger-v1".to_string(),
        run_id: checkpoint.run_id.clone(),
        lifecycle_id: checkpoint.lifecycle_id.clone(),
        target: target_rel.to_string(),
        producer: "lifecycle-program-controller".to_string(),
        consumer: "proposal-program-replan-loop".to_string(),
        generated_at: generated_at.to_string(),
        authority_boundary: compact_evidence_authority_boundary(),
        selected_slice: route_decision.step_kind.clone(),
        max_steps: checkpoint.max_steps.unwrap_or(DEFAULT_PROGRAM_MAX_STEPS),
        max_child_concurrency: checkpoint
            .max_child_concurrency
            .unwrap_or(DEFAULT_MAX_CHILD_CONCURRENCY),
        runnable_batch: plan.runnable_batch.clone(),
        action_slices: program_action_slice_entries(plan, checkpoint, route_decision),
        deterministic_preflights: program_deterministic_preflights(plan),
        source_refs: source_refs.to_vec(),
        source_digests,
        validation,
        validation_binding: validation_binding.clone(),
        evidence_refs,
        failure_behavior: program_routing_failure_behavior(),
    };
    fs::write(&action_slice_path, serde_yaml::to_string(&ledger)?)?;
    verify_program_compact_artifact_source_refs(repo_root, &action_slice_path)?;

    Ok(())
}

fn program_source_digest_map(source_refs: &[ProgramCompactSourceRef]) -> BTreeMap<String, String> {
    source_refs
        .iter()
        .map(|source_ref| (source_ref.artifact_role.clone(), source_ref.sha256.clone()))
        .collect()
}

fn program_routing_artifact_validation(
    checkpoint: &ProgramLifecycleCheckpoint,
    route_decision: &ProgramContextRouteDecision,
    source_refs: &[ProgramCompactSourceRef],
    source_digests: &BTreeMap<String, String>,
) -> Result<ProgramRoutingArtifactValidation> {
    let model_visible_context = serde_yaml::to_string(&(
        route_decision,
        checkpoint.max_steps,
        checkpoint.max_child_concurrency,
        source_digests,
    ))?;
    Ok(ProgramRoutingArtifactValidation {
        status: "digest-bound".to_string(),
        validator: "verify_program_compact_artifact_source_refs".to_string(),
        source_event_index: effective_checkpoint_event_index(checkpoint),
        source_event_sha256: checkpoint.latest_event_sha256.clone(),
        source_event_log_sha256: checkpoint.event_log_sha256.clone(),
        child_registry_digest: checkpoint.child_registry_digest.clone(),
        model_visible_context_sha256: stable_text_digest(&format!(
            "{}\nsource-count:{}",
            model_visible_context,
            source_refs.len()
        )),
    })
}

fn program_route_owner(plan: &ProgramLifecyclePlanResult) -> String {
    if plan.program_route.is_some() && plan.runnable_batch.is_empty() {
        "parent-route-owned".to_string()
    } else if plan.program_route.is_none() && !plan.runnable_batch.is_empty() {
        "child-route-owned".to_string()
    } else if plan.program_route.is_none() && plan.runnable_batch.is_empty() {
        "none-no-dispatch".to_string()
    } else {
        "invalid-mixed-parent-and-child-route-selection".to_string()
    }
}

fn program_selected_child_routes(
    plan: &ProgramLifecyclePlanResult,
) -> Vec<ProgramSelectedChildRoute> {
    plan.runnable_batch
        .iter()
        .filter_map(|child_id| {
            let state = plan.child_states.get(child_id)?;
            let route = state.selected_route.as_ref()?;
            Some(ProgramSelectedChildRoute {
                child_id: child_id.clone(),
                route_id: route.route_id.clone(),
                route_type: route.route_type.clone(),
                route_owner: "child-lifecycle-route".to_string(),
            })
        })
        .collect()
}

fn program_route_selection_inputs(
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
    source_refs: &[ProgramCompactSourceRef],
    _source_digests: &BTreeMap<String, String>,
) -> ProgramRouteSelectionInputs {
    let child_receipt_digest_count = plan
        .child_states
        .values()
        .map(|state| state.receipt_digests.len())
        .sum();
    ProgramRouteSelectionInputs {
        continuation_mode: "clean-delivery-orchestrated-replan-loop".to_string(),
        selection_rule:
            "select exactly one route-owned parent route or one child-owned runnable batch; otherwise stop with typed blocker"
                .to_string(),
        live_state_sources: vec![
            "parent proposal.yml".to_string(),
            "resources/child-packet-index.yml".to_string(),
            "child proposal manifests".to_string(),
            "child-owned support receipts".to_string(),
            "program lifecycle checkpoint".to_string(),
            "program event log".to_string(),
            "retained run evidence".to_string(),
        ],
        child_registry_digest: checkpoint.child_registry_digest.clone(),
        source_ref_count: source_refs.len(),
        source_ref_digest: stable_text_digest(
            &source_refs
                .iter()
                .map(|source_ref| {
                    format!(
                        "{}:{}:{}",
                        source_ref.artifact_role, source_ref.artifact_ref, source_ref.sha256
                    )
                })
                .collect::<Vec<_>>()
                .join("\n"),
        ),
        parent_receipt_count: plan.parent_receipt_states.len(),
        child_receipt_digest_count,
        generated_outputs_authority: "derived-only".to_string(),
        parent_summary_satisfies_child_receipts: false,
    }
}

fn program_blocked_alternatives(
    plan: &ProgramLifecyclePlanResult,
) -> Vec<ProgramBlockedAlternative> {
    let mut alternatives = Vec::new();
    for blocker in &plan.program_blockers {
        let candidate_route = blocker
            .recovery_route
            .clone()
            .or_else(|| {
                plan.program_route
                    .as_ref()
                    .map(|route| route.route_id.clone())
            })
            .unwrap_or_else(|| "none".to_string());
        alternatives.push(ProgramBlockedAlternative {
            scope: "program".to_string(),
            child_id: None,
            candidate_route,
            blocker_class: blocker.blocker_class.clone(),
            message: blocker.message.clone(),
            disposition: program_blocker_disposition_label(&blocker.blocker_class).to_string(),
            recovery_owner: blocker
                .recovery_route
                .clone()
                .unwrap_or_else(|| "program-or-human-owner".to_string()),
        });
    }
    for state in plan.child_states.values() {
        for blocker in &state.blockers {
            let candidate_route = blocker
                .recovery_route
                .clone()
                .or_else(|| {
                    state
                        .selected_route
                        .as_ref()
                        .map(|route| route.route_id.clone())
                })
                .unwrap_or_else(|| "none".to_string());
            alternatives.push(ProgramBlockedAlternative {
                scope: "child".to_string(),
                child_id: Some(state.child_id.clone()),
                candidate_route,
                blocker_class: blocker.blocker_class.clone(),
                message: blocker.message.clone(),
                disposition: program_blocker_disposition_label(&blocker.blocker_class).to_string(),
                recovery_owner: blocker
                    .recovery_route
                    .clone()
                    .unwrap_or_else(|| "child-lifecycle-owner".to_string()),
            });
        }
    }
    alternatives
}

fn program_retry_fingerprint_inputs(
    plan: &ProgramLifecyclePlanResult,
) -> Vec<ProgramRetryFingerprintInput> {
    let mut inputs = Vec::new();
    let parent_target_digest = stable_text_digest(&plan.target);
    let parent_receipt_digest = parent_receipt_state_digest(&plan.parent_receipt_states);
    for blocker in &plan.program_blockers {
        let route_id = blocker
            .recovery_route
            .clone()
            .or_else(|| {
                plan.program_route
                    .as_ref()
                    .map(|route| route.route_id.clone())
            })
            .unwrap_or_else(|| "none".to_string());
        inputs.push(program_retry_fingerprint_input(
            "program",
            None,
            &blocker.blocker_class,
            &route_id,
            &parent_target_digest,
            &parent_receipt_digest,
            &stable_text_digest("program-parent-write-scope"),
            &stable_text_digest(&format!(
                "{}:{}:{}",
                plan.child_registry_digest, plan.target, route_id
            )),
            blocker
                .recovery_route
                .as_deref()
                .unwrap_or("program-or-human-owner"),
        ));
    }
    for state in plan.child_states.values() {
        let target_digest = stable_text_digest(&state.target);
        let receipt_digest = stable_text_digest(
            &state
                .receipt_digests
                .iter()
                .map(|(receipt_id, digest)| format!("{receipt_id}:{digest}"))
                .collect::<Vec<_>>()
                .join("\n"),
        );
        let write_scope_digest = stable_text_digest(&state.write_scopes.join("\n"));
        for blocker in &state.blockers {
            let route_id = blocker
                .recovery_route
                .clone()
                .or_else(|| {
                    state
                        .selected_route
                        .as_ref()
                        .map(|route| route.route_id.clone())
                })
                .unwrap_or_else(|| "none".to_string());
            inputs.push(program_retry_fingerprint_input(
                "child",
                Some(&state.child_id),
                &blocker.blocker_class,
                &route_id,
                &target_digest,
                &receipt_digest,
                &write_scope_digest,
                &stable_text_digest(&format!(
                    "{}:{}:{}:{}",
                    plan.child_registry_digest, state.child_id, state.target, route_id
                )),
                blocker
                    .recovery_route
                    .as_deref()
                    .unwrap_or("child-lifecycle-owner"),
            ));
        }
    }
    inputs
}

fn program_retry_fingerprint_input(
    scope: &str,
    child_id: Option<&str>,
    blocker_class: &str,
    route_id: &str,
    target_digest: &str,
    receipt_digest: &str,
    write_scope_digest: &str,
    stable_digest_boundary: &str,
    recovery_owner: &str,
) -> ProgramRetryFingerprintInput {
    let current_fingerprint = stable_text_digest(&format!(
        "{scope}\n{}\n{blocker_class}\n{route_id}\n{target_digest}\n{receipt_digest}\n{write_scope_digest}\n{stable_digest_boundary}\n{recovery_owner}",
        child_id.unwrap_or("program")
    ));
    ProgramRetryFingerprintInput {
        scope: scope.to_string(),
        child_id: child_id.map(str::to_string),
        blocker_class: blocker_class.to_string(),
        route_id: route_id.to_string(),
        target_digest: target_digest.to_string(),
        receipt_digest: receipt_digest.to_string(),
        write_scope_digest: write_scope_digest.to_string(),
        stable_digest_boundary: stable_digest_boundary.to_string(),
        recovery_owner: recovery_owner.to_string(),
        current_fingerprint,
    }
}

fn parent_receipt_state_digest(receipts: &BTreeMap<String, ReceiptPlanState>) -> String {
    stable_text_digest(
        &receipts
            .iter()
            .map(|(receipt_id, receipt)| {
                format!(
                    "{receipt_id}:{}:{}:{}:{}:{}",
                    receipt.path,
                    receipt.exists,
                    receipt.verdict.as_deref().unwrap_or("none"),
                    receipt.current_digest.as_deref().unwrap_or("none"),
                    receipt.stored_digest.as_deref().unwrap_or("none")
                )
            })
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn program_resume_source_refs(
    checkpoint: &ProgramLifecycleCheckpoint,
    source_refs: &[ProgramCompactSourceRef],
    validation: &ProgramRoutingArtifactValidation,
) -> ProgramResumeSourceRefs {
    ProgramResumeSourceRefs {
        checkpoint_event_index: effective_checkpoint_event_index(checkpoint),
        checkpoint_event_sha256: checkpoint.latest_event_sha256.clone(),
        event_log_sha256: checkpoint.event_log_sha256.clone(),
        child_registry_digest: checkpoint.child_registry_digest.clone(),
        model_visible_context_sha256: validation.model_visible_context_sha256.clone(),
        source_refs: source_refs.to_vec(),
        unsafe_resume_behavior:
            "fail-closed when checkpoint event head, event log, child registry digest, source refs, or model-visible context digest cannot verify"
                .to_string(),
    }
}

fn program_delivery_handoff_evidence(
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
    validation: &ProgramRoutingArtifactValidation,
    route_decision_receipt_ref: &str,
) -> ProgramDeliveryHandoffEvidence {
    let requested_target_outcome = checkpoint
        .run_inputs
        .get(INPUT_TARGET_OUTCOME)
        .cloned()
        .unwrap_or_else(|| "not-requested".to_string());
    let no_blockers = plan.program_blockers.is_empty()
        && plan
            .child_states
            .values()
            .all(|state| state.blockers.is_empty());
    let all_required_terminal = plan
        .child_states
        .values()
        .filter(|state| state.required && !state.deferred)
        .all(|state| state.terminal_outcome.is_some());
    let readiness_state = if requested_target_outcome == "cleaned"
        && all_required_terminal
        && no_blockers
        && plan.program_route.is_none()
        && plan.runnable_batch.is_empty()
    {
        "handoff-input-ready".to_string()
    } else if requested_target_outcome == "cleaned" {
        "blocked-until-child-parent-delivery-gates-pass".to_string()
    } else {
        "not-requested".to_string()
    };
    ProgramDeliveryHandoffEvidence {
        requested_target_outcome,
        target_outcome_is_request_only: true,
        readiness_state,
        delivery_owner: "proposal-program-delivery".to_string(),
        route_decision_receipt_ref: route_decision_receipt_ref.to_string(),
        child_registry_digest: checkpoint.child_registry_digest.clone(),
        parent_receipts: program_parent_receipt_refs(plan),
        child_receipts: program_child_receipt_refs(plan),
        generated_freshness_status: program_generated_freshness_status(plan),
        forbidden_runner_claims: vec![
            "landing".to_string(),
            "sync".to_string(),
            "cleanup".to_string(),
            "branch-cleanup".to_string(),
            "terminal-proof".to_string(),
            "cleaned-claim".to_string(),
        ],
        authority_boundary_notice: format!(
            "runner may request target_outcome=cleaned as delivery input only; Proposal Program Delivery owns delivery mutation and final cleaned proof; model_visible_context_sha256={}",
            validation.model_visible_context_sha256
        ),
    }
}

fn program_parent_receipt_refs(
    plan: &ProgramLifecyclePlanResult,
) -> Vec<ProgramParentReceiptDigestRef> {
    plan.parent_receipt_states
        .iter()
        .filter_map(|(receipt_id, receipt)| {
            let sha256 = receipt
                .current_digest
                .clone()
                .or_else(|| receipt.stored_digest.clone())?;
            Some(ProgramParentReceiptDigestRef {
                receipt_id: receipt_id.clone(),
                receipt_ref: receipt.path.clone(),
                sha256,
            })
        })
        .collect()
}

fn program_child_receipt_refs(
    plan: &ProgramLifecyclePlanResult,
) -> Vec<ProgramChildReceiptDigestRef> {
    plan.child_states
        .values()
        .flat_map(|state| {
            state
                .receipt_digests
                .iter()
                .map(|(receipt_id, digest)| ProgramChildReceiptDigestRef {
                    receipt_id: format!("{}:{receipt_id}", state.child_id),
                    receipt_ref: child_receipt_ref(state, receipt_id),
                    sha256: digest.clone(),
                })
        })
        .collect()
}

fn program_generated_freshness_status(plan: &ProgramLifecyclePlanResult) -> String {
    let freshness_blocked = plan
        .program_blockers
        .iter()
        .chain(
            plan.child_states
                .values()
                .flat_map(|state| state.blockers.iter()),
        )
        .any(|blocker| {
            matches!(
                blocker.blocker_class.as_str(),
                "publication-drift" | "generated-freshness-drift"
            ) || blocker.message.contains("generated freshness")
        });
    if freshness_blocked {
        "blocked-or-stale".to_string()
    } else {
        "not-blocked-by-current-plan".to_string()
    }
}

fn program_blocker_disposition_label(blocker_class: &str) -> &'static str {
    match classify_program_blocker_class(blocker_class) {
        ProgramBlockerDisposition::Recoverable => "recoverable",
        ProgramBlockerDisposition::Human => "human-required",
        ProgramBlockerDisposition::Unsafe => "unsafe-fail-closed",
    }
}

fn program_route_bypass_guard(plan: &ProgramLifecyclePlanResult) -> String {
    if plan.program_route.is_some() && plan.runnable_batch.is_empty() {
        "parent-route-selected-child-dispatch-suppressed".to_string()
    } else if plan.program_route.is_none() && !plan.runnable_batch.is_empty() {
        "child-batch-selected-parent-route-absent".to_string()
    } else if plan.program_route.is_none() && plan.runnable_batch.is_empty() {
        "no-dispatch-selected".to_string()
    } else {
        "invalid-mixed-parent-and-child-route-selection".to_string()
    }
}

fn program_deterministic_preflights(plan: &ProgramLifecyclePlanResult) -> Vec<String> {
    let mut preflights = vec![
        "publication-freshness".to_string(),
        "generated-freshness".to_string(),
        "blocker-aggregation-zero-state".to_string(),
        "dependency-vector".to_string(),
        "manifest-completeness".to_string(),
        "registry-projection".to_string(),
        "raw-log-indexing".to_string(),
        "closeout-schema-validation".to_string(),
        "worktree-cleanliness".to_string(),
    ];
    if plan.program_gate_results.iter().any(|gate| !gate.passed) {
        preflights.push("program-gate-failure-observed".to_string());
    }
    preflights
}

fn program_model_route_for_step(
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
) -> String {
    if !program_escalation_triggers(plan).is_empty() {
        "high-on-escalation".to_string()
    } else if checkpoint.terminal_outcome.is_some()
        || plan.program_route.is_none() && plan.runnable_batch.is_empty()
    {
        "deterministic".to_string()
    } else if !plan.runnable_batch.is_empty() {
        "small".to_string()
    } else if !plan.program_blockers.is_empty()
        || plan
            .child_states
            .values()
            .any(|state| !state.blockers.is_empty())
    {
        "medium".to_string()
    } else {
        "deterministic".to_string()
    }
}

fn token_ceiling_for_model_route(
    model_route: &str,
    plan: &ProgramLifecyclePlanResult,
    checkpoint: &ProgramLifecycleCheckpoint,
) -> u64 {
    match model_route {
        "small" => CHILD_DISPATCH_BASE_TOKEN_CEILING,
        "medium" => RECOVERY_DELTA_NONZERO_BLOCKER_TOKEN_CEILING,
        "high" | "high-on-escalation" => ARCHITECTURE_EXCEPTION_TOKEN_CEILING,
        _ if checkpoint.terminal_outcome.is_some() => FINAL_COMPLETION_TOKEN_CEILING,
        _ if !plan.runnable_batch.is_empty() => CHILD_DISPATCH_BASE_TOKEN_CEILING,
        _ => PROGRAM_CONTEXT_CAPSULE_TOKEN_CEILING,
    }
}

fn program_escalation_triggers(plan: &ProgramLifecyclePlanResult) -> Vec<String> {
    let mut triggers = BTreeSet::new();
    for blocker in plan.program_blockers.iter().chain(
        plan.child_states
            .values()
            .flat_map(|state| state.blockers.iter()),
    ) {
        match blocker.blocker_class.as_str() {
            "authority-ambiguity"
            | "authority-zone-ambiguous"
            | "authority-boundary-ambiguous"
            | "protected-artifact-authority-ambiguity"
            | "scope-expansion" => {
                triggers.insert("authority ambiguity".to_string());
            }
            "validation-failed" => {
                triggers.insert("unexplained test failure".to_string());
            }
            "unsafe-resume" => {
                triggers.insert("rollback conflict".to_string());
            }
            "recovery-integrity-risk"
            | "recovery-budget-override-required"
            | "artifact-ownership-unclear"
            | "aggregate-closeout-readiness-missing" => {
                triggers.insert("archive/recovery failure".to_string());
            }
            "missing-evidence" => {
                triggers.insert("support-proof interpretation".to_string());
            }
            _ => {}
        }
        if blocker.message.contains("promotion evidence") {
            triggers.insert("promotion evidence conflict".to_string());
        }
        if blocker.message.contains("architecture") {
            triggers.insert("architecture decision".to_string());
        }
        if blocker.message.contains("rollback") {
            triggers.insert("rollback conflict".to_string());
        }
        if blocker.message.contains("support-proof") {
            triggers.insert("support-proof interpretation".to_string());
        }
    }
    triggers.into_iter().collect()
}

