    #[test]
    fn target_drift_explained_selects_rebaseline_once_then_exhausts_budget() {
        let program = program_with_rebaseline_checkpoint_action();
        let mut child_states = BTreeMap::new();
        child_states.insert(
            "a".to_string(),
            child_state("a", vec![blocker("target-drift-explained")]),
        );
        let plan = program_plan_with_children(child_states.clone(), vec![]);

        assert_eq!(
            select_program_recovery_action(&program, &plan, None),
            Some(("target-drift-explained", REBASELINE_CHECKPOINT_ACTION))
        );

        let mut used_actions = BTreeMap::new();
        used_actions.insert(
            program_recovery_action_attempt_key(
                "target-drift-explained",
                REBASELINE_CHECKPOINT_ACTION,
            ),
            1,
        );
        let checkpoint = checkpoint_from_plan(
            "target-drift-explained-budget",
            "proposal-program",
            "parent",
            ExecutorKind::Mock,
            "unattended",
            &BTreeMap::new(),
            &plan,
            &[],
            "blocked-recoverable",
            None,
            0,
            BTreeMap::new(),
            used_actions,
            BTreeMap::new(),
            BTreeMap::new(),
            Vec::new(),
        );

        assert!(select_program_recovery_action(&program, &plan, Some(&checkpoint)).is_none());

        let mut exhausted_children = child_states;
        let mut exhausted_program_blockers = Vec::new();
        apply_program_recovery_action_budget_blockers(
            &program,
            &mut exhausted_children,
            &mut exhausted_program_blockers,
            Some(&checkpoint),
        );
        let exhausted = exhausted_children
            .get("a")
            .unwrap()
            .blockers
            .first()
            .unwrap();
        assert_eq!(exhausted.blocker_class, "recovery-budget-override-required");
        assert!(exhausted.message.contains(REBASELINE_CHECKPOINT_ACTION));
    }

    #[test]
    fn retained_rebaseline_event_supersedes_stale_checkpoint_projection() {
        let _guard = crate::acquire_kernel_test_lock();
        let fixture = ProgramFixture::new("retained-rebaseline-event-supersedes", true);
        let program = program_with_rebaseline_checkpoint_action();
        let mut child_states = BTreeMap::new();
        child_states.insert(
            "a".to_string(),
            child_state("a", vec![blocker("target-drift-explained")]),
        );
        let plan = program_plan_with_children(child_states, vec![]);
        let checkpoint = checkpoint_from_plan(
            "retained-rebaseline-event-supersedes",
            "proposal-program",
            "parent",
            ExecutorKind::Mock,
            "unattended",
            &BTreeMap::new(),
            &plan,
            &[],
            "blocked-recoverable",
            None,
            0,
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            Vec::new(),
        );
        let control_root = fixture
            .octon_dir
            .join("state/control/execution/runs/retained-rebaseline-event-supersedes");
        let evidence_root = fixture
            .octon_dir
            .join("state/evidence/runs/workflows/retained-rebaseline-event-supersedes");
        append_program_event(
            &control_root,
            &evidence_root,
            "retained-rebaseline-event-supersedes",
            "plan-created",
            None,
            None,
            "stale checkpoint plan was written before recovery completion",
            event_data([("final_verdict", "partial")]),
        )
        .unwrap();
        append_program_event(
            &control_root,
            &evidence_root,
            "retained-rebaseline-event-supersedes",
            "program-recovery-action-finished",
            None,
            Some(REBASELINE_CHECKPOINT_ACTION),
            "program recovery action finished after stale checkpoint snapshot",
            event_data([
                ("blocker_class", "target-drift-explained"),
                ("action_id", REBASELINE_CHECKPOINT_ACTION),
                ("status", "completed"),
            ]),
        )
        .unwrap();

        let effective = checkpoint_with_retained_program_recovery_action_events(
            &control_root,
            Some(&checkpoint),
        )
        .unwrap()
        .unwrap();

        assert!(effective.child_states.is_empty());
        assert_eq!(
            program_recovery_action_attempt_count(
                Some(&effective),
                "target-drift-explained",
                REBASELINE_CHECKPOINT_ACTION,
            ),
            1
        );
        assert!(select_program_recovery_action(&program, &plan, Some(&effective)).is_none());
    }

    #[test]
    fn recovery_integrity_risk_selects_rebaseline_and_resets_matching_retry_state() {
        let program = program_with_recovery_integrity_rebaseline_action();
        let mut state = child_state("a", vec![blocker("recovery-integrity-risk")]);
        state.selected_route = Some(RoutePlanState {
            route_id: "promote-proposal".to_string(),
            route_type: "workflow".to_string(),
            command_id: None,
            skill_id: None,
            prompt_set_id: None,
        });
        let mut child_states = BTreeMap::new();
        child_states.insert("a".to_string(), state);
        let plan = program_plan_with_children(child_states, vec![]);

        assert_eq!(
            select_program_recovery_action(&program, &plan, None),
            Some(("recovery-integrity-risk", REBASELINE_CHECKPOINT_ACTION))
        );

        let child_results = vec![ProgramChildExecutionSummary {
            child_id: "a".to_string(),
            child_run_id: "recovery-integrity-risk-a".to_string(),
            route_id: "promote-proposal".to_string(),
            status: "failed".to_string(),
            attempts: 2,
            retryable: true,
            blocker_class: Some("executor-failed".to_string()),
            error_message: Some("validator failed before repair".to_string()),
            error_class: Some("executor-failed".to_string()),
            evidence_paths: Vec::new(),
            worktree_hygiene_foreign_fingerprint: None,
        }];
        let mut checkpoint = checkpoint_from_plan(
            "recovery-integrity-risk-rebaseline",
            "proposal-program",
            "parent",
            ExecutorKind::Mock,
            "unattended",
            &BTreeMap::new(),
            &plan,
            &child_results,
            "blocked-recoverable",
            None,
            0,
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            Vec::new(),
        );
        checkpoint.program_recovery_action_attempts.insert(
            program_recovery_action_attempt_key(
                "recovery-integrity-risk",
                REBASELINE_CHECKPOINT_ACTION,
            ),
            1,
        );
        let progress_key = recovery_progress_key("a", "promote-proposal", "executor-failed");
        assert!(checkpoint
            .recovery_progress_fingerprints
            .contains_key(&progress_key));
        assert_eq!(
            recovery_attempt_count(&checkpoint, "a", "executor-failed"),
            2
        );
        assert_eq!(
            select_program_recovery_action(&program, &plan, Some(&checkpoint)),
            Some(("recovery-integrity-risk", REBASELINE_CHECKPOINT_ACTION))
        );

        let rebased = checkpoint_for_recovery_action_replan(
            Some(&checkpoint),
            REBASELINE_CHECKPOINT_ACTION,
            "recovery-integrity-risk",
            &plan,
        )
        .unwrap();

        assert!(rebased.child_states.is_empty());
        assert!(!rebased
            .recovery_progress_fingerprints
            .contains_key(&progress_key));
        assert_eq!(recovery_attempt_count(&rebased, "a", "executor-failed"), 0);
        assert_eq!(
            program_recovery_action_attempt_count(
                Some(&rebased),
                "recovery-integrity-risk",
                REBASELINE_CHECKPOINT_ACTION
            ),
            0
        );
    }

